window.ORGANIC_DATA = {"chapters":[{"title":"第一章 绪论","questions":[{"type":"A","stem":"按路易斯酸碱理论，下列物质属于路易斯酸的是","options":{"A":"NH3","B":"BF3","C":"H2O","D":"OH-","E":"CH3NH2"},"answer":["B"],"rationale":"路易斯酸是能接受电子对的物质，BF3 中硼原子缺电子、有空轨道，可接受电子对，故为路易斯酸。","expl":{"A":"氨分子氮上有孤对电子，是电子对给予体，属路易斯碱。","B":"正确，BF3 的硼原子有空轨道，能接受电子对，是典型的路易斯酸。","C":"水分子氧上有孤对电子，可给出电子对，属路易斯碱。","D":"氢氧根是强电子对给予体，属路易斯碱。","E":"甲胺氮上有孤对电子，是路易斯碱而不是酸。"},"id":"org01_q01","chapter":"第一章 绪论","chapterIdx":0,"num":1},{"type":"A","stem":"与 CH3CH2CH2CH3 互为同分异构体的是","options":{"A":"2-甲基丁烷","B":"1-丁烯","C":"2-甲基丙烷","D":"1-丁醇","E":"环丁烷"},"answer":["C"],"rationale":"正丁烷分子式为 C4H10，2-甲基丙烷分子式同样是 C4H10，二者互为同分异构体，故选 C。","expl":{"A":"2-甲基丁烷分子式为 C5H12，碳原子数不同，不是同分异构体。","B":"1-丁烯分子式为 C4H8，氢原子数不同，不互为同分异构体。","C":"正确，2-甲基丙烷分子式也是 C4H10，与正丁烷互为同分异构体。","D":"1-丁醇含氧，分子式为 C4H10O，与丁烷不互为同分异构体。","E":"环丁烷分子式为 C4H8，比丁烷少两个氢，故不互为同分异构体。"},"id":"org01_q02","chapter":"第一章 绪论","chapterIdx":0,"num":2},{"type":"A","stem":"共价键发生均裂时生成的活性中间体是","options":{"A":"正、负离子","B":"自由基","C":"碳正离子","D":"碳负离子","E":"络合物"},"answer":["B"],"rationale":"均裂时成键的一对电子平均分给两个片段，各带一个未成对电子，生成自由基，故选 B。","expl":{"A":"正负离子是异裂的产物，成键电子对完全转移给其中一方，与均裂不同。","B":"正确，均裂使每个片段各得一个电子，生成自由基。","C":"碳正离子由异裂产生，属于离子型中间体，不是均裂产物。","D":"碳负离子同样来自异裂，与均裂无关。","E":"络合物是配位作用形成的，与共价键断裂方式无关。"},"id":"org01_q03","chapter":"第一章 绪论","chapterIdx":0,"num":3},{"type":"A","stem":"下列基团中不属于官能团的是","options":{"A":"-OH","B":"-COOH","C":"-CHO","D":"-CH3","E":"-NH2"},"answer":["D"],"rationale":"官能团是决定化合物主要化学性质的原子或基团，甲基只是烃基骨架的一部分，不属于官能团。","expl":{"A":"羟基是醇和酚的官能团，决定其化学性质，属官能团。","B":"羧基是羧酸的官能团，属官能团。","C":"醛基是醛的官能团，决定醛的还原性与加成性，属官能团。","D":"正确，甲基只是烷基，不能决定特征化学性质，不是官能团。","E":"氨基是胺的官能团，能决定胺的碱性和成盐性质，故属于官能团。"},"id":"org01_q04","chapter":"第一章 绪论","chapterIdx":0,"num":4},{"type":"A","stem":"下列反应属于消除反应的是","options":{"A":"苯与浓硝酸、浓硫酸共热","B":"乙烷与氯气在光照下反应","C":"乙烯与溴的四氯化碳溶液反应","D":"乙醛与 HCN 加成生成氰醇","E":"乙醇在浓硫酸中 170 摄氏度脱水生成乙烯"},"answer":["E"],"rationale":"乙醇分子内脱去一分子水并形成新的 π 键，是典型的消除反应，故选 E。","expl":{"A":"苯的硝化是芳香环上的亲电取代反应。","B":"乙烷与氯气光照是自由基取代反应，不是消除反应。","C":"乙烯与溴发生亲电加成，属加成反应。","D":"醛与 HCN 是亲核加成反应，不是消除反应。","E":"正确，乙醇在浓硫酸中分子内脱水生成乙烯，属消除反应。"},"id":"org01_q05","chapter":"第一章 绪论","chapterIdx":0,"num":5},{"type":"A","stem":"下列试剂在有机反应中作为亲电试剂的是","options":{"A":"H+","B":"H2O","C":"CN-","D":"NH3","E":"RO-"},"answer":["A"],"rationale":"亲电试剂是能接受电子对、进攻富电子中心的试剂，通常是正离子或带空轨道的分子。H+ 无电子而带正电荷，可接受电子对，是最简单的亲电试剂；H2O、CN-、NH3、RO- 都带有孤对电子，属于亲核试剂。","expl":{"A":"正确，质子只有空轨道、能接受电子对，是典型的亲电试剂。","B":"水分子氧上有孤对电子，能进攻缺电子的碳原子，是亲核试剂。","C":"氰离子带负电荷并有孤对电子，是强亲核试剂。","D":"氨分子氮上有孤对电子，作为亲核试剂进攻卤代烃等底物。","E":"烷氧负离子既是强碱又是强亲核试剂，不具有亲电性。"},"id":"org01_q06","chapter":"第一章 绪论","chapterIdx":0,"num":6},{"type":"A","stem":"下列分子中属于极性分子的是","options":{"A":"I2","B":"CCl4","C":"CH2Cl2","D":"CH4","E":"CO2"},"answer":["C"],"rationale":"分子有无极性取决于键的极性和分子构型是否对称。CH2Cl2 为四面体形，两个 C-Cl 键的极性不能相互抵消，分子有偶极矩；I2、CCl4、CH4、CO2 的键极性因对称排列而抵消，偶极矩为零。","expl":{"A":"碘分子由同种原子成键，键无极性，分子也无偶极矩。","B":"四氯化碳为四面体形，四个 C-Cl 键极性完全对称抵消，是非极性分子。","C":"正确，二氯甲烷构型不对称，C-Cl 键极性不能抵消，故为极性分子。","D":"甲烷四个 C-H 键对称排列，键矩相互抵消，属非极性分子。","E":"二氧化碳为直线形，两个 C=O 键方向相反、键矩抵消，偶极矩为零。"},"id":"org01_q07","chapter":"第一章 绪论","chapterIdx":0,"num":7},{"type":"A","stem":"下列反应中属于亲核取代反应的是","options":{"A":"溴乙烷与氢氧化钠水溶液共热生成乙醇","B":"甲烷与氯气在光照下生成氯甲烷","C":"苯与浓硝酸、浓硫酸共热生成硝基苯","D":"乙烯与溴的四氯化碳溶液反应","E":"乙醇在浓硫酸中加热脱水生成乙烯"},"answer":["A"],"rationale":"亲核取代是亲核试剂进攻带部分正电荷的碳原子并取代离去基团的反应。溴乙烷水解时 OH- 进攻与溴相连的碳并取代 Br-，属亲核取代；其余依次为自由基取代、亲电取代、亲电加成和消除反应。","expl":{"A":"正确，OH- 作为亲核试剂取代溴原子，是典型的亲核取代（水解）反应。","B":"光照下氯分子均裂成自由基，甲烷的氢被自由基夺取，属自由基取代。","C":"苯环上的氢被 NO2+ 取代，属亲电取代反应。","D":"溴与双键加成、打开 π 键，属亲电加成反应。","E":"乙醇分子内脱去一分子水形成双键，属消除反应。"},"id":"org01_q08","chapter":"第一章 绪论","chapterIdx":0,"num":8},{"type":"A","stem":"1828 年维勒由无机物合成尿素，打破了有机物只能由生命体产生的旧观念，他所用的原料是","options":{"A":"碳酸铵","B":"醋酸铵","C":"氰化铵","D":"氰酸铵","E":"草酸铵"},"answer":["D"],"rationale":"维勒加热氰酸铵（NH4OCN）时发生重排，得到原本只能由生命体产生的尿素 CO(NH2)2，这是第一个人工合成的有机物，说明有机物与无机物之间没有不可逾越的界限。","expl":{"A":"碳酸铵受热分解为氨和二氧化碳，不能生成尿素。","B":"醋酸铵受热脱水生成乙酰胺，与尿素的合成无关。","C":"氰化铵并不是维勒实验所用的原料，受热也不生成尿素。","D":"正确，氰酸铵受热重排为尿素，开创了人工合成有机物的先例。","E":"草酸铵受热分解，产物中不含尿素。"},"id":"org01_q09","chapter":"第一章 绪论","chapterIdx":0,"num":9}]},{"title":"第二章 有机化合物的化学键","questions":[{"type":"A","stem":"下列分子中碳原子为 sp 杂化的是","options":{"A":"甲烷","B":"乙烯","C":"乙炔","D":"苯","E":"乙烷"},"answer":["C"],"rationale":"乙炔的两个碳原子均为 sp 杂化，两个 p 轨道侧面重叠形成两个 π 键，分子呈直线形，故答案为 C。","expl":{"A":"甲烷中碳为 sp3 杂化，呈正四面体结构，不是 sp 杂化。","B":"乙烯中碳为 sp2 杂化，分子为平面三角形，不是 sp 杂化。","C":"正确，乙炔碳为 sp 杂化，两个未杂化 p 轨道形成两个 π 键，分子为直线形。","D":"苯环碳为 sp2 杂化，形成闭合大 π 键，不是 sp 杂化。","E":"乙烷中碳为 sp3 杂化，可绕 C-C 键自由旋转，不是 sp 杂化。"},"id":"org02_q01","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":1},{"type":"A","stem":"下列关于 σ 键和 π 键的叙述，正确的是","options":{"A":"σ 键只能由两个 s 轨道重叠形成","B":"π 键的电子云沿键轴呈圆柱形对称分布","C":"σ 键的键能总是小于 π 键","D":"乙烯分子中的 C=C 由两个 σ 键构成","E":"π 键由 p 轨道肩并肩重叠形成，重叠程度小于 σ 键"},"answer":["E"],"rationale":"π 键由两个平行 p 轨道侧面重叠形成，电子云分布在键轴上下方，重叠程度小于 σ 键，故 E 正确。","expl":{"A":"σ 键可由 s-s、s-p、p-p 等多种轨道重叠形成，并非只能由两个 s 轨道形成。","B":"π 键电子云在键轴上下两侧，呈块状分布，只有 σ 键才是轴对称的。","C":"一般 π 键重叠程度小、键能小于 σ 键，该选项说法与事实相反。","D":"乙烯的 C=C 由一个 σ 键和一个 π 键组成，不是两个 σ 键。","E":"正确，π 键由 p 轨道肩并肩重叠形成，重叠程度小，键能低于 σ 键。"},"id":"org02_q02","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":2},{"type":"A","stem":"下列基团中，吸电子诱导效应（-I 效应）最强的是","options":{"A":"-F","B":"-Cl","C":"-Br","D":"-I","E":"-CH3"},"answer":["A"],"rationale":"卤素的吸电子诱导效应随电负性增大而增强，氟电负性最大，故 -I 效应最强，选 A。","expl":{"A":"正确，氟的电负性在卤素中最大，吸电子诱导效应最强。","B":"氯的电负性小于氟，其 -I 效应弱于氟，故不是最强。","C":"溴的电负性更小，-I 效应弱于氯和氟，故错误。","D":"碘的电负性最小，在卤素中 -I 效应最弱，故错误。","E":"甲基是推电子基，表现为 +I 效应，与题意相反。"},"id":"org02_q03","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":3},{"type":"A","stem":"下列化合物中不存在共轭体系的是","options":{"A":"CH2=CH-CH=CH2","B":"CH2=CH-Cl","C":"Ph-OH","D":"CH3CH=CH-CHO","E":"CH3CH2CH3"},"answer":["E"],"rationale":"丙烷分子中碳碳之间只有 σ 键，没有 p 轨道参与的重叠，不存在共轭体系，故答案为 E。","expl":{"A":"1,3-丁二烯的两个双键共轭，形成 π-π 共轭体系，故存在共轭。","B":"氯原子的 p 轨道与双键 π 键形成 p-π 共轭，存在共轭体系。","C":"苯酚中氧的 p 轨道与苯环大 π 键形成 p-π 共轭，存在共轭。","D":"2-丁烯醛的双键与羰基形成 π-π 共轭，存在共轭体系。","E":"正确，丙烷只有 σ 键，无任何共轭，故选 E。"},"id":"org02_q04","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":4},{"type":"A","stem":"下列碳碳键中键长最短的是","options":{"A":"乙烷中的 C-C","B":"丙烷中的 C-C","C":"乙烯中的 C=C","D":"乙炔中的 C≡C","E":"苯环中的碳碳键"},"answer":["D"],"rationale":"键级越高键长越短，乙炔碳碳三键键级为 3，键长约 0.120 nm，是其中最短的。","expl":{"A":"乙烷 C-C 单键键长约 0.154 nm，明显长于三键。","B":"丙烷 C-C 也是单键，键长与乙烷相近，不是最短。","C":"乙烯 C=C 双键键长约 0.134 nm，比三键长。","D":"正确，乙炔 C≡C 三键键级最高，键长约 0.120 nm，为最短。","E":"苯环碳碳键长约 0.139 nm，介于单双键之间，长于三键。"},"id":"org02_q05","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":5},{"type":"X","stem":"下列关于共价键的叙述，正确的有","options":{"A":"σ 键可以绕键轴自由旋转","B":"π 键不能绕键轴自由旋转","C":"两个原子间形成单键时一定形成 σ 键","D":"双键由一个 σ 键和一个 π 键组成","E":"π 键比 σ 键牢固，不易断裂"},"answer":["A","B","C","D"],"rationale":"σ 键轴对称可旋转，π 键不能旋转；单键为 σ 键，双键为 σ 键加 π 键，故 ABCD 正确。","expl":{"A":"正确，σ 键电子云绕键轴轴对称，旋转不改变重叠状态。","B":"正确，π 键若绕键轴旋转会破坏 p 轨道侧面重叠，故不能自由旋转。","C":"正确，任何共价单键都至少含一个 σ 键，由轨道头碰头重叠形成。","D":"正确，双键通常由一个 σ 键和一个 π 键共同组成。","E":"错误，π 键重叠程度小、键能低，比 σ 键更容易断裂。"},"id":"org02_q06","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":6},{"type":"X","stem":"下列化合物中，碳原子存在 sp2 杂化的有","options":{"A":"乙烯","B":"苯","C":"甲醛","D":"乙炔","E":"甲烷"},"answer":["A","B","C"],"rationale":"乙烯、苯、甲醛中的碳原子均为 sp2 杂化，乙炔碳为 sp 杂化，甲烷碳为 sp3 杂化，故选 ABC。","expl":{"A":"正确，乙烯双键碳为 sp2 杂化，分子呈平面三角形。","B":"正确，苯环每个碳原子均为 sp2 杂化，形成闭合大 π 键。","C":"正确，甲醛羰基碳为 sp2 杂化，分子为平面结构。","D":"错误，乙炔碳原子为 sp 杂化，分子呈直线形。","E":"错误，甲烷碳原子为 sp3 杂化，呈正四面体结构。"},"id":"org02_q07","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":7},{"type":"A","stem":"乙烯分子中两个碳原子之间的 σ 键是由下列哪类轨道重叠形成的","options":{"A":"两个 p 轨道肩并肩重叠","B":"两个 sp2 杂化轨道头碰头重叠","C":"一个 sp2 杂化轨道与一个 p 轨道重叠","D":"一个 s 轨道与一个 sp2 杂化轨道重叠","E":"两个 sp3 杂化轨道头碰头重叠"},"answer":["B"],"rationale":"乙烯的两个双键碳都是 sp2 杂化，各用一个 sp2 杂化轨道沿键轴头碰头重叠形成 C-C σ 键，未参与杂化的两个 p 轨道侧面重叠形成 π 键，因此 C=C 由一个 σ 键和一个 π 键组成。","expl":{"A":"p 轨道肩并肩重叠形成的是 π 键，重叠程度小且不能绕键轴旋转。","B":"正确，C-C σ 键由两个 sp2 杂化轨道头碰头重叠而成。","C":"sp2 与 p 轨道重叠不能构成 C-C σ 键，乙烯中不存在这种组合。","D":"s 与 sp2 重叠是 C-H σ 键的形成方式，不是碳碳之间的键。","E":"sp3 杂化碳出现在烷烃中，乙烯的碳不是 sp3 杂化。"},"id":"org02_q08","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":8},{"type":"A","stem":"下列化合物中能形成分子内氢键的是","options":{"A":"对硝基苯酚","B":"苯酚","C":"乙醇","D":"邻硝基苯酚","E":"甲苯"},"answer":["D"],"rationale":"形成分子内氢键要求给氢基团与受氢基团在空间上足够接近。邻硝基苯酚的酚羟基与邻位硝基的氧相距很近，可形成六元环状分子内氢键；对硝基苯酚的两个基团相距太远，只能形成分子间氢键。","expl":{"A":"对位取代使羟基与硝基相距很远，不能形成分子内氢键，只形成分子间氢键。","B":"苯酚羟基周围没有合适的受氢基团，形成的是分子间氢键。","C":"乙醇分子只有一个氧原子，只能形成分子间氢键。","D":"正确，邻硝基苯酚中羟基与邻位硝基距离近，可形成分子内氢键。","E":"甲苯既无羟基也无强电负性原子，不能形成氢键。"},"id":"org02_q09","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":9},{"type":"A","stem":"下列基团中，对苯环主要表现为给电子的共轭效应（+C 效应）的是","options":{"A":"-OH","B":"-NO2","C":"-CN","D":"-COOH","E":"-CHO"},"answer":["A"],"rationale":"羟基氧上的孤对电子与苯环的大 π 键形成 p-π 共轭，电子向环内转移，表现为给电子的 +C 效应；硝基、氰基、羧基、醛基的 π 键与苯环共轭时都从环上吸走电子，表现为 -C 效应。","expl":{"A":"正确，氧的孤对电子参与共轭并给电子，是强给电子的 +C 基团。","B":"硝基中氮带正电、氧电负性大，通过共轭强烈吸电子，属 -C 基团。","C":"氰基的 C≡N 与苯环共轭时吸电子，表现为 -C 效应。","D":"羧基的羰基与苯环共轭吸电子，属 -C 效应。","E":"醛基的羰基通过共轭从环上吸电子，属 -C 效应。"},"id":"org02_q10","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":10},{"type":"A","stem":"下列化合物中偶极矩最大的是","options":{"A":"CH3CH3","B":"CH4","C":"CH3CH2Cl","D":"CH2=CHCl","E":"HC≡CCl"},"answer":["C"],"rationale":"氯乙烯、氯乙炔中氯的 p 轨道与 π 键发生 p-π 共轭，电子向双键方向转移，使 C-Cl 键的极性减弱、偶极矩变小；氯乙烷中氯只表现吸电子诱导效应，偶极矩最大。乙烷、甲烷分子对称，偶极矩为零。","expl":{"A":"乙烷分子对称，键的极性相互抵消，偶极矩为零。","B":"甲烷为正四面体，键矩完全抵消，偶极矩为零。","C":"正确，氯乙烷中只有氯的吸电子诱导效应，偶极矩在五个化合物中最大。","D":"氯乙烯中氯与双键共轭，C-Cl 键极性减弱，偶极矩小于氯乙烷。","E":"氯乙炔中共轭使 C-Cl 键极性进一步减弱，偶极矩最小。"},"id":"org02_q11","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":11}]},{"title":"第三章 烷烃","questions":[{"type":"A","stem":"化合物 CH3CH(CH3)CH2CH2CH3 的正确系统名称是","options":{"A":"2-甲基戊烷","B":"3-甲基戊烷","C":"2-甲基己烷","D":"正己烷","E":"4-甲基戊烷"},"answer":["A"],"rationale":"选择含取代基最多的最长碳链为戊烷，从靠近支链一端编号，甲基在 2 位，故为 2-甲基戊烷。","expl":{"A":"正确，主链 5 个碳，从靠近甲基一端编号，甲基位于 2 位，为 2-甲基戊烷。","B":"若从另一端编号甲基才在 4 位，应取较小位次，故不是 3-甲基戊烷。","C":"主链只有 5 个碳原子，不是己烷，故错。","D":"分子中有支链甲基，不是直链的正己烷。","E":"编号应使取代基位次最小，称为 2-甲基戊烷而非 4-甲基戊烷。"},"id":"org03_q01","chapter":"第三章 烷烃","chapterIdx":2,"num":1},{"type":"A","stem":"乙烷分子中最稳定的构象是","options":{"A":"重叠式","B":"半交叉式","C":"全重叠式","D":"部分重叠式","E":"交叉式"},"answer":["E"],"rationale":"乙烷的交叉式构象中前后氢原子相距最远，扭转张力与空间排斥最小，能量最低，最稳定。","expl":{"A":"重叠式中前后氢原子相互靠近，存在较大排斥与扭转张力，能量较高。","B":"半交叉式并不是乙烷的稳定构象，其能量高于交叉式。","C":"全重叠式是重叠式中能量最高的构象，最不稳定。","D":"部分重叠式仍属重叠式，存在较大排斥，能量不最低。","E":"正确，交叉式构象中氢原子交替排列、距离最远，能量最低最稳定。"},"id":"org03_q02","chapter":"第三章 烷烃","chapterIdx":2,"num":2},{"type":"A","stem":"正丁烷绕 C2-C3 键旋转时，能量最低的构象是","options":{"A":"全重叠式","B":"部分重叠式","C":"邻位交叉式","D":"对位交叉式","E":"半重叠式"},"answer":["D"],"rationale":"对位交叉式中两个甲基相距最远，空间排斥最小，是正丁烷能量最低的构象。","expl":{"A":"全重叠式两个甲基相互重叠，排斥最大，能量最高。","B":"部分重叠式的甲基与氢重叠，能量高于交叉式。","C":"邻位交叉式的两个甲基相距较近，仍有较大排斥，能量高于对位交叉式。","D":"正确，对位交叉式两个甲基处于对位，相距最远，能量最低。","E":"半重叠式不是丁烷的典型稳定构象，其能量高于交叉式。"},"id":"org03_q03","chapter":"第三章 烷烃","chapterIdx":2,"num":3},{"type":"A","stem":"甲烷与氯气在光照下生成氯甲烷的反应属于","options":{"A":"亲电取代","B":"亲核取代","C":"自由基取代","D":"亲电加成","E":"消除反应"},"answer":["C"],"rationale":"光照使氯气均裂产生氯自由基，引发链反应，甲烷的氢被逐步取代，属自由基取代反应。","expl":{"A":"亲电取代常见于芳香环，由亲电试剂进攻，与本题机理不同。","B":"亲核取代发生在 sp3 碳上由亲核试剂进攻，本反应无亲核试剂。","C":"正确，光照下氯分子均裂成自由基，反应按链式自由基取代进行。","D":"加成反应会打开 π 键，甲烷为饱和烃无 π 键，不能加成。","E":"消除反应生成不饱和键，本反应只发生氢被取代。"},"id":"org03_q04","chapter":"第三章 烷烃","chapterIdx":2,"num":4},{"type":"A","stem":"2-甲基丁烷与溴在光照下反应，主要产物是","options":{"A":"1-溴-2-甲基丁烷","B":"2-溴-2-甲基丁烷","C":"2-溴-3-甲基丁烷","D":"1-溴-3-甲基丁烷","E":"2-溴丁烷"},"answer":["B"],"rationale":"溴代反应选择性高，优先取代最活泼的叔氢，2-位碳上的氢为叔氢，故主要生成 2-溴-2-甲基丁烷。","expl":{"A":"1-溴产物需取代伯氢，伯氢活性最低，只能得到少量。","B":"正确，2-位碳为叔碳，其氢最活泼，溴代主要发生在该位置。","C":"该结构即 2-甲基-3-溴丁烷，溴连在仲碳上，活性低于叔氢，生成量很少。","D":"取代另一端伯氢生成量极少，不是主要产物。","E":"分子骨架不会在取代中改变，不能生成 2-溴丁烷。"},"id":"org03_q05","chapter":"第三章 烷烃","chapterIdx":2,"num":5},{"type":"A","stem":"烷烃自由基取代反应中，不同类型氢原子的活性顺序是","options":{"A":"伯氢 > 仲氢 > 叔氢","B":"叔氢 > 仲氢 > 伯氢","C":"仲氢 > 叔氢 > 伯氢","D":"伯氢 > 叔氢 > 仲氢","E":"三者活性相同"},"answer":["B"],"rationale":"叔自由基最稳定，形成的过渡态能量最低，故叔氢最活泼，活性顺序为叔大于仲大于伯。","expl":{"A":"伯自由基最不稳定，伯氢活性最低，该项顺序颠倒。","B":"正确，叔自由基受三个烷基稳定化，最稳定，故叔氢最活泼。","C":"仲氢活性低于叔氢，顺序不正确。","D":"叔氢应排在首位，该项把伯氢排在前面，错误。","E":"三类氢的活性差异明显，溴代时选择性尤其突出，不可能相同。"},"id":"org03_q06","chapter":"第三章 烷烃","chapterIdx":2,"num":6},{"type":"A","stem":"下列烷烃中，一氯代产物只有一种的是","options":{"A":"丙烷","B":"正丁烷","C":"2-甲基丙烷","D":"2,2-二甲基丙烷","E":"正己烷"},"answer":["D"],"rationale":"2,2-二甲基丙烷分子中 12 个氢完全等同，一氯代只生成一种产物，故选 D。","expl":{"A":"丙烷有一氯取代在 1 位和 2 位两种产物，不符合题意。","B":"正丁烷的 1 位和 2 位氢不同，可得两种一氯代产物。","C":"2-甲基丙烷有叔氢与伯氢两类，可生成两种一氯代产物。","D":"正确，2,2-二甲基丙烷四个甲基完全等同，只有一种一氯代产物。","E":"正己烷有 1、2、3 位三类氢，一氯代产物多于一种。"},"id":"org03_q07","chapter":"第三章 烷烃","chapterIdx":2,"num":7},{"type":"X","stem":"关于烷烃的自由基取代反应，下列说法正确的有","options":{"A":"反应经过自由基中间体","B":"光照或加热可以引发反应","C":"反应常存在诱导期","D":"加入少量氧气会延缓反应","E":"反应按离子型机理进行"},"answer":["A","B","C","D"],"rationale":"烷烃卤代是自由基链反应，需光照或加热引发，存在诱导期，氧气作为自由基捕获剂会阻抑反应。","expl":{"A":"正确，反应经氯自由基夺氢形成烷基自由基等自由基中间体。","B":"正确，光照或高温可使卤素分子均裂产生自由基，从而引发链反应。","C":"正确，引发阶段自由基浓度积累需要时间，故常出现诱导期。","D":"正确，氧气是自由基捕获剂，能与自由基结合而延缓反应。","E":"错误，该反应是自由基型链反应，不是离子型机理。"},"id":"org03_q08","chapter":"第三章 烷烃","chapterIdx":2,"num":8},{"type":"A","stem":"下列 C6H14 异构体中沸点最低的是","options":{"A":"正己烷","B":"2-甲基戊烷","C":"3-甲基戊烷","D":"2,2-二甲基丁烷","E":"2,3-二甲基丁烷"},"answer":["D"],"rationale":"同分异构的烷烃支链越多，分子越接近球形，分子间有效接触面积越小，色散力越弱，沸点越低。2,2-二甲基丁烷支链最多且含季碳、分子最接近球形，在 C6H14 各异构体中沸点最低。","expl":{"A":"正己烷是直链烷烃，分子间接触面积最大，沸点最高。","B":"2-甲基戊烷只有一个支链，沸点高于二甲基取代物。","C":"3-甲基戊烷也只有一个支链，沸点高于带两个支链的异构体。","D":"正确，2,2-二甲基丁烷支链最多、分子最接近球形，沸点最低。","E":"2,3-二甲基丁烷虽有两个支链，但分子不如 2,2-二甲基丁烷那样紧凑，沸点稍高。"},"id":"org03_q09","chapter":"第三章 烷烃","chapterIdx":2,"num":9},{"type":"A","stem":"氟、氯、溴与烷烃发生自由基取代反应时，对不同类型的氢选择性最高的是","options":{"A":"溴","B":"氯","C":"氟","D":"碘","E":"三者选择性相同"},"answer":["A"],"rationale":"卤素夺氢的选择性取决于反应放热程度：反应越放热，过渡态越早、越接近反应物，对三类氢的差别体现得越少。溴代反应放热最少，过渡态最接近产物，故对叔、仲、伯氢的选择性最高。","expl":{"A":"正确，溴代反应的过渡态最接近产物，对三类氢的活性差别反映最充分，选择性最高。","B":"氯代反应放热较多、过渡态较早，选择性低于溴。","C":"氟代反应极其剧烈、放热很大，几乎无选择性，常导致碳链断裂。","D":"碘代反应很难进行，一般不用于讨论氢的选择性。","E":"不同卤素的选择性差别很大，溴最高而氟最低，不可能相同。"},"id":"org03_q10","chapter":"第三章 烷烃","chapterIdx":2,"num":10},{"type":"A","stem":"下列化合物绕碳碳单键旋转时，需要克服的能垒最大的是","options":{"A":"CH3CH3","B":"CH2ClCH2Br","C":"CH2ICH2I","D":"CH2ClCH2Cl","E":"CH2ClCH2I"},"answer":["C"],"rationale":"绕 C-C 键旋转的能垒主要来自重叠式构象中大基团之间的空间排斥和极性排斥。取代基体积越大，重叠式时相互排斥越强，旋转所需克服的能垒越大；碘原子体积最大，故 CH2ICH2I 的旋转能垒最大。","expl":{"A":"乙烷的重叠式只有氢与氢之间的排斥，能垒最小。","B":"氯与溴体积中等，重叠式排斥小于两个碘原子。","C":"正确，两个碘原子体积最大，重叠式排斥最强，旋转能垒最大。","D":"两个氯体积小于碘，能垒小于碘代物。","E":"氯与碘组合的排斥小于两个碘原子之间的排斥。"},"id":"org03_q11","chapter":"第三章 烷烃","chapterIdx":2,"num":11},{"type":"A","stem":"分子式为 C5H12 的烷烃中，一氯代产物有三种的是","options":{"A":"正戊烷","B":"2-甲基丁烷","C":"2,2-二甲基丙烷","D":"环戊烷","E":"不存在这种烷烃"},"answer":["A"],"rationale":"正戊烷分子中有 1 位、2 位、3 位三类不同环境的氢，一氯代只能生成 1-氯戊烷、2-氯戊烷和 3-氯戊烷三种产物；2-甲基丁烷有四种氢，2,2-二甲基丙烷只有一种氢。","expl":{"A":"正确，正戊烷有 1、2、3 位三类氢，一氯代物共三种。","B":"2-甲基丁烷有伯氢、叔氢和两类亚甲基氢，一氯代物共四种。","C":"2,2-二甲基丙烷的十二个氢完全等同，一氯代物只有一种。","D":"环戊烷分子式为 C5H10，不符合题设分子式的前提。","E":"分子式为 C5H12 的烷烃有三种，确实存在一氯代物为三种的正戊烷。"},"id":"org03_q12","chapter":"第三章 烷烃","chapterIdx":2,"num":12}]},{"title":"第四章 烯烃","questions":[{"type":"A","stem":"化合物 (CH3)2C=CHCH3 的正确系统名称是","options":{"A":"2-戊烯","B":"3-甲基-2-丁烯","C":"2-甲基-1-丁烯","D":"2-甲基-2-丁烯","E":"3-甲基-1-丁烯"},"answer":["D"],"rationale":"选择含双键的最长碳链为丁烯，双键位于 2 位，甲基也在 2 位，故名称为 2-甲基-2-丁烯。","expl":{"A":"主链只有 4 个碳且含支链，不能命名为 2-戊烯。","B":"甲基实际连在双键碳上，编号后应为 2 位而不是 3 位。","C":"双键位于 2 位而不是 1 位，故名称不符。","D":"正确，主链 4 个碳，双键在 2 位，甲基也在 2 位，得 2-甲基-2-丁烯。","E":"双键不在端位，也不是 1-丁烯的衍生物。"},"id":"org04_q01","chapter":"第四章 烯烃","chapterIdx":3,"num":1},{"type":"A","stem":"下列化合物中存在顺反异构的是","options":{"A":"CH2=CH2","B":"CH3CH=CH2","C":"CH3CH=CHCH3","D":"(CH3)2C=CH2","E":"CH3CH2CH=CH2"},"answer":["C"],"rationale":"顺反异构要求双键两端每个碳上连有两个不同的基团，2-丁烯的两个双键碳各连氢和甲基，故有顺反异构。","expl":{"A":"乙烯两个双键碳上各连两个相同的氢，不存在顺反异构。","B":"丙烯端位双键碳上连两个相同的氢，无顺反异构。","C":"正确，2-丁烯两端碳各连 H 与 CH3，存在顺式和反式两种构型。","D":"该化合物同一碳上连有两个相同的甲基，不存在顺反异构。","E":"1-丁烯端位碳连两个氢，不能形成顺反异构。"},"id":"org04_q02","chapter":"第四章 烯烃","chapterIdx":3,"num":2},{"type":"A","stem":"按次序规则，下列基团优先次序最高的是","options":{"A":"-CH3","B":"-Cl","C":"-OH","D":"-Br","E":"-H"},"answer":["D"],"rationale":"次序规则按直接相连原子序数由大到小排列，溴的原子序数最大，故 -Br 优先次序最高。","expl":{"A":"甲基直接相连的是碳，原子序数小于卤素和氧，优先次序靠后。","B":"氯的原子序数为 17，小于溴的 35，故低于溴。","C":"羟基直接相连的是氧，原子序数 8，低于氯和溴。","D":"正确，溴的原子序数 35 最大，按次序规则优先次序最高。","E":"氢的原子序数最小，在所有基团中优先次序最低。"},"id":"org04_q03","chapter":"第四章 烯烃","chapterIdx":3,"num":3},{"type":"A","stem":"乙烯与溴加成反应中生成的关键中间体是","options":{"A":"碳正离子","B":"溴鎓离子","C":"自由基","D":"碳负离子","E":"卡宾"},"answer":["B"],"rationale":"溴分子与乙烯先形成三元环状的溴鎓离子，再由溴离子从背面开环进攻，故关键中间体是溴鎓离子。","expl":{"A":"溴加成不生成普通碳正离子，若生成碳正离子会发生重排，实际上很少。","B":"正确，溴与乙烯先形成环状溴鎓离子，再受溴离子背面进攻开环。","C":"自由基不是溴与烯烃亲电加成的中间体，属自由基加成机理。","D":"碳负离子通常出现在亲核加成中，与溴的亲电加成无关。","E":"卡宾用于环丙烷化反应，与本反应无关。"},"id":"org04_q04","chapter":"第四章 烯烃","chapterIdx":3,"num":4},{"type":"A","stem":"丙烯与 HBr 加成的主要产物是","options":{"A":"2-溴丙烷","B":"1-溴丙烷","C":"1,2-二溴丙烷","D":"2,2-二溴丙烷","E":"3-溴丙烯"},"answer":["A"],"rationale":"按马氏规则，氢加在含氢较多的端位碳上，生成更稳定的仲碳正离子，故主要产物为 2-溴丙烷。","expl":{"A":"正确，H 加到端位碳形成仲碳正离子，溴加到中间碳上，得 2-溴丙烷。","B":"1-溴丙烷是反马氏产物，仅在过氧化物存在时 HBr 加成才为主。","C":"反应只加成 1 分子 HBr，不会生成二溴代物。","D":"两个溴加在同一碳上不符合加成规律，不能生成。","E":"加成后双键打开，不会保留双键生成溴丙烯。"},"id":"org04_q05","chapter":"第四章 烯烃","chapterIdx":3,"num":5},{"type":"A","stem":"丙烯在过氧化物存在下与 HBr 反应的主要产物是","options":{"A":"2-溴丙烷","B":"1,2-二溴丙烷","C":"1-溴丙烷","D":"2,2-二溴丙烷","E":"不反应"},"answer":["C"],"rationale":"过氧化物引发自由基链反应，溴自由基加到含氢较多的碳上生成更稳定的仲自由基，故得反马氏产物 1-溴丙烷。","expl":{"A":"2-溴丙烷是马氏产物，在过氧化物存在下不再是主产物。","B":"只加成 1 分子 HBr，不生成二溴代物。","C":"正确，过氧化物效应使 HBr 反马氏加成，主要得 1-溴丙烷。","D":"两个溴不可能加在同一碳上，产物不成立。","E":"体系中有过氧化物时反应更快进行，并非不反应。"},"id":"org04_q06","chapter":"第四章 烯烃","chapterIdx":3,"num":6},{"type":"A","stem":"丙烯在酸催化下水合的主要产物是","options":{"A":"1-丙醇","B":"2-丙醇","C":"丙醛","D":"丙酮","E":"丙烷"},"answer":["B"],"rationale":"水合是亲电加成，质子先加到端位碳形成更稳定的仲碳正离子，水进攻后得 2-丙醇，符合马氏规则。","expl":{"A":"1-丙醇是反马氏产物，只在硼氢化氧化等特殊条件下生成。","B":"正确，质子加端位碳得仲碳正离子，水进攻后生成 2-丙醇。","C":"水合产物是醇，不是醛，醛需经其他氧化过程生成。","D":"丙酮需由炔烃水合等途径得到，丙烯水合不生成酮。","E":"水合是加水而不是加氢，不生成丙烷。"},"id":"org04_q07","chapter":"第四章 烯烃","chapterIdx":3,"num":7},{"type":"A","stem":"乙烯通入冷稀高锰酸钾碱性溶液的现象是","options":{"A":"无明显变化","B":"生成乙醛","C":"紫色褪去并生成乙二醇","D":"放出氢气","E":"生成草酸"},"answer":["C"],"rationale":"冷稀高锰酸钾在中性或碱性条件下使烯烃顺式双羟基化，紫色褪去并生成乙二醇，可用于检验不饱和键。","expl":{"A":"烯烃可被高锰酸钾氧化，溶液会褪色，并非无变化。","B":"冷稀碱性条件下主要得到邻二醇，进一步氧化才可能断键。","C":"正确，高锰酸钾紫色褪去，双键上加两个羟基生成乙二醇。","D":"该反应是氧化反应，不产生氢气。","E":"草酸需在较强氧化条件下断裂双键才能生成，冷稀条件得到二醇。"},"id":"org04_q08","chapter":"第四章 烯烃","chapterIdx":3,"num":8},{"type":"A","stem":"2-丁烯经臭氧氧化后还原水解，主要产物是","options":{"A":"乙醛和乙酸","B":"两分子乙醛","C":"两分子乙酸","D":"丙醛和甲醛","E":"丁醛"},"answer":["B"],"rationale":"臭氧化还原水解使双键完全断裂，2-丁烯两端均为 CH3CH 结构，故生成两分子乙醛。","expl":{"A":"还原水解生成醛，不会进一步氧化成乙酸。","B":"正确，双键断裂后每个碳上带一个氢，各生成一分子乙醛。","C":"乙酸需在氧化性条件下才生成，还原水解只得到醛。","D":"2-丁烯两端碳各连一个甲基，不可能生成丙醛和甲醛。","E":"臭氧化使双键断裂，碳链变短，不生成丁醛。"},"id":"org04_q09","chapter":"第四章 烯烃","chapterIdx":3,"num":9},{"type":"A","stem":"丙烯先用过氧乙酸环氧化，再在酸性条件下水解，主要产物是","options":{"A":"1-丙醇","B":"2-丙醇","C":"丙醛","D":"1,2-丙二醇","E":"丙酮"},"answer":["D"],"rationale":"过氧酸使双键环氧化生成环氧丙烷，酸性水解时水从背面开环，在相邻两碳上各加羟基，得 1,2-丙二醇。","expl":{"A":"环氧开环生成二醇，不是一元醇。","B":"2-丙醇需双键加一分子水，而环氧水解是在两个碳上加羟基。","C":"水解产物是二醇，不发生氧化生成醛。","D":"正确，环氧丙烷酸性水解在两端碳上各引入羟基，生成 1,2-丙二醇。","E":"丙酮由丙烯直接氧化制得，非环氧水解产物。"},"id":"org04_q10","chapter":"第四章 烯烃","chapterIdx":3,"num":10},{"type":"A","stem":"丙烯在 500 摄氏度高温下与氯气反应的主要产物是","options":{"A":"1,2-二氯丙烷","B":"3-氯-1-丙烯","C":"2-氯丙烷","D":"1-氯丙烷","E":"不反应"},"answer":["B"],"rationale":"高温下反应以自由基取代为主，烯丙位碳氢键离解能低、生成的烯丙基自由基稳定，故主要得 3-氯-1-丙烯。","expl":{"A":"高温下加成比例很低，主要发生烯丙位取代，二氯代物不是主产物。","B":"正确，高温利于自由基取代，烯丙位氢被取代生成 3-氯-1-丙烯。","C":"2-氯丙烷需经加成机理生成，高温条件下不是主要产物。","D":"1-氯丙烷是反马氏加成产物，高温取代主要发生在烯丙位。","E":"丙烯在高温下能与氯发生取代反应，并非不反应。"},"id":"org04_q11","chapter":"第四章 烯烃","chapterIdx":3,"num":11},{"type":"A","stem":"乙烯在齐格勒-纳塔催化剂作用下生成聚乙烯，该反应属于","options":{"A":"缩聚反应","B":"逐步聚合","C":"开环聚合","D":"共聚反应","E":"加聚反应"},"answer":["E"],"rationale":"乙烯分子中的 π 键打开相互连接成高分子，无小分子副产物析出，属于加成聚合反应。","expl":{"A":"缩聚伴随小分子副产物生成，乙烯聚合无副产物。","B":"逐步聚合通过官能团间反应逐步增长，乙烯聚合是链式增长。","C":"开环聚合针对环状单体，乙烯不是环状化合物。","D":"共聚需两种以上单体，乙烯单独聚合属均聚。","E":"正确，乙烯的 π 键打开彼此加成连接，属加聚反应。"},"id":"org04_q12","chapter":"第四章 烯烃","chapterIdx":3,"num":12},{"type":"X","stem":"下列物质能使溴水褪色的有","options":{"A":"乙烯","B":"乙炔","C":"丙烷","D":"苯","E":"苯酚"},"answer":["A","B","E"],"rationale":"乙烯、乙炔含不饱和键可加成溴，苯酚与溴水发生取代生成三溴苯酚，三者均使溴水褪色；丙烷和苯不能。","expl":{"A":"正确，乙烯与溴发生亲电加成，使溴水褪色。","B":"正确，乙炔也能与溴加成，使溴水褪色。","C":"丙烷是饱和烷烃，与溴水不反应，不能褪色。","D":"苯在无催化剂时与溴水不反应，不能使溴水褪色。","E":"正确，苯酚与溴水迅速生成 2,4,6-三溴苯酚白色沉淀，溴水褪色。"},"id":"org04_q13","chapter":"第四章 烯烃","chapterIdx":3,"num":13},{"type":"X","stem":"关于马氏规则，下列说法正确的有","options":{"A":"不对称烯烃与 HX 加成时，氢加在含氢较多的双键碳上","B":"其本质是反应经过较稳定的碳正离子","C":"过氧化物存在下 HBr 发生反马氏加成","D":"HCl 和 HI 也存在明显的过氧化物效应","E":"该规则适用于烯烃的亲电加成反应"},"answer":["A","B","C","E"],"rationale":"马氏规则源于较稳定碳正离子的生成，仅 HBr 有过氧化物效应，故 D 错误，其余各项均正确。","expl":{"A":"正确，这是马氏规则的经典表述，氢加到含氢较多的碳上。","B":"正确，反应经更稳定的碳正离子进行，是马氏规则的本质原因。","C":"正确，只有 HBr 在过氧化物存在下发生反马氏自由基加成。","D":"错误，HCl 和 HI 的过氧化物效应不明显，不呈反马氏产物。","E":"正确，马氏规则描述的是亲电加成反应的取向规律。"},"id":"org04_q14","chapter":"第四章 烯烃","chapterIdx":3,"num":14},{"type":"A","stem":"3,3-二甲基-1-丁烯与氯化氢加成时，除正常的加成产物外还生成一个重排产物，该重排产物的结构是","options":{"A":"2-氯-2,3-二甲基丁烷","B":"1-氯-3,3-二甲基丁烷","C":"2-氯-3,3-二甲基丁烷","D":"3-氯-2,2-二甲基丁烷","E":"2,3-二氯-2,3-二甲基丁烷"},"answer":["A"],"rationale":"质子加到端位碳后生成仲碳正离子 CH3CH+-C(CH3)3，其邻位季碳上的甲基带着一对电子发生 1,2-迁移，形成更稳定的叔碳正离子，氯离子进攻该碳即得 2-氯-2,3-二甲基丁烷。","expl":{"A":"正确，1,2-甲基迁移后生成的叔碳正离子被氯离子捕获，得到该重排产物。","B":"该结构要求氢加到含氢较少的碳上，不符合马氏规则。","C":"这是未经重排的正常加成产物，不是重排产物。","D":"该结构对应的碳架与反应物不符，甲基迁移不会得到此产物。","E":"反应只加成一分子氯化氢，不会生成二氯代物。"},"id":"org04_q15","chapter":"第四章 烯烃","chapterIdx":3,"num":15},{"type":"A","stem":"下列化合物与溴发生亲电加成反应活性最大的是","options":{"A":"CH2=CHCl","B":"CH2=CHCH2COOH","C":"CH2=CHCOOH","D":"CH3CH=CH2","E":"(CH3)2C=CHCH3"},"answer":["E"],"rationale":"亲电加成活性取决于双键的电子云密度：双键碳上给电子的烷基越多，π 电子云密度越高，越容易受亲电试剂进攻；吸电子基（羧基、氯）则使活性下降。故双取代的 (CH3)2C=CHCH3 活性最大。","expl":{"A":"氯的吸电子诱导效应使双键电子云密度降低，活性最小。","B":"羧基与双键被亚甲基隔开，吸电子作用较弱，活性低于丙烯。","C":"羧基直接与双键共轭吸电子，活性很低。","D":"丙烯有一个给电子的甲基，活性高于带吸电子基的烯烃，但低于双取代烯烃。","E":"正确，双键上连有两个给电子甲基，π 电子云密度最高，加成活性最大。"},"id":"org04_q16","chapter":"第四章 烯烃","chapterIdx":3,"num":16},{"type":"A","stem":"丙烯经硼氢化-氧化反应（先用 B2H6，再用 H2O2/OH- 处理），主要产物是","options":{"A":"2-丙醇","B":"丙醛","C":"1-丙醇","D":"环氧丙烷","E":"丙酸"},"answer":["C"],"rationale":"硼氢化时硼加到含氢较多的端位碳上，氧化时硼被羟基取代且构型保持，总结果是水分子反马氏、顺式地加到双键上，故丙烯生成 1-丙醇，与酸催化水合的马氏产物相反。","expl":{"A":"2-丙醇是酸催化水合的马氏产物，与硼氢化的取向相反。","B":"硼氢化-氧化只引入羟基，不把双键氧化成醛。","C":"正确，硼加到端位碳，氧化后羟基也在端位，得到 1-丙醇。","D":"环氧化需要过氧酸，硼氢化试剂不生成环氧。","E":"生成羧酸需要强氧化条件，本反应只得到醇。"},"id":"org04_q17","chapter":"第四章 烯烃","chapterIdx":3,"num":17},{"type":"A","stem":"乙烯与溴的加成反应在立体化学上的特征是","options":{"A":"顺式加成","B":"自由基加成","C":"亲核取代","D":"反式加成","E":"不饱和键保持不变"},"answer":["D"],"rationale":"溴与乙烯先形成环状溴鎓离子，溴离子只能从三元环的背面进攻开环，两个溴原子分别加在双键的两侧，因此是反式加成；环己烯加溴同样得到反式-1,2-二溴环己烷。","expl":{"A":"顺式加成是催化加氢、硼氢化和冷稀高锰酸钾氧化的特征，溴加成不是。","B":"溴与烯烃的亲电加成走离子型机理，不是自由基加成。","C":"该反应是加成而不是取代，碳架和卤素数目都发生改变。","D":"正确，溴鎓离子背面开环使两个溴处于反式，属反式加成。","E":"加成后 π 键消失、双键被饱和，不会保持不变。"},"id":"org04_q18","chapter":"第四章 烯烃","chapterIdx":3,"num":18}]},{"title":"第五章 炔烃和二烯烃","questions":[{"type":"A","stem":"化合物 CH3CH(CH3)C≡CH 的正确名称是","options":{"A":"3-甲基-1-丁炔","B":"2-甲基-1-丁炔","C":"3-甲基-2-丁炔","D":"2-甲基-3-丁炔","E":"异丙基乙炔"},"answer":["A"],"rationale":"主链含三键取 4 个碳，从靠近三键一端编号，三键在 1 位、甲基在 3 位，故为 3-甲基-1-丁炔。","expl":{"A":"正确，编号使三键位次最小为 1，甲基落在 3 位，名称规范。","B":"从三键端编号时甲基在 3 位而不是 2 位，故错。","C":"三键位于端位而非 2 位，故名称不符。","D":"编号方向应使三键位次最小，不能命名为 3-丁炔。","E":"系统命名要求选择最长碳链并标出位次，俗名不能代替系统名。"},"id":"org05_q01","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":1},{"type":"A","stem":"下列碳氢键中酸性最强的是","options":{"A":"乙烷中的 C-H","B":"乙烯中的 C-H","C":"乙炔中的 C-H","D":"苯环上的 C-H","E":"丙烷中的 C-H"},"answer":["C"],"rationale":"乙炔的 sp 杂化碳 s 成分最多，电负性最大，生成的炔负离子最稳定，故炔氢酸性最强。","expl":{"A":"乙烷的 sp3 碳 s 成分最少，C-H 酸性最弱。","B":"乙烯 sp2 碳的酸性强于烷烃，但弱于乙炔。","C":"正确，乙炔碳为 sp 杂化，电负性最大，炔氢酸性最强。","D":"苯环 sp2 碳的 C-H 酸性弱于乙炔碳氢。","E":"丙烷属烷烃，其 C-H 酸性比乙炔弱得多。"},"id":"org05_q02","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":2},{"type":"A","stem":"鉴别乙炔和乙烯可用的试剂是","options":{"A":"溴水","B":"硝酸银的氨溶液","C":"冷稀高锰酸钾溶液","D":"蒸馏水","E":"氢氧化钠溶液"},"answer":["B"],"rationale":"乙炔为末端炔，其炔氢可被银离子取代生成白色炔化银沉淀，乙烯无此反应，故可鉴别。","expl":{"A":"乙烯和乙炔都能使溴水褪色，无法区别二者。","B":"正确，乙炔生成白色炔化银沉淀，乙烯不反应，可以鉴别。","C":"两者都能使高锰酸钾褪色，不能用于区分。","D":"二者均不溶于水且无明显反应，不能鉴别。","E":"氢氧化钠与二者均不反应，无鉴别作用。"},"id":"org05_q03","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":3},{"type":"A","stem":"与烯烃相比，炔烃发生亲电加成反应的活性","options":{"A":"明显更快","B":"无法比较","C":"完全相同","D":"不发生加成","E":"明显更慢"},"answer":["E"],"rationale":"sp 杂化碳电负性大，π 电子被束缚较紧，不易给出，故炔烃亲电加成活性低于烯烃。","expl":{"A":"炔烃 π 电子被 sp 碳束缚更紧，反应反而更慢，故该项错误。","B":"炔烃与烯烃的活性差异有明确规律，可以比较。","C":"两者杂化方式不同，活性存在明显差别，不可能完全相同。","D":"炔烃可以发生亲电加成，只是速率较慢，并非不能加成。","E":"正确，sp 碳电负性大，π 电子云不易极化，亲电加成慢于烯烃。"},"id":"org05_q04","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":4},{"type":"A","stem":"乙炔在硫酸汞-硫酸催化下加水，主要产物是","options":{"A":"乙醇","B":"乙醛","C":"乙酸","D":"丙酮","E":"乙醚"},"answer":["B"],"rationale":"乙炔加水先生成不稳定的乙烯醇，随即重排为乙醛，这是乙炔水合制乙醛的经典方法。","expl":{"A":"水合产物是醛，不会停留在醇，乙醇需还原才能得到。","B":"正确，乙炔水合经乙烯醇互变异构生成乙醛。","C":"乙醛需进一步氧化才生成乙酸，水合产物为乙醛。","D":"只有非末端炔水合才生成酮，乙炔水合生成醛。","E":"乙醚是醇分子间脱水产物，与炔烃水合无关。"},"id":"org05_q05","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":5},{"type":"A","stem":"2-丁炔用酸性高锰酸钾溶液氧化，碳链断裂后的主要产物是","options":{"A":"两分子乙酸","B":"丙酸","C":"草酸","D":"丁酸","E":"二氧化碳"},"answer":["A"],"rationale":"酸性高锰酸钾使三键完全断裂，2-丁炔两侧各为 CH3C 结构，氧化后各生成一分子乙酸。","expl":{"A":"正确，三键断裂后每个碳氧化为羧基，各得乙酸一分子。","B":"丙酸碳数不符，2-丁炔断裂只产生 C2 片段。","C":"草酸需由乙炔氧化生成，2-丁炔不含端位炔碳。","D":"三键断裂使碳链缩短，不会保留四个碳的羧酸。","E":"端位炔碳才可能被氧化为二氧化碳，此处两端均为甲基。"},"id":"org05_q06","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":6},{"type":"A","stem":"丙炔与硝酸银的氨溶液反应，观察到的现象是","options":{"A":"红色沉淀","B":"黄色沉淀","C":"无色气体放出","D":"白色沉淀","E":"无明显现象"},"answer":["D"],"rationale":"丙炔为末端炔，炔氢被银取代生成炔化银白色沉淀，可用于末端炔的鉴别。","expl":{"A":"红色沉淀是炔化亚铜的特征，银盐应为白色。","B":"黄色沉淀不是炔化银的颜色，与反应无关。","C":"该取代反应不放出气体，只生成沉淀。","D":"正确，丙炔生成白色炔化银沉淀，是末端炔的鉴别反应。","E":"末端炔与银氨溶液反应明显，会析出沉淀。"},"id":"org05_q07","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":7},{"type":"A","stem":"1,3-丁二烯与一分子溴在低温下加成，主要产物是","options":{"A":"3,4-二溴-1-丁烯","B":"1,4-二溴-2-丁烯","C":"两种产物等量","D":"环状加成产物","E":"不发生加成"},"answer":["A"],"rationale":"低温下反应受动力学控制，溴优先加到端位双键上，形成较稳定的烯丙型碳正离子，故主要得 1,2-加成产物。","expl":{"A":"正确，低温动力学控制，主要生成 1,2-加成产物 3,4-二溴-1-丁烯。","B":"1,4-加成产物在高温热力学控制条件下才占优势。","C":"低温下 1,2-加成产物明显占优，并非等量。","D":"溴与共轭二烯发生加成而不成环，不生成环状产物。","E":"共轭二烯易于加成，低温下反应仍能顺利进行。"},"id":"org05_q08","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":8},{"type":"A","stem":"1,3-丁二烯与溴加成在较高温度下，主要产物是","options":{"A":"1,2-加成产物","B":"3,4-加成产物","C":"1,4-加成产物","D":"全加成产物","E":"聚合物"},"answer":["C"],"rationale":"高温下反应受热力学控制，1,4-加成产物双键上取代基较多、更稳定，故成为主要产物。","expl":{"A":"1,2-加成产物在低温动力学控制下为主，高温时不是主要产物。","B":"3,4-加成与 1,2-加成相同，高温下所占比例下降。","C":"正确，高温热力学控制，生成更稳定的 1,4-加成产物。","D":"只加入一分子溴，不会得到全加成产物。","E":"高温下仍以加成反应为主，聚合不是主要过程。"},"id":"org05_q09","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":9},{"type":"A","stem":"1,3-丁二烯与顺丁烯二酸酐加热反应，生成的产物属于","options":{"A":"芳香化合物","B":"环丁烷衍生物","C":"环戊烷衍生物","D":"直链加成产物","E":"环己烯衍生物"},"answer":["E"],"rationale":"该反应是 Diels-Alder 双烯合成，共轭二烯与亲双烯体加成形成一个六元环，产物为环己烯二甲酸酐。","expl":{"A":"D-A 产物为环己烯骨架，不具芳香性。","B":"双烯合成形成六元环而不是四元环。","C":"产物环上有 6 个碳，不是五元环。","D":"该反应是环加成，产物为环状而非直链。","E":"正确，D-A 反应生成含一个双键的六元环，即环己烯衍生物。"},"id":"org05_q10","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":10},{"type":"X","stem":"关于 1,3-丁二烯，下列说法正确的有","options":{"A":"存在 s-顺式和 s-反式两种构象","B":"能与溴发生 1,4-加成","C":"能与顺丁烯二酸酐发生双烯合成反应","D":"分子中两个双键彼此孤立，无共轭","E":"完全加氢可生成丁烷"},"answer":["A","B","C","E"],"rationale":"1,3-丁二烯为共轭二烯，有 s-顺、s-反构象，可发生 1,4-加成和 D-A 反应，完全加氢得丁烷，故 D 错误。","expl":{"A":"正确，绕单键旋转可得到 s-顺式和 s-反式两种构象。","B":"正确，共轭二烯可发生 1,4-加成，高温下 1,4-产物更稳定。","C":"正确，s-顺式构象可与顺丁烯二酸酐发生 D-A 环加成。","D":"错误，两个双键被单键隔开且共轭，并非孤立双键。","E":"正确，1,3-丁二烯加两分子氢后生成丁烷。"},"id":"org05_q11","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":11},{"type":"X","stem":"下列化合物能与硝酸银的氨溶液反应生成沉淀的有","options":{"A":"乙炔","B":"1-丁炔","C":"2-丁炔","D":"乙烯","E":"丙炔"},"answer":["A","B","E"],"rationale":"只有末端炔的炔氢可被银取代生成炔化银沉淀，乙炔、1-丁炔、丙炔均为末端炔，2-丁炔和乙烯不能。","expl":{"A":"正确，乙炔为末端炔，生成白色炔化银沉淀。","B":"正确，1-丁炔的三键在端位，可生成炔化银沉淀。","C":"错误，2-丁炔三键在内部，无炔氢，不能生成沉淀。","D":"错误，乙烯无炔氢，与银氨溶液不反应。","E":"正确，丙炔为末端炔，可生成白色沉淀。"},"id":"org05_q12","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":12},{"type":"A","stem":"2-丁炔在林德拉催化剂（Lindlar 催化剂）作用下加氢，生成的主要产物是","options":{"A":"反-2-丁烯","B":"丁烷","C":"1-丁烯","D":"顺-2-丁烯","E":"2-丁醇"},"answer":["D"],"rationale":"林德拉催化剂经醋酸铅和喹啉毒化后活性降低，只能使炔烃加一分子氢并发生顺式加氢，故 2-丁炔生成顺-2-丁烯；若用钠-液氨还原则得反式烯烃，彻底加氢才生成丁烷。","expl":{"A":"反-2-丁烯是钠-液氨还原炔烃的产物，不是林德拉催化的产物。","B":"林德拉催化剂活性低，加氢停在烯烃阶段，不会生成丁烷。","C":"2-丁炔加氢时氢加在三键两端，不生成端位双键的 1-丁烯。","D":"正确，顺式加氢使两个甲基位于双键同侧，得到顺-2-丁烯。","E":"加氢得到烯烃而不是醇，醇需要经水合反应制备。"},"id":"org05_q13","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":13},{"type":"A","stem":"乙炔钠与溴乙烷在液氨中反应，生成的主要产物是","options":{"A":"2-丁炔","B":"丁烷","C":"1-丁烯","D":"乙烯","E":"1-丁炔"},"answer":["E"],"rationale":"乙炔钠中的炔负离子是强亲核试剂，按 SN2 机理进攻溴乙烷的碳并取代溴，碳链由两个碳增长到四个碳，生成端基炔 1-丁炔，这是由末端炔增长碳链的常用方法。","expl":{"A":"反应生成的是端基炔，不是内部炔，2-丁炔需另经异构化才能得到。","B":"炔负离子与卤代烃发生取代而不是还原，不生成烷烃。","C":"产物中保留三键，不会只得到烯烃。","D":"乙烯碳数不变，与碳链增长的取代反应不符。","E":"正确，炔负离子取代溴后碳链增长两个碳，得到 1-丁炔。"},"id":"org05_q14","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":14},{"type":"A","stem":"下列亲双烯体中，与 1,3-丁二烯发生 Diels-Alder 反应活性最大的是","options":{"A":"乙烯","B":"丙烯","C":"顺丁烯二酸酐","D":"1-丁烯","E":"环己烯"},"answer":["C"],"rationale":"Diels-Alder 反应中，亲双烯体上连有吸电子基时其双键的 LUMO 能量降低，与双烯体 HOMO 的能差减小，反应活性增大。顺丁烯二酸酐的两个羰基强吸电子，是最活泼的亲双烯体。","expl":{"A":"乙烯没有吸电子基，双键电子云密度正常，活性最低。","B":"丙烯的甲基给电子，反而降低亲双烯体的亲电性。","C":"正确，两个羰基强吸电子，使亲双烯体最活泼，反应极易进行。","D":"1-丁烯的烷基给电子，活性低于乙烯和酸酐。","E":"环己烯虽有环状双键，但没有吸电子基，活性仍低于顺丁烯二酸酐。"},"id":"org05_q15","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":15},{"type":"A","stem":"乙炔与一分子溴化氢加成，生成的主要产物是","options":{"A":"1,2-二溴乙烷","B":"溴乙烯","C":"1,1-二溴乙烷","D":"乙基溴","E":"1,2-二溴乙烯"},"answer":["B"],"rationale":"乙炔与一分子溴化氢发生亲电加成，按马氏规则氢加到含氢较多的碳上，先得到溴乙烯；溴乙烯还可与第二分子溴化氢加成生成 1,1-二溴乙烷，但控制一分子加成时主要产物是溴乙烯。","expl":{"A":"1,2-二溴乙烷是乙烯与溴加成的产物，需要另一类试剂。","B":"正确，一分子溴化氢加到三键上，生成溴乙烯。","C":"1,1-二溴乙烷需再加一分子溴化氢才能生成。","D":"乙基溴是乙烷的溴代物，必须把三键完全加成才能得到。","E":"1,2-二溴乙烯相当于在乙烯上再取代一个氢，与加成反应不符。"},"id":"org05_q16","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":16}]},{"title":"第六章 脂环烃","questions":[{"type":"A","stem":"下列环己烷构象中最稳定的是","options":{"A":"船式","B":"扭船式","C":"椅式","D":"半椅式","E":"平面六边形"},"answer":["C"],"rationale":"椅式构象中所有相邻碳氢均处于交叉式，扭转张力最小，且无船式的旗杆氢排斥，故最稳定。","expl":{"A":"船式存在旗杆氢之间的强排斥和部分重叠，能量较高。","B":"扭船式虽比船式稳定，但仍高于椅式构象。","C":"正确，椅式构象中键均呈交叉式，无旗杆氢排斥，是最稳定构象。","D":"半椅式是船式与椅式互变途中的过渡构象，能量高。","E":"平面六边形使键角压缩、氢原子全重叠，能量极高，不能稳定存在。"},"id":"org06_q01","chapter":"第六章 脂环烃","chapterIdx":5,"num":1},{"type":"A","stem":"环丙烷与氢气在镍催化下反应的主要产物是","options":{"A":"丙烯","B":"丙烷","C":"1-溴丙烷","D":"不反应","E":"环丁烷"},"answer":["B"],"rationale":"环丙烷张力大，可像烯烃一样与氢发生开环加成，加氢后生成丙烷，故选 B。","expl":{"A":"加氢是还原过程，不生成含双键的丙烯。","B":"正确，环丙烷在镍催化下开环加氢，生成丙烷。","C":"反应体系中没有溴，不可能生成溴代烷。","D":"环丙烷张力大，比普通环烷烃活泼，能与氢加成。","E":"加氢不会使环扩大，不能生成环丁烷。"},"id":"org06_q02","chapter":"第六章 脂环烃","chapterIdx":5,"num":2},{"type":"A","stem":"下列环烷烃中热力学稳定性最高的是","options":{"A":"环丙烷","B":"环丁烷","C":"环戊烷","D":"环己烷","E":"环庚烷"},"answer":["D"],"rationale":"环己烷的椅式构象中键角接近 109.5 度，扭转张力与角张力都很小，故稳定性最高。","expl":{"A":"环丙烷角张力最大，稳定性最差，易开环。","B":"环丁烷仍有较大角张力，稳定性低于环戊烷和环己烷。","C":"环戊烷需略微扭曲成信封式，仍有一定张力，稳定性不如环己烷。","D":"正确，环己烷椅式构象张力最小，是稳定性最高的环烷烃。","E":"环庚烷存在跨环氢排斥，稳定性不如环己烷。"},"id":"org06_q03","chapter":"第六章 脂环烃","chapterIdx":5,"num":3},{"type":"X","stem":"关于环己烷椅式构象，下列说法正确的有","options":{"A":"椅式构象是环己烷最稳定的构象","B":"每个碳原子上有一个直立键和一个平伏键","C":"两种椅式构象可通过环翻转相互转变","D":"环翻转后原来的直立键变为平伏键","E":"椅式构象中六个碳原子共平面"},"answer":["A","B","C","D"],"rationale":"椅式构象张力最小最稳定，每个碳有一上一下的直立键与平伏键，环翻转时二者互换，但碳原子并不共平面。","expl":{"A":"正确，椅式构象所有相邻键呈交叉式，张力最小，最稳定。","B":"正确，椅式构象中每个碳原子上有一个直立键（a）和一个平伏键（e）。","C":"正确，环翻转可使一种椅式构象转变为另一种椅式构象。","D":"正确，环翻转过程中原来的直立键转变为平伏键，反之亦然。","E":"错误，椅式构象中碳原子交替位于两个平行平面，并不共平面。"},"id":"org06_q04","chapter":"第六章 脂环烃","chapterIdx":5,"num":4},{"type":"A","stem":"环丙烷与溴的四氯化碳溶液反应，生成的主要产物是","options":{"A":"1,3-二溴丙烷","B":"1,2-二溴丙烷","C":"1-溴丙烷","D":"2-溴丙烷","E":"不反应"},"answer":["A"],"rationale":"环丙烷的键角只有 60 度，角张力很大，成环的碳碳键弯曲如香蕉，可像烯烃一样与溴发生开环加成：断裂一个碳碳单键，两个溴分别加在断键的两端，生成 1,3-二溴丙烷。","expl":{"A":"正确，三元环开环后两个溴分别加在断键两端，得 1,3-二溴丙烷。","B":"1,2-二溴丙烷要求两个溴加在相邻碳上，与三元环的开环位置不符。","C":"只加一分子溴化氢才得到一溴代物，溴加成引入的是两个溴原子。","D":"2-溴丙烷是丙烯加溴化氢的产物，与溴的开环加成无关。","E":"环丙烷张力大，与溴能顺利反应使溴的红色褪去。"},"id":"org06_q05","chapter":"第六章 脂环烃","chapterIdx":5,"num":5},{"type":"A","stem":"甲基环丙烷与溴化氢发生开环加成时，主要产物是","options":{"A":"1-溴丁烷","B":"2-溴丁烷","C":"1-溴-2-甲基丙烷","D":"2-溴-2-甲基丙烷","E":"溴甲基环丙烷"},"answer":["B"],"rationale":"取代环丙烷开环时断裂连接取代基最多与最少的两碳之间的键，质子加到含氢较多的碳上，形成较稳定的仲碳正离子，溴再连到带甲基的碳上，故主要产物为 2-溴丁烷。","expl":{"A":"溴连在端位碳上需要生成较不稳定的伯碳正离子，不是主要产物。","B":"正确，氢加到 CH2 上、溴加到带甲基的碳上，得到 2-溴丁烷。","C":"该结构要求环在另一侧开环，与马氏规则给出的取向不符。","D":"该产物需要生成叔碳正离子，甲基环丙烷开环只能形成仲碳正离子。","E":"溴化氢使环打开，溴不会连在甲基上而保留三元环。"},"id":"org06_q06","chapter":"第六章 脂环烃","chapterIdx":5,"num":6},{"type":"A","stem":"用酸性高锰酸钾溶液鉴别环丙烷和丙烯时，观察到的现象是","options":{"A":"两者都使溶液褪色","B":"两者都不褪色","C":"环丙烷褪色而丙烯不褪色","D":"两者都生成沉淀","E":"环丙烷不褪色而丙烯褪色"},"answer":["E"],"rationale":"环丙烷虽然有较大的角张力，但碳原子仍为 sp3 杂化、没有 π 电子，不能被高锰酸钾氧化，只使溴的四氯化碳溶液褪色；丙烯含双键可被高锰酸钾氧化使紫色褪去，据此可区分二者。","expl":{"A":"环丙烷不与高锰酸钾反应，不会褪色，不能说两者都褪色。","B":"丙烯含双键，能使高锰酸钾褪色，不能说两者都不褪色。","C":"现象正好相反，环丙烷不褪色而丙烯褪色。","D":"高锰酸钾氧化烯烃生成棕色二氧化锰，但不是两者都产生沉淀。","E":"正确，环丙烷不被氧化而丙烯被氧化，可据此区分。"},"id":"org06_q07","chapter":"第六章 脂环烃","chapterIdx":5,"num":7},{"type":"A","stem":"顺-1,3-二甲基环己烷最稳定的椅式构象中，两个甲基所处的键型是","options":{"A":"两个甲基都处于平伏键（e,e）","B":"两个甲基都处于直立键（a,a）","C":"一个处于直立键、一个处于平伏键","D":"两个甲基都在环平面内","E":"无法判断"},"answer":["A"],"rationale":"椅式构象中 1,3 位两个同向的键同属一类：都取 e 键时两个甲基位于环的同侧，即顺式。顺-1,3-二甲基环己烷可采取 e,e 构象，位阻最小、最稳定；翻转后变成 a,a，能量较高。","expl":{"A":"正确，顺-1,3 取代物两个甲基可同时处于平伏键，位阻最小。","B":"a,a 是同一分子的另一种椅式构象，两个甲基都直立时位阻大。","C":"一 a 一 e 对应的是反-1,3-二甲基环己烷，与顺式不符。","D":"椅式构象中取代基只能在 a 键或 e 键上，不存在位于环平面内的键。","E":"由 1,3 位两个键的几何关系可直接判断构象，并非无法判断。"},"id":"org06_q08","chapter":"第六章 脂环烃","chapterIdx":5,"num":8},{"type":"A","stem":"叔丁基环己烷在室温下几乎完全以叔丁基处于平伏键的椅式构象存在，主要原因是","options":{"A":"平伏键的键长比直立键短","B":"叔丁基处于直立键时与 1,3-位直立氢距离过近，排斥很强","C":"平伏键上的叔丁基能形成分子内氢键","D":"叔丁基使环己烷不能发生构象翻转","E":"平伏键的键能比直立键大"},"answer":["B"],"rationale":"椅式构象中同一侧的 1,3,5 位直立氢指向环内，与直立键上的大基团距离很近，产生强烈的 1,3-二直立键相互作用。叔丁基体积很大，处于平伏键时这种排斥最小，故几乎全部以 e 构象存在。","expl":{"A":"a 键与 e 键的键长相同，稳定性差异来自空间排斥而不是键长。","B":"正确，1,3-二直立键相互作用是叔丁基强烈偏好平伏键的原因。","C":"叔丁基与环己烷上都没有能形成氢键的基团。","D":"叔丁基不阻止环翻转，只是使 e 构象在平衡中占绝对优势。","E":"两种键的键能和键长没有差别，差别在于取代基的空间环境。"},"id":"org06_q09","chapter":"第六章 脂环烃","chapterIdx":5,"num":9},{"type":"A","stem":"关于螺[2.4]庚烷分子的结构，下列说法正确的是","options":{"A":"含有两个共用的桥头碳原子","B":"含有一个四元环和一个五元环","C":"分子中一共有 6 个碳原子","D":"含有一个三元环和一个五元环，共用一个螺碳原子","E":"含有一个三元环和一个六元环"},"answer":["D"],"rationale":"螺环烃的两个环只共用一个碳原子（螺原子）。命名时方括号内先写小环、后写大环除螺原子以外的碳数，螺[2.4]庚烷即由一个三元环和一个五元环共用螺碳构成，碳原子总数为 2+4+1=7。","expl":{"A":"共用两个以上碳原子的是桥环烃，螺环烃只共用一个碳。","B":"方括号中的 2 和 4 指两个环上除螺碳外的碳数，对应三元环和五元环。","C":"碳原子总数为 2+4+1=7，故称庚烷，不是 6 个。","D":"正确，2 与 4 分别表示两环上除螺碳外的碳数，共 7 个碳。","E":"若为三元环与六元环，名称应为螺[2.5]辛烷。"},"id":"org06_q10","chapter":"第六章 脂环烃","chapterIdx":5,"num":10},{"type":"A","stem":"比较环烷烃稳定性时，常用的热力学判据是","options":{"A":"沸点的高低","B":"密度的大小","C":"折射率的大小","D":"每个 CH2 的燃烧热，数值越大越稳定","E":"每个 CH2 的燃烧热，数值越大越不稳定"},"answer":["E"],"rationale":"环的张力越大，分子内能越高，完全燃烧时放出的热量越多。为消除环大小不同带来的碳数差异，通常比较每个 CH2 的燃烧热，其值越大说明环张力越大、越不稳定，顺序为环丙烷最大、环己烷最小。","expl":{"A":"沸点反映分子间作用力，与分子内环张力没有直接关系。","B":"密度属于物理性质，不能作为判断环稳定性的热力学判据。","C":"折射率与极性和密度有关，与环张力无必然联系。","D":"每个 CH2 燃烧热越大说明分子内能越高，是越不稳定而不是越稳定。","E":"正确，每个 CH2 的燃烧热越大，环张力越大、越不稳定。"},"id":"org06_q11","chapter":"第六章 脂环烃","chapterIdx":5,"num":11},{"type":"A","stem":"环己烷在催化剂存在下用空气氧化，生成的主要产物是","options":{"A":"己二酸","B":"环己烯","C":"环己醇和环己酮","D":"二氧化碳和水","E":"氯代环己烷"},"answer":["C"],"rationale":"环己烷的六元环张力很小、不易开环，在钴盐等催化剂作用下与空气反应时氧进攻环上的碳氢键，主要生成环己醇和环己酮；二者进一步氧化可得己二酸，这是工业制备己二酸的第一步。","expl":{"A":"己二酸是环己醇、环己酮进一步氧化的产物，不是环己烷直接氧化的主要产物。","B":"该氧化是引入氧而不是脱氢成烯，不生成环己烯。","C":"正确，环己烷空气氧化的主要产物是环己醇和环己酮。","D":"温和的催化氧化条件下六元环不开环、也不完全燃烧。","E":"氯代环己烷需用氯气在光照下进行自由基取代才能得到。"},"id":"org06_q12","chapter":"第六章 脂环烃","chapterIdx":5,"num":12},{"type":"A","stem":"环戊烷与溴在光照下反应，主要发生的反应类型是","options":{"A":"自由基取代","B":"开环加成","C":"亲电取代","D":"消除反应","E":"不反应"},"answer":["A"],"rationale":"环戊烷的角张力很小、环不易打开，性质与链状烷烃相似，在光照下与卤素发生自由基取代生成卤代环戊烷；只有环丙烷、环丁烷这类小环才容易开环加成。","expl":{"A":"正确，光照使溴分子均裂产生自由基，环戊烷的氢被取代，属自由基取代。","B":"环戊烷张力小，光照下不发生开环加成。","C":"亲电取代是芳香环的特征反应，环戊烷没有大 π 键。","D":"该反应不脱去小分子形成双键，不是消除反应。","E":"环戊烷在光照下能与溴反应，并非不反应。"},"id":"org06_q13","chapter":"第六章 脂环烃","chapterIdx":5,"num":13},{"type":"X","stem":"关于环丙烷的结构和性质，下列说法正确的有","options":{"A":"碳原子为 sp3 杂化，成环的碳碳键弯曲呈香蕉键","B":"能使溴的四氯化碳溶液褪色","C":"能使酸性高锰酸钾溶液褪色","D":"与溴化氢加成生成 1-溴丙烷","E":"在镍催化下与氢气加成生成丙烷"},"answer":["A","B","D","E"],"rationale":"环丙烷的键角只有 60 度，碳原子仍为 sp3 杂化，成环轨道向外弯曲形成香蕉键，张力大而具有类似烯烃的开环加成性质，能与溴、溴化氢、氢气加成；但它没有 π 电子，不能被高锰酸钾氧化，故 C 错误。","expl":{"A":"正确，环丙烷碳为 sp3 杂化，弯曲的香蕉键重叠程度小，故性质活泼。","B":"正确，三元环开环加溴生成 1,3-二溴丙烷，使溴的红色褪去。","C":"错误，环丙烷不含 π 电子，不被高锰酸钾氧化，可据此与丙烯区分。","D":"正确，开环加成遵循马氏规则，氢加到含氢较多的碳上，得 1-溴丙烷。","E":"正确，镍催化下开环加氢生成丙烷。"},"id":"org06_q14","chapter":"第六章 脂环烃","chapterIdx":5,"num":14}]},{"title":"第七章 芳香烃","questions":[{"type":"A","stem":"关于苯分子中碳碳键的叙述，正确的是","options":{"A":"单双键交替排列，键长长短不等","B":"六个碳碳键完全等同，键长介于单键和双键之间","C":"所有碳碳键都比单键长","D":"所有碳碳键都比双键短","E":"键长随温度改变而无法确定"},"answer":["B"],"rationale":"苯环六个碳碳键完全等同，键长约 0.139 nm，介于单键与双键之间，说明苯具有离域的大 π 键结构。","expl":{"A":"苯并非单双键交替，六个键完全等同，键长相等。","B":"正确，苯的六个碳碳键等同，键长介于单双键之间。","C":"苯环碳碳键比单键短，不是更长。","D":"苯环碳碳键比典型双键长，并非比双键短。","E":"苯的键长是确定的实验事实，不因温度而无法确定。"},"id":"org07_q01","chapter":"第七章 芳香烃","chapterIdx":6,"num":1},{"type":"A","stem":"下列化合物中具有芳香性的是","options":{"A":"环戊二烯","B":"环戊二烯正离子","C":"环戊二烯负离子","D":"1,4-环己二烯","E":"环辛四烯"},"answer":["C"],"rationale":"环戊二烯负离子为平面环状共轭体系，含 6 个 π 电子，符合 4n+2 规则，故具有芳香性。","expl":{"A":"环戊二烯有一个 sp3 碳，共轭不闭合，且只有 4 个 π 电子，无芳香性。","B":"环戊二烯正离子只有 4 个 π 电子，不符合 4n+2 规则，无芳香性。","C":"正确，环戊二烯负离子含 6 个 π 电子，平面闭合共轭，具有芳香性。","D":"1,4-环己二烯共轭不闭合，无芳香性。","E":"环辛四烯呈盆形非平面结构，含 8 个 π 电子，不具芳香性。"},"id":"org07_q02","chapter":"第七章 芳香烃","chapterIdx":6,"num":2},{"type":"A","stem":"苯的硝化反应中，真正进攻苯环的亲电试剂是","options":{"A":"NO2-","B":"NO3-","C":"H+","D":"NO2+","E":"HNO3 分子"},"answer":["D"],"rationale":"浓硝酸在浓硫酸作用下生成硝酰正离子 NO2+，它作为强亲电试剂进攻苯环形成碳正离子中间体。","expl":{"A":"NO2- 是负离子，不能作为亲电试剂进攻苯环。","B":"NO3- 不具亲电性，不能进攻富电子的苯环。","C":"质子不是硝化反应的进攻试剂，它参与生成硝酰正离子。","D":"正确，混酸中生成 NO2+，是进攻苯环的真正亲电试剂。","E":"硝酸分子需先被质子化脱水生成 NO2+ 才能反应。"},"id":"org07_q03","chapter":"第七章 芳香烃","chapterIdx":6,"num":3},{"type":"A","stem":"苯环上的硝基（-NO2）属于","options":{"A":"间位定位基，使苯环钝化","B":"邻、对位定位基，使苯环钝化","C":"邻、对位定位基，使苯环活化","D":"间位定位基，使苯环活化","E":"无定位效应的基团"},"answer":["A"],"rationale":"硝基是强吸电子基，使苯环电子云密度降低而钝化，且使邻对位更缺电子，故为间位定位基。","expl":{"A":"正确，硝基吸电子，钝化苯环并使新取代基主要进入间位。","B":"硝基不是邻对位定位基，它使邻对位电子云密度降低最多。","C":"硝基吸电子而非给电子，不能活化苯环。","D":"硝基虽为间位定位基，但作用是钝化而非活化。","E":"硝基有明确的间位定位效应，不是无定位基团。"},"id":"org07_q04","chapter":"第七章 芳香烃","chapterIdx":6,"num":4},{"type":"A","stem":"下列基团中属于邻、对位定位基的是","options":{"A":"-NO2","B":"-COOH","C":"-SO3H","D":"-CH3","E":"-CHO"},"answer":["D"],"rationale":"甲基通过 +I 和超共轭效应给电子，使邻对位电子云密度升高，属邻对位定位基且活化苯环。","expl":{"A":"硝基是强吸电子基，属间位定位基。","B":"羧基是吸电子基，使苯环钝化并使新取代基进入间位，属间位定位基。","C":"磺酸基是强吸电子基，使苯环钝化并使新取代基主要进入间位，属间位定位基。","D":"正确，甲基给电子，是典型的邻对位定位基和致活基。","E":"醛基通过羰基吸电子，使苯环钝化且新取代基主要进入间位，属间位定位基。"},"id":"org07_q05","chapter":"第七章 芳香烃","chapterIdx":6,"num":5},{"type":"A","stem":"下列化合物进行硝化反应时活性最高的是","options":{"A":"苯","B":"硝基苯","C":"氯苯","D":"苯甲酸","E":"甲苯"},"answer":["E"],"rationale":"甲基是给电子基，使苯环电子云密度升高，故甲苯的硝化活性高于苯，更高于各吸电子基取代的苯。","expl":{"A":"苯无取代基，活性低于带给电子基的甲苯。","B":"硝基强烈吸电子，使苯环严重钝化，活性最低。","C":"氯有吸电子诱导效应，使苯环略微钝化，活性低于苯。","D":"羧基吸电子，钝化苯环，活性低于苯。","E":"正确，甲基给电子活化苯环，硝化活性最高。"},"id":"org07_q06","chapter":"第七章 芳香烃","chapterIdx":6,"num":6},{"type":"A","stem":"下列化合物硝化时新取代基主要进入间位的是","options":{"A":"甲苯","B":"苯酚","C":"硝基苯","D":"氯苯","E":"苯胺"},"answer":["C"],"rationale":"硝基苯中的硝基是强吸电子间位定位基，使邻对位电子云密度显著降低，故新取代基主要进入间位。","expl":{"A":"甲基是邻对位定位基，硝化主要得邻、对位产物。","B":"羟基是强邻对位定位基，取代主要发生在邻、对位。","C":"正确，硝基为间位定位基，硝化产物以间位为主。","D":"氯是邻对位定位基，主要得邻、对位产物。","E":"氨基是强邻对位定位基，取代主要在邻、对位。"},"id":"org07_q07","chapter":"第七章 芳香烃","chapterIdx":6,"num":7},{"type":"A","stem":"萘发生亲电取代反应时，取代主要发生在","options":{"A":"α 位","B":"β 位","C":"两个环同时取代","D":"侧链上","E":"不发生取代"},"answer":["A"],"rationale":"萘的 α 位取代所形成的碳正离子中间体可写出更多保留完整苯环的共振式，更稳定，故 α 位活性高。","expl":{"A":"正确，α 位取代中间体更稳定，活化能低，是主要产物。","B":"β 位取代中间体稳定性较差，只在特殊条件下才成为主产物。","C":"亲电取代通常只在一个环上引入一个取代基。","D":"萘分子中没有侧链，亲电取代只发生在环上的α位或β位，不会发生在侧链上。","E":"萘比苯更易发生亲电取代，反应可以顺利进行。"},"id":"org07_q08","chapter":"第七章 芳香烃","chapterIdx":6,"num":8},{"type":"A","stem":"甲苯在酸性高锰酸钾溶液中加热氧化，主要产物是","options":{"A":"苯甲醛","B":"苯甲酸","C":"苯酚","D":"苯甲醇","E":"二氧化碳和水"},"answer":["B"],"rationale":"苯环上的烷基侧链只要含有 α-H，被酸性高锰酸钾强烈氧化后侧链断裂，最终生成苯甲酸。","expl":{"A":"苯甲醛是中间产物，强氧化条件下会继续氧化成羧酸。","B":"正确，侧链含 α-H 时被氧化为羧基，最终产物为苯甲酸。","C":"氧化不引入羟基，不会生成苯酚。","D":"苯甲醇为中间产物，不能稳定存在于此强氧化体系。","E":"苯环稳定不被破坏，产物为苯甲酸而非完全氧化产物。"},"id":"org07_q09","chapter":"第七章 芳香烃","chapterIdx":6,"num":9},{"type":"A","stem":"氯苯水解需要高温高压，其主要原因是","options":{"A":"氯原子容易离去","B":"苯环特别活泼","C":"氯的 p 轨道与苯环共轭使 C-Cl 键增强，且中间体碳正离子不稳定","D":"氯苯不溶于水","E":"没有合理解释"},"answer":["C"],"rationale":"氯原子孤对电子与苯环形成 p-π 共轭，使 C-Cl 键具有部分双键性而难以断裂，同时苯环上难以形成碳正离子，故水解困难。","expl":{"A":"氯苯中氯原子离去困难，正因如此才需要苛刻条件。","B":"苯环因共轭而稳定，并不特别活泼，反而不利于亲核取代。","C":"正确，p-π 共轭增强 C-Cl 键，且不能形成稳定碳正离子，故难水解。","D":"溶解度只影响反应速率，不是根本原因。","E":"该现象有明确的电子效应解释，并非无原因。"},"id":"org07_q10","chapter":"第七章 芳香烃","chapterIdx":6,"num":10},{"type":"A","stem":"由苯胺制备对硝基苯胺时，通常先进行乙酰化的目的是","options":{"A":"使氨基变成重氮基","B":"增加氨基的碱性","C":"使苯环钝化到完全不反应","D":"提高产物在水中的溶解度","E":"保护氨基，防止其被硝酸氧化，并降低其过度活化"},"answer":["E"],"rationale":"氨基易被硝酸氧化，且活化过强易得多取代物，故先用乙酸酐乙酰化保护氨基，硝化后再水解脱去乙酰基。","expl":{"A":"重氮化需用亚硝酸处理，与乙酰化目的不同。","B":"乙酰化后氮上孤对被羰基共轭分散，碱性反而降低。","C":"乙酰氨基仍是邻对位定位基，苯环仍可发生硝化。","D":"乙酰化的目的不是改善溶解度，而是保护氨基。","E":"正确，乙酰化可保护氨基不被氧化，并适当降低苯环的过度活化。"},"id":"org07_q11","chapter":"第七章 芳香烃","chapterIdx":6,"num":11},{"type":"A","stem":"苯在镍催化下与氢气充分反应，生成的产物是","options":{"A":"环己烯","B":"己烷","C":"1,3-环己二烯","D":"环己烷","E":"不反应"},"answer":["D"],"rationale":"苯的大 π 键在催化加氢时被完全饱和，三个双键共加三分子氢，最终生成环己烷。","expl":{"A":"催化加氢会继续进行到底，不能停留在环己烯。","B":"加氢只饱和环上双键，不开环，故不生成己烷。","C":"中间体可部分加氢，但充分加氢的最终产物是环己烷。","D":"正确，苯完全加氢生成环己烷，是苯具有不饱和性的证据。","E":"苯在镍催化下可以加氢，并非不反应。"},"id":"org07_q12","chapter":"第七章 芳香烃","chapterIdx":6,"num":12},{"type":"X","stem":"下列基团中属于邻、对位定位基的有","options":{"A":"-OH","B":"-NH2","C":"-Cl","D":"-NO2","E":"-CH3"},"answer":["A","B","C","E"],"rationale":"羟基、氨基、卤素、烷基均为邻对位定位基，硝基为间位定位基，故选 ABCE。","expl":{"A":"正确，羟基给电子，是强邻对位定位基。","B":"正确，氨基给电子能力更强，是强邻对位定位基。","C":"正确，氯虽略钝化苯环，但仍属邻对位定位基。","D":"错误，硝基吸电子，属间位定位基。","E":"正确，甲基给电子，属邻对位定位基。"},"id":"org07_q13","chapter":"第七章 芳香烃","chapterIdx":6,"num":13},{"type":"X","stem":"关于苯的结构，下列说法正确的有","options":{"A":"六个碳原子和六个氢原子共平面，构成正六边形","B":"环上键角约为 120 度","C":"每个碳原子均为 sp2 杂化","D":"六个 p 轨道侧面重叠形成闭合大 π 键","E":"分子中存在交替的单键和双键"},"answer":["A","B","C","D"],"rationale":"苯为平面正六边形，碳原子 sp2 杂化，六个 p 电子形成离域大 π 键，不存在交替单双键，故 E 错误。","expl":{"A":"正确，苯分子为平面正六边形，所有碳氢原子共平面。","B":"正确，每个碳为 sp2 杂化，理想键角为 120 度。","C":"正确，苯环碳原子全部为 sp2 杂化。","D":"正确，六个 p 轨道侧面重叠形成闭合的离域大 π 键。","E":"错误，苯的 π 电子完全离域，不存在真正交替的单双键。"},"id":"org07_q14","chapter":"第七章 芳香烃","chapterIdx":6,"num":14},{"type":"A","stem":"按休克尔规则，一个环状共轭体系具有芳香性的条件是","options":{"A":"环状共轭体系共平面且 π 电子数为 4n+2（n=0,1,2…）","B":"环状共轭体系共平面且 π 电子数为 4n","C":"只要分子是环状的，无论是否共轭都具有芳香性","D":"开链共轭体系的 π 电子数为 4n+2","E":"含 6 个 π 电子的任何环状体系，无论是否共平面"},"answer":["A"],"rationale":"休克尔规则要求成环原子共平面或接近共平面、形成闭合的离域 π 体系，且 π 电子数符合 4n+2。π 电子数为 4n 的平面环状共轭体系属反芳香性，如环丁二烯；环辛四烯虽有 8 个 π 电子，却因呈盆形不共平面而无芳香性。","expl":{"A":"正确，共平面、闭合共轭、π 电子数 4n+2 是芳香性的三个条件。","B":"π 电子数为 4n 的平面环状共轭体系属反芳香性，如环丁二烯。","C":"环状但不共轭的体系（如环己烷）没有离域 π 电子，谈不上芳香性。","D":"开链共轭体系可以有共轭，但不满足环状闭合的条件，不具芳香性。","E":"环辛四烯含 8 个 π 电子而因不共平面无芳香性，说明平面性是必要条件。"},"id":"org07_q15","chapter":"第七章 芳香烃","chapterIdx":6,"num":15},{"type":"A","stem":"叔丁基苯进行硝化时，产物几乎全部是对位产物，主要原因是","options":{"A":"叔丁基是间位定位基","B":"对位产物是该反应的热力学控制产物","C":"硝酸优先与对位的氢反应","D":"硝酸过量时只进攻对位","E":"叔丁基体积很大，邻位的空间位阻显著"},"answer":["E"],"rationale":"叔丁基通过 +I 和超共轭给电子，是邻、对位定位基，本应生成邻、对位产物；但叔丁基体积很大，严重阻碍邻位进攻，故产物几乎全为对位，说明定位效应还要受空间位阻修正。","expl":{"A":"叔丁基是烷基，属邻、对位定位基，不是间位定位基。","B":"硝化是不可逆的亲电取代，产物分布由各位置的反应速率决定，不是热力学平衡的结果。","C":"邻位与对位氢的化学环境相同，差别来自进攻时的空间位阻。","D":"硝酸过量只会增加多硝化产物，并不改变对位的优势。","E":"正确，叔丁基的巨大体积屏蔽邻位，使对位产物占绝对优势。"},"id":"org07_q16","chapter":"第七章 芳香烃","chapterIdx":6,"num":16},{"type":"A","stem":"萘在较低温度（约 80 摄氏度）下磺化主要生成 α-萘磺酸，在较高温度（约 160 摄氏度）下主要生成 β-萘磺酸，这说明","options":{"A":"α-萘磺酸是热力学更稳定的产物","B":"高温下反应不可逆，产物只由稳定性决定","C":"α 位的生成速率比 β 位慢","D":"该反应低温受动力学控制、高温受热力学控制","E":"温度升高改变了萘的环系结构"},"answer":["D"],"rationale":"α 位活性高、生成 α-萘磺酸的活化能低，故低温下生成速率快，是动力学控制产物；但 α 位与 8 位氢存在空间排斥，α-萘磺酸不如 β-萘磺酸稳定，而磺化又是可逆反应，高温下平衡向更稳定的 β-萘磺酸移动，表现为热力学控制。","expl":{"A":"β-萘磺酸才是热力学更稳定的产物，α 位受 8 位氢的位阻影响。","B":"磺化是可逆反应，高温下正逆反应都很快，产物由平衡决定而不是单纯不可逆。","C":"α 位的生成速率比 β 位快，正因如此低温下 α 产物占优。","D":"正确，低温动力学控制得 α 产物，高温热力学控制得 β 产物。","E":"温度只改变反应速率和平衡，不改变萘的环状结构。"},"id":"org07_q17","chapter":"第七章 芳香烃","chapterIdx":6,"num":17},{"type":"A","stem":"苯与 1-氯丙烷在无水三氯化铝催化下反应，除正丙苯外还得到较多的异丙苯，其主要原因是","options":{"A":"苯环在反应中发生骨架重排","B":"生成的伯碳正离子经 1,2-氢迁移重排为更稳定的仲碳正离子","C":"1-氯丙烷在催化剂中先异构化","D":"三氯化铝使苯环电子云密度升高","E":"反应温度过高使产物异构化"},"answer":["B"],"rationale":"1-氯丙烷与 AlCl3 作用首先生成正丙基正离子（伯碳正离子），它很不稳定，迅速经 1,2-氢迁移转变为更稳定的异丙基正离子（仲碳正离子），再进攻苯环，故产物中异丙苯占相当比例。这说明傅-克烷基化常伴随碳正离子重排。","expl":{"A":"发生重排的是烷基正离子中间体，不是苯环骨架。","B":"正确，伯碳正离子经 1,2-氢迁移成仲碳正离子，是生成异丙苯的原因。","C":"1-氯丙烷本身不异构化，重排发生在正离子阶段。","D":"三氯化铝的作用是产生亲电试剂，并不直接导致重排。","E":"该重排由碳正离子本身的稳定性驱动，主要不是温度引起的产物异构化。"},"id":"org07_q18","chapter":"第七章 芳香烃","chapterIdx":6,"num":18}]},{"title":"第八章 立体化学基础","questions":[{"type":"A","stem":"只含一个手性碳原子的化合物","options":{"A":"一定是手性分子，具有旋光性","B":"一定是外消旋体","C":"一定没有旋光性","D":"一定含有对称面","E":"一定是内消旋体"},"answer":["A"],"rationale":"含一个手性碳时分子无对称面与对称中心，必为手性分子，纯净物具有旋光性，不可能形成内消旋体。","expl":{"A":"正确，单个手性碳即足以使分子与其镜像不能重合，为手性分子。","B":"外消旋体是等量对映体的混合物，与分子本身是否手性无关。","C":"手性分子对映体过量时具有旋光性，不能说一定没有。","D":"含一个手性碳的分子不能有对称面，否则碳不成为手性中心。","E":"内消旋体要求分子内存在两个构型相反的手性碳，一个手性碳无法形成。"},"id":"org08_q01","chapter":"第八章 立体化学基础","chapterIdx":7,"num":1},{"type":"A","stem":"分子中含有对称面的化合物","options":{"A":"一定是手性分子","B":"一定不是手性分子","C":"一定含有对称中心","D":"一定是外消旋体","E":"无法判断其手性"},"answer":["B"],"rationale":"分子具有对称面时，其镜像可通过对称操作与自身重合，故一定不是手性分子，如内消旋酒石酸。","expl":{"A":"有对称面的分子与其镜像可重合，不是手性分子。","B":"正确，对称面使镜像与自身重合，因此无手性。","C":"有对称面不一定有对称中心，两者是不同对称元素。","D":"有对称面的可能是内消旋体，并非外消旋混合物。","E":"由对称面可直接判断无手性，结论是明确的。"},"id":"org08_q02","chapter":"第八章 立体化学基础","chapterIdx":7,"num":2},{"type":"A","stem":"内消旋酒石酸（meso-酒石酸）的性质是","options":{"A":"具有旋光性","B":"是外消旋混合物","C":"无旋光性，因分子内存在对称面","D":"是手性分子","E":"分子中没有手性碳"},"answer":["C"],"rationale":"内消旋酒石酸含两个构型相反的手性碳，分子内存在对称面，使旋光性互相抵消，故整体无旋光性。","expl":{"A":"内消旋体因内部对称抵消而不显旋光性。","B":"外消旋体是两种对映体的混合物，内消旋体是单一化合物。","C":"正确，分子内对称面使两个手性碳的旋光贡献相互抵消。","D":"有对称面的分子不可能是手性分子。","E":"内消旋酒石酸含有两个手性碳，只是构型相反。"},"id":"org08_q03","chapter":"第八章 立体化学基础","chapterIdx":7,"num":3},{"type":"A","stem":"在标记手性碳的 R/S 构型时，下列基团优先顺序排在最高位的是","options":{"A":"-OH","B":"-COOH","C":"-CH3","D":"-H","E":"-Cl"},"answer":["E"],"rationale":"次序规则以直接相连原子的原子序数比较，氯为 17，大于氧的 8 和碳的 6，故 -Cl 优先次序最高。","expl":{"A":"羟基直接相连的是氧，原子序数小于氯，故低于氯。","B":"羧基直接相连的是碳，优先次序低于连氧和连氯的基团。","C":"甲基相连的是碳，原子序数最小之一，优先次序低。","D":"氢的原子序数最小，优先次序最低。","E":"正确，氯的原子序数最大，因此优先次序最高。"},"id":"org08_q04","chapter":"第八章 立体化学基础","chapterIdx":7,"num":4},{"type":"A","stem":"D-甘油醛的绝对构型是","options":{"A":"R 构型","B":"S 构型","C":"外消旋体","D":"内消旋体","E":"无法确定"},"answer":["A"],"rationale":"D-甘油醛中羟基、醛基、羟甲基、氢的优先顺序确定后，按 R/S 判断法得到 R 构型。","expl":{"A":"正确，按次序规则判断 D-甘油醛为 R 构型，D/L 与 R/S 在此对应。","B":"L-甘油醛才是 S 构型，与 D 型相反。","C":"甘油醛是单一对映体，不是外消旋体。","D":"甘油醛只有一个手性碳，不能形成内消旋体。","E":"由结构可直接判定构型，不存在无法确定的问题。"},"id":"org08_q05","chapter":"第八章 立体化学基础","chapterIdx":7,"num":5},{"type":"A","stem":"一对对映体之间的差别是","options":{"A":"熔点一定不同","B":"化学性质完全不同","C":"溶解度一定不同","D":"旋光方向相反，生物活性可以不同","E":"红外光谱完全不同"},"answer":["D"],"rationale":"对映体在非手性环境中物理化学性质相同，但旋光方向相反，在手性环境（如生物体）中活性常显著不同。","expl":{"A":"对映体在非手性溶剂中的熔点相同，不能说一定不同。","B":"对映体与非手性试剂的化学反应完全相同。","C":"对映体在非手性溶剂中溶解度相同，故该项错误。","D":"正确，对映体旋光方向相反，与手性受体作用时生物活性常不同。","E":"对映体的红外光谱在非手性条件下完全相同。"},"id":"org08_q06","chapter":"第八章 立体化学基础","chapterIdx":7,"num":6},{"type":"A","stem":"含两个不相同手性碳原子的化合物，最多可有的立体异构体数目是","options":{"A":"2 个","B":"3 个","C":"4 个","D":"6 个","E":"8 个"},"answer":["C"],"rationale":"两个不相同的手性碳各可有两种构型，组合后共 2 的 2 次方即 4 个立体异构体，且都不存在内消旋。","expl":{"A":"两个手性碳时异构体不止 2 个，2 个是一个手性碳的情况。","B":"3 个是含两个相同手性碳时的数目（含内消旋体）。","C":"正确，两个不同手性碳共有 4 个立体异构体，两对对映体。","D":"6 个不符合 2 的 n 次方规律。","E":"8 个是三个手性碳时的最大数目。"},"id":"org08_q07","chapter":"第八章 立体化学基础","chapterIdx":7,"num":7},{"type":"A","stem":"2,3-二氯丁烷的立体异构体数目是","options":{"A":"2 个","B":"4 个","C":"3 个","D":"5 个","E":"6 个"},"answer":["C"],"rationale":"2,3-二氯丁烷两个手性碳所连基团相同，除一对外消旋体外还有一个内消旋体，共 3 个立体异构体。","expl":{"A":"只考虑一对对映体时遗漏了内消旋体，故数目不正确。","B":"4 个是两个手性碳所连基团不同时的数目，此处有内消旋体。","C":"正确，一对外消旋体加一个内消旋体，共 3 个立体异构体。","D":"5 个不符合该分子的对称性分析结果。","E":"6 个对应三个手性碳的情形，此处只有两个手性碳。"},"id":"org08_q08","chapter":"第八章 立体化学基础","chapterIdx":7,"num":8},{"type":"A","stem":"将外消旋体拆分为两个对映体，常用的方法是","options":{"A":"分馏","B":"萃取","C":"过滤","D":"与手性碱成盐后分级结晶分离","E":"直接重结晶"},"answer":["D"],"rationale":"对映体与非手性试剂作用性质相同，故需先与手性试剂（如手性碱）成盐，生成非对映体后再利用溶解度差异分离。","expl":{"A":"对映体沸点相同，分馏无法拆分。","B":"对映体在非手性溶剂中分配系数相同，萃取无效。","C":"过滤只能分离固液，不能区分对映体。","D":"正确，与手性试剂成盐得到非对映体，再用分级结晶分离后分解回收。","E":"对映体溶解度相同，直接重结晶无法分离。"},"id":"org08_q09","chapter":"第八章 立体化学基础","chapterIdx":7,"num":9},{"type":"A","stem":"(R)-2-溴丁烷在氢氧化钠水溶液中经 SN2 机理水解，产物的主要构型是","options":{"A":"构型完全翻转的(S)-2-丁醇","B":"构型完全保持的(R)-2-丁醇","C":"外消旋体","D":"构型不变","E":"无法判断"},"answer":["A"],"rationale":"SN2 反应中亲核试剂从离去基团背面进攻，中心碳发生瓦尔登翻转，故产物构型与底物相反。","expl":{"A":"正确，背面进攻导致构型翻转，得(S)-2-丁醇。","B":"SN2 是构型翻转过程，不会完全保持原构型。","C":"外消旋化主要出现在 SN1 反应中，SN2 不发生消旋。","D":"构型不变与 SN2 的背面进攻机理矛盾。","E":"SN2 机理明确，产物构型可以确定。"},"id":"org08_q10","chapter":"第八章 立体化学基础","chapterIdx":7,"num":10},{"type":"A","stem":"卤代烃经 SN1 机理水解时，产物的立体化学特征是","options":{"A":"完全构型翻转","B":"外消旋化，通常伴随部分构型翻转","C":"构型完全保持","D":"不发生反应","E":"生成顺反异构体"},"answer":["B"],"rationale":"SN1 反应先形成平面型碳正离子，亲核试剂可从两侧进攻，故产物部分翻转部分保持，总体接近外消旋。","expl":{"A":"完全翻转是 SN2 的特征，SN1 中碳正离子两侧均可被进攻。","B":"正确，平面碳正离子两侧进攻概率相近，产物外消旋化并含部分翻转。","C":"完全保持需要有两次翻转或特殊机理，SN1 不符合。","D":"SN1 条件下反应可以顺利进行，并非不反应。","E":"该反应改变的是手性中心的构型，不产生顺反异构。"},"id":"org08_q11","chapter":"第八章 立体化学基础","chapterIdx":7,"num":11},{"type":"A","stem":"下列各组化合物中，属于构象异构的是","options":{"A":"2-丁醇的一对对映体","B":"顺-2-丁烯与反-2-丁烯","C":"乙醇与二甲醚","D":"正丁烷的对位交叉式与邻位交叉式","E":"丙酮与丙烯醇"},"answer":["D"],"rationale":"构象异构是同一分子因单键旋转而产生的不同空间排列，正丁烷的对位交叉式与邻位交叉式正属此类。","expl":{"A":"对映体属于构型异构，不能用单键旋转相互转化。","B":"顺反异构属构型异构，需断键才能互变。","C":"乙醇与二甲醚是构造异构体，分子式相同而连接方式不同。","D":"正确，两者由 C2-C3 单键旋转产生，是典型的构象异构。","E":"丙酮与丙烯醇是构造异构体，官能团不同。"},"id":"org08_q12","chapter":"第八章 立体化学基础","chapterIdx":7,"num":12},{"type":"X","stem":"关于手性分子，下列说法正确的有","options":{"A":"手性分子与其镜像不能完全重合","B":"有对称面的分子一定没有手性","C":"含两个相同手性碳的分子可能有内消旋体","D":"外消旋体不显旋光性","E":"含手性碳的分子一定有手性"},"answer":["A","B","C","D"],"rationale":"手性分子镜像不重合，有对称面即无手性，含相同手性碳者可形成内消旋体，故 E 错误，其余正确。","expl":{"A":"正确，手性的本质就是分子与其镜像不能重合。","B":"正确，对称面使镜像与分子重合，因此不具手性。","C":"正确，两个构型相反且取代基相同的手性碳可构成内消旋体。","D":"正确，外消旋体中两种对映体的旋光相互抵消。","E":"错误，内消旋体虽含手性碳，但整体无手性。"},"id":"org08_q13","chapter":"第八章 立体化学基础","chapterIdx":7,"num":13},{"type":"X","stem":"关于 R/S 构型标记法，下列说法正确的有","options":{"A":"先按次序规则确定四个基团的优先顺序","B":"最低优先级基团背向观察者时，其余三个基团由高到低顺时针排列为 R","C":"最低优先级基团朝向观察者时，顺时针排列读作 S","D":"手性碳所连的四个基团必须互不相同","E":"只要有两个基团不同即可用 R/S 标记该碳原子"},"answer":["A","B","C","D"],"rationale":"R/S 标记需以四个不同基团的优先顺序和最低优先级基团的朝向判断，故 E 错误，其余各项均正确。","expl":{"A":"正确，先按次序规则排出四个基团的优先顺序是判断前提。","B":"正确，最低优先级背向观察者时，顺时针方向对应 R 构型。","C":"正确，最低优先级朝向观察者时，顺时针方向实际对应 S 构型。","D":"正确，连有相同基团的碳原子不是手性碳，无 R/S 可言。","E":"错误，四个基团必须互不相同，仅两个不同不构成手性中心。"},"id":"org08_q14","chapter":"第八章 立体化学基础","chapterIdx":7,"num":14},{"type":"A","stem":"内消旋酒石酸与(2R,3R)-酒石酸二者的关系是","options":{"A":"同一化合物","B":"非对映体","C":"对映体","D":"外消旋体","E":"构造异构体"},"answer":["B"],"rationale":"内消旋酒石酸的两个手性碳构型相反（2R,3S），分子内有对称面而无旋光性；(2R,3R)-酒石酸是手性分子。二者碳架和连接方式相同、构型不同又互不为镜像，故属非对映体。","expl":{"A":"二者构型不同，不是同一化合物。","B":"正确，都含两个手性碳、碳架相同而构型不同且非镜像关系，属非对映体。","C":"对映体应互为镜像，(2R,3R) 的镜像为 (2S,3S)，而非内消旋体。","D":"外消旋体是等量对映体的混合物，二者都是单一的纯化合物。","E":"构造异构体要求原子的连接顺序不同，二者连接顺序完全相同。"},"id":"org08_q15","chapter":"第八章 立体化学基础","chapterIdx":7,"num":15},{"type":"A","stem":"在(R)-乳酸（2-羟基丙酸）中，与手性碳相连的四个基团按次序规则排在第三位的是","options":{"A":"-OH","B":"-COOH","C":"-H","D":"-CH3"},"answer":["D"],"rationale":"次序规则先比较与手性碳直接相连的原子：氧大于碳，故 -OH 居首；-COOH 与 -CH3 都连碳，再比较第二层原子，羧基碳连有(O,O,O)，甲基碳只连(H,H,H)，故 -COOH 第二位、-CH3 第三位，-H 最小。","expl":{"A":"羟基直接相连的是氧，原子序数最大，排在第一位。","B":"羧基碳连有三个氧，优先于只连氢的甲基，排第二位。","C":"氢的原子序数最小，排在第四位。","D":"正确，甲基碳只连三个氢，优先次序低于羧基而高于氢，排第三位。"},"id":"org08_q16","chapter":"第八章 立体化学基础","chapterIdx":7,"num":16},{"type":"A","stem":"下列化合物中不含手性碳原子但具有手性的是","options":{"A":"2-丁醇","B":"内消旋酒石酸","C":"1,4-二甲基环己烷","D":"2-甲基丙烷","E":"2,3-戊二烯"},"answer":["E"],"rationale":"2,3-戊二烯属于丙二烯型化合物，两个双键所在平面互相垂直，两端碳上各连有 CH3 与 H，分子没有对称面、与其镜像不能重合，因而具有手性，但分子中并没有手性碳原子。","expl":{"A":"2-丁醇的 2 号碳连有四个不同基团，是手性碳，与题意不符。","B":"内消旋酒石酸含两个手性碳，且因有对称面而整体无手性。","C":"1,4-二甲基环己烷有对称面，不具手性。","D":"2-甲基丙烷既无手性碳又有多个对称面，不是手性分子。","E":"正确，2,3-戊二烯靠两个互相垂直的双键形成轴手性，而无手性碳。"},"id":"org08_q17","chapter":"第八章 立体化学基础","chapterIdx":7,"num":17},{"type":"A","stem":"把 Fischer 投影式在纸面内旋转 90 度，所得投影式与原化合物的关系是","options":{"A":"对映体","B":"同一化合物","C":"外消旋体","D":"非对映体","E":"构造异构体"},"answer":["A"],"rationale":"Fischer 投影式规定竖直键朝向纸面后方、水平键朝向前方。在纸面内旋转 90 度会使原本朝后的基团转到朝前，构型随之翻转，得到的是原化合物的对映体；而在纸面内旋转 180 度构型不变。","expl":{"A":"正确，纸面内旋转 90 度改变了前后关系，构型翻转，得到对映体。","B":"只有旋转 180 度或偶数次交换基团才保持同一化合物。","C":"外消旋体是两种对映体的混合物，旋转单个投影式不会生成混合物。","D":"非对映体需要至少两个手性中心的构型差异，此处是整体构型翻转。","E":"旋转不改变原子的连接顺序，不可能是构造异构体。"},"id":"org08_q18","chapter":"第八章 立体化学基础","chapterIdx":7,"num":18}]},{"title":"第九章 卤代烃","questions":[{"type":"A","stem":"(CH3)3CBr 的正确系统名称是","options":{"A":"1-溴-2-甲基丙烷","B":"2-溴丁烷","C":"2-溴-2-甲基丙烷","D":"3-溴-2-甲基丙烷","E":"溴代异丁烷"},"answer":["C"],"rationale":"最长碳链为 3 个碳，溴与甲基均连在 2 位碳上，故系统名称为 2-溴-2-甲基丙烷。","expl":{"A":"溴连在 2 位碳上而不是端位 1 位，故名称不符。","B":"主链只有 3 个碳，不能命名为丁烷。","C":"正确，主链为丙烷，2 位上同时连有溴和甲基，名称规范。","D":"编号应从靠近取代基一端开始，溴在 2 位而非 3 位。","E":"俗名不能代替系统命名，考试中应写系统名称。"},"id":"org09_q01","chapter":"第九章 卤代烃","chapterIdx":8,"num":1},{"type":"A","stem":"下列化合物中属于叔卤代烃的是","options":{"A":"CH3CH2Br","B":"(CH3)2CHBr","C":"CH2=CHBr","D":"PhBr","E":"(CH3)3CBr"},"answer":["E"],"rationale":"卤素所连碳原子同时与三个碳相连的称为叔卤代烃，(CH3)3CBr 中溴连在叔碳上，故属叔卤代烃。","expl":{"A":"溴乙烷中溴连在只与一个碳相连的伯碳上，属伯卤代烃。","B":"2-溴丙烷中溴连在与两个碳相连的仲碳上，属仲卤代烃。","C":"溴乙烯中溴直接连在双键碳上，属乙烯型卤代烃。","D":"溴苯中溴连在苯环碳上，属芳香卤代烃。","E":"正确，溴连在与三个碳相连的叔碳上，是叔卤代烃。"},"id":"org09_q02","chapter":"第九章 卤代烃","chapterIdx":8,"num":2},{"type":"A","stem":"下列卤代烃在 SN2 反应中速率最快的是","options":{"A":"溴甲烷","B":"溴乙烷","C":"2-溴丙烷","D":"2-溴-2-甲基丙烷","E":"溴苯"},"answer":["A"],"rationale":"SN2 反应速率受空间位阻影响极大，溴甲烷碳上无支链、位阻最小，故反应最快。","expl":{"A":"正确，溴甲烷只有一个碳，空间位阻最小，SN2 速率最快。","B":"溴乙烷的甲基增大位阻，速率低于溴甲烷。","C":"2-溴丙烷为仲卤代烃，位阻更大，SN2 速率明显下降。","D":"叔卤代烃位阻最大，几乎不能按 SN2 机理反应。","E":"溴苯为芳香卤代烃，C-Br 键强且背面受阻，SN2 极难进行。"},"id":"org09_q03","chapter":"第九章 卤代烃","chapterIdx":8,"num":3},{"type":"A","stem":"下列卤代烃在 SN1 反应中速率最快的是","options":{"A":"溴甲烷","B":"溴乙烷","C":"2-溴丙烷","D":"溴苯","E":"2-溴-2-甲基丙烷"},"answer":["E"],"rationale":"SN1 反应速率取决于碳正离子的稳定性，叔碳正离子最稳定，故 2-溴-2-甲基丙烷的 SN1 速率最快。","expl":{"A":"溴甲烷生成的甲基碳正离子极不稳定，SN1 速率最慢。","B":"伯碳正离子也不稳定，SN1 速率远低于叔卤代烃。","C":"仲碳正离子稳定性居中，速率低于叔卤代烃。","D":"溴苯难以生成苯基正离子，基本不发生 SN1 反应。","E":"正确，生成的叔碳正离子最稳定，SN1 速率最快。"},"id":"org09_q04","chapter":"第九章 卤代烃","chapterIdx":8,"num":4},{"type":"A","stem":"极性溶剂有利于卤代烃按 SN1 机理反应，其主要原因是","options":{"A":"能溶剂化稳定碳正离子中间体","B":"使亲核试剂更易从背面进攻","C":"增大底物的空间位阻","D":"显著降低反应温度","E":"对反应没有任何影响"},"answer":["A"],"rationale":"SN1 反应的决速步是形成碳正离子，极性溶剂通过溶剂化作用稳定电荷分离的过渡态和碳正离子，从而加快反应。","expl":{"A":"正确，极性溶剂溶剂化碳正离子，降低其能量，加快 SN1 反应。","B":"背面进攻与 SN2 相关，极性溶剂对 SN2 往往不利。","C":"溶剂不会改变底物本身的位阻，位阻由结构决定。","D":"溶剂效应的本质是稳定中间体，不是通过降温起作用。","E":"极性溶剂对 SN1 速率影响显著，绝非没有影响。"},"id":"org09_q05","chapter":"第九章 卤代烃","chapterIdx":8,"num":5},{"type":"A","stem":"2-溴丁烷在乙醇钠的乙醇溶液中加热，主要产物是","options":{"A":"1-丁烯","B":"2-丁烯","C":"丁烷","D":"1-丁醇","E":"2-丁醇"},"answer":["B"],"rationale":"按扎依采夫规则，消除时优先形成双键碳上取代基较多、更稳定的烯烃，故主要产物为 2-丁烯。","expl":{"A":"1-丁烯是取代较少的烯烃，热力学稳定性差，为次要产物。","B":"正确，2-丁烯双键取代多、更稳定，是主要消除产物。","C":"该条件下发生消除而不是还原，不生成丁烷。","D":"强碱醇溶液以消除为主，水解生成醇只是次要途径。","E":"生成 2-丁醇需要水溶液条件，与本题强碱醇溶液不符。"},"id":"org09_q06","chapter":"第九章 卤代烃","chapterIdx":8,"num":6},{"type":"A","stem":"2-溴-2-甲基丙烷在乙醇中加热，主要进行的反应类型是","options":{"A":"SN2 取代","B":"E2 消除","C":"SN1 取代","D":"E1 消除","E":"自由基取代"},"answer":["D"],"rationale":"叔卤代烃在质子溶剂中加热时，先离解生成稳定叔碳正离子，再失去β-氢形成烯烃，主要发生 E1 消除。","expl":{"A":"叔卤代烃位阻大，不能按 SN2 机理进行。","B":"E2 需要强碱，乙醇是弱碱，故不以 E2 为主。","C":"SN1 取代可发生，但在加热的醇溶液中消除产物占优。","D":"正确，经叔碳正离子失去β-氢，主要进行 E1 消除生成异丁烯。","E":"该反应为离子型，不是自由基取代过程。"},"id":"org09_q07","chapter":"第九章 卤代烃","chapterIdx":8,"num":7},{"type":"A","stem":"实验室制备格氏试剂时，最常用的溶剂是","options":{"A":"水","B":"无水乙醚","C":"乙醇","D":"稀盐酸","E":"氢氧化钠水溶液"},"answer":["B"],"rationale":"格氏试剂遇质子溶剂立即分解，故须在无水乙醚等惰性非质子溶剂中制备，乙醚还能溶剂化稳定试剂。","expl":{"A":"格氏试剂遇水剧烈分解生成烷烃，不能用水作溶剂。","B":"正确，无水乙醚不含活泼氢，且能配位稳定格氏试剂。","C":"乙醇含活泼氢，会使格氏试剂分解。","D":"稀盐酸的质子会使格氏试剂立即分解。","E":"碱性水溶液仍含水，同样破坏格氏试剂。"},"id":"org09_q08","chapter":"第九章 卤代烃","chapterIdx":8,"num":8},{"type":"A","stem":"格氏试剂与二氧化碳反应后再酸性水解，生成的产物是","options":{"A":"醇","B":"醛","C":"酮","D":"烃","E":"羧酸"},"answer":["E"],"rationale":"格氏试剂对二氧化碳发生亲核加成，生成羧酸镁盐，酸化后即得多一个碳的羧酸，是增长碳链的方法之一。","expl":{"A":"与醛酮加成才生成醇，二氧化碳加成产物为羧酸。","B":"格氏试剂与甲酸酯等才生成醛，与二氧化碳不生成醛。","C":"与腈或酰氯反应可得酮，二氧化碳的产物是羧酸。","D":"格氏试剂与水反应才生成烃，与二氧化碳反应生成羧酸。","E":"正确，加成并水解后得到比原卤代烃多一个碳的羧酸。"},"id":"org09_q09","chapter":"第九章 卤代烃","chapterIdx":8,"num":9},{"type":"A","stem":"下列卤代烃在硝酸银的乙醇溶液中加热也不产生沉淀的是","options":{"A":"溴乙烷","B":"氯化苄","C":"氯苯","D":"2-溴丙烷","E":"溴甲烷"},"answer":["C"],"rationale":"氯苯中氯直接连在苯环上，C-Cl 键因共轭而强，且不能形成稳定碳正离子，故与硝酸银醇溶液不反应。","expl":{"A":"溴乙烷可生成溴化银沉淀，只是速率较慢。","B":"氯化苄生成苄基碳正离子很稳定，迅速析出氯化银沉淀。","C":"正确，氯苯的 C-Cl 键牢固，加热也不产生沉淀，可用于鉴别。","D":"2-溴丙烷为仲卤代烃，可生成溴化银沉淀。","E":"溴甲烷在加热下也能缓慢生成溴化银沉淀。"},"id":"org09_q10","chapter":"第九章 卤代烃","chapterIdx":8,"num":10},{"type":"A","stem":"溴乙烷与氰化钠在乙醇中反应，生成的主要产物是","options":{"A":"丙腈","B":"乙腈","C":"乙胺","D":"乙醇","E":"乙酸"},"answer":["A"],"rationale":"氰离子作为亲核试剂按 SN2 机理进攻溴乙烷，取代溴原子并引入氰基，碳链增长一个碳，得丙腈。","expl":{"A":"正确，氰基取代溴后碳数增加一个，生成丙腈。","B":"乙腈需由溴甲烷氰化得到，乙基被氰取代后应为丙腈。","C":"氰基还原才生成胺，本反应产物是腈。","D":"生成醇需在碱性水溶液中水解，而非氰化。","E":"腈水解才生成羧酸，本步只得到腈。"},"id":"org09_q11","chapter":"第九章 卤代烃","chapterIdx":8,"num":11},{"type":"A","stem":"卤代烃在强碱的醇溶液中主要按 E2 机理消除，其反应速率","options":{"A":"只与底物浓度成正比","B":"与底物浓度和碱浓度的乘积成正比","C":"只与碱浓度成正比","D":"与两者浓度均无关","E":"只与溶剂极性成正比"},"answer":["B"],"rationale":"E2 是双分子消除反应，决速步中碱夺取β-氢与卤素离去同时进行，故速率与底物和碱的浓度均成正比。","expl":{"A":"只与底物浓度成正比是一级反应，对应 E1 而非 E2。","B":"正确，E2 为二级反应，速率与底物和碱浓度乘积成正比。","C":"仅与碱浓度成正比不符合 E2 的双分子特征。","D":"E2 速率与两种反应物浓度都有关，不可能无关。","E":"溶剂极性影响速率，但不能说只与极性成正比。"},"id":"org09_q12","chapter":"第九章 卤代烃","chapterIdx":8,"num":12},{"type":"X","stem":"关于卤代烃的 SN2 反应，下列说法正确的有","options":{"A":"底物空间位阻越大，反应速率越慢","B":"增大亲核试剂的浓度可加快反应速率","C":"使用极性非质子溶剂通常有利于反应","D":"离去基团越好，反应越容易进行","E":"叔卤代烃最容易发生 SN2 反应"},"answer":["A","B","C","D"],"rationale":"SN2 受位阻、亲核试剂浓度、溶剂和离去基团共同影响，位阻越大越慢，故叔卤代烃反而不易发生 SN2。","expl":{"A":"正确，背面进攻受位阻阻碍，位阻越大 SN2 越慢。","B":"正确，SN2 速率与亲核试剂浓度成正比。","C":"正确，极性非质子溶剂不溶剂化亲核试剂，利于其进攻。","D":"正确，离去基团越易离去，反应活化能越低。","E":"错误，叔卤代烃位阻大，几乎不能进行 SN2 反应。"},"id":"org09_q13","chapter":"第九章 卤代烃","chapterIdx":8,"num":13},{"type":"X","stem":"关于格氏试剂，下列说法正确的有","options":{"A":"由卤代烃与金属镁在无水乙醚中制备","B":"遇水分解生成相应的烷烃","C":"与醛加成水解后生成醇","D":"与二氧化碳反应水解后生成羧酸","E":"可以在水溶液中稳定存在"},"answer":["A","B","C","D"],"rationale":"格氏试剂须在无水条件下制备和使用，遇质子溶剂立即分解，故 E 错误，其余各项均正确。","expl":{"A":"正确，卤代烃与镁在无水乙醚中反应制得格氏试剂。","B":"正确，格氏试剂是强碱，遇水夺取质子生成烷烃。","C":"正确，与醛加成后水解得到相应的醇。","D":"正确，与二氧化碳加成并酸化得到多一个碳的羧酸。","E":"错误，格氏试剂遇水迅速分解，不能在水溶液中存在。"},"id":"org09_q14","chapter":"第九章 卤代烃","chapterIdx":8,"num":14},{"type":"A","stem":"烯丙型卤代烃在 SN1 和 SN2 反应中都比相应的烷基卤代烃活泼，主要原因是","options":{"A":"卤素原子的电负性更小","B":"碳卤键的键能更大","C":"分子中没有 β-氢","D":"生成的碳正离子和过渡态都受相邻 π 键共轭稳定","E":"烯丙型卤代烃更易溶于水"},"answer":["D"],"rationale":"烯丙位碳正离子的空 p 轨道与相邻双键的 π 轨道共轭，正电荷得到分散而特别稳定，SN1 速率大大提高；SN2 的过渡态中部分正电荷同样被 π 键共轭稳定，故两条机理都加快。","expl":{"A":"卤素相同则电负性相同，速率差异来自烃基结构。","B":"烯丙位的碳卤键并不更强，其解离能反而较低。","C":"烯丙型卤代烃通常含有 β-氢，β-氢与 SN1、SN2 的速率无直接关系。","D":"正确，碳正离子与过渡态都被相邻 π 键共轭稳定，故两种机理都加快。","E":"溶解性不是反应速率显著提高的原因。"},"id":"org09_q15","chapter":"第九章 卤代烃","chapterIdx":8,"num":15},{"type":"A","stem":"E2 消除反应在立体化学上要求","options":{"A":"亲核试剂从离去基团背面进攻","B":"β-氢与离去基团处于同一侧（顺式共平面）","C":"β-氢与离去基团处于反式共平面","D":"先形成平面碳正离子再失去质子","E":"没有立体化学要求"},"answer":["C"],"rationale":"E2 是协同的单步反应，碱夺取 β-氢、C-H 键电子形成 π 键与离去基团离去同时发生，要求过渡态中 β-氢与离去基团处于反式共平面，这样两个正在形成的 p 轨道才能平行重叠。","expl":{"A":"背面进攻是 SN2 的特征，E2 中碱进攻的是 β-氢而不是中心碳。","B":"顺式共平面时新形成的 p 轨道不能有效重叠，消除难以进行。","C":"正确，E2 要求 β-氢与离去基团反式共平面，属反式消除。","D":"先形成碳正离子是 E1 的特征，E2 不经过碳正离子。","E":"E2 对立体化学有明确要求，产物的立体化学由此决定。"},"id":"org09_q16","chapter":"第九章 卤代烃","chapterIdx":8,"num":16},{"type":"A","stem":"2-溴丁烷与叔丁醇钾在叔丁醇中加热，生成的主要产物是","options":{"A":"1-丁烯","B":"2-丁烯","C":"丁烷","D":"2-丁醇","E":"1-丁醇"},"answer":["A"],"rationale":"叔丁醇钾是体积很大的强碱，更容易夺取位阻较小的端位 β-氢，故主要生成取代较少的 1-丁烯，即霍夫曼产物；若用体积较小的乙醇钠，则遵循扎依采夫规则主要得 2-丁烯。","expl":{"A":"正确，大位阻碱优先夺取端位氢，主要生成霍夫曼产物 1-丁烯。","B":"2-丁烯是小位阻碱（如乙醇钠）作用下的扎依采夫产物。","C":"强碱的醇溶液以消除为主，不生成烷烃。","D":"生成 2-丁醇需要氢氧化钠水溶液等取代条件。","E":"1-丁醇需经取代反应才能得到，与消除产物不符。"},"id":"org09_q17","chapter":"第九章 卤代烃","chapterIdx":8,"num":17},{"type":"A","stem":"格氏试剂与环氧乙烷反应后再经酸性水解，生成的产物是","options":{"A":"仲醇","B":"叔醇","C":"酮","D":"比原烃基多两个碳的伯醇","E":"羧酸"},"answer":["D"],"rationale":"环氧乙烷是三元环醚，格氏试剂的烃基作为亲核试剂进攻位阻小的环碳，开环后碳链延长两个碳，酸化水解得到伯醇，这是由卤代烃制备多两个碳的伯醇的常用方法。","expl":{"A":"仲醇需格氏试剂与醛加成，环氧乙烷开环得到的是伯醇。","B":"叔醇需格氏试剂与酮或酯加成，环氧乙烷不能生成叔醇。","C":"格氏试剂与环氧乙烷加成后水解得醇，不生成酮。","D":"正确，开环使碳链增加两个碳，末端为伯醇羟基。","E":"羧酸需格氏试剂与二氧化碳反应才能得到。"},"id":"org09_q18","chapter":"第九章 卤代烃","chapterIdx":8,"num":18}]},{"title":"第十章 醇、酚、醚","questions":[{"type":"A","stem":"下列化合物中酸性最强的是","options":{"A":"乙醇","B":"苯酚","C":"碳酸","D":"乙酸","E":"水"},"answer":["D"],"rationale":"乙酸的 pKa 约为 4.76，酸性明显强于碳酸、苯酚、水与乙醇，故四者中乙酸酸性最强。","expl":{"A":"乙醇 pKa 约 16，是弱酸，酸性远低于乙酸。","B":"苯酚 pKa 约 10，虽比醇强，但仍弱于乙酸。","C":"碳酸一级电离 pKa 约 6.4，酸性弱于乙酸。","D":"正确，乙酸 pKa 约 4.76，是题给物质中酸性最强的。","E":"水的 pKa 约 15.7，酸性远弱于乙酸。"},"id":"org10_q01","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":1},{"type":"A","stem":"与苯酚相比，对硝基苯酚的酸性","options":{"A":"明显增强","B":"明显减弱","C":"基本相同","D":"完全消失","E":"无法比较"},"answer":["A"],"rationale":"硝基是强吸电子基，通过诱导和共轭效应分散酚氧负离子的电荷，使其更稳定，故酸性增强。","expl":{"A":"正确，硝基稳定酚氧负离子，使对硝基苯酚酸性强于苯酚。","B":"吸电子基使酸性增强而不是减弱。","C":"取代基对酚羟基酸性影响显著，不可能基本相同。","D":"对硝基苯酚仍有明显酸性，能与碱成盐。","E":"取代基效应有明确规律，可以比较强弱。"},"id":"org10_q02","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":2},{"type":"A","stem":"下列醇与浓盐酸反应速率最快的是","options":{"A":"甲醇","B":"乙醇","C":"异丙醇","D":"叔丁醇","E":"苯酚"},"answer":["D"],"rationale":"醇与氢卤酸反应经碳正离子机理，叔丁醇生成最稳定的叔碳正离子，故反应速率最快。","expl":{"A":"甲醇生成极不稳定的甲基碳正离子，反应最慢。","B":"乙醇经伯碳正离子，速率慢于仲醇和叔醇。","C":"异丙醇经仲碳正离子，速率快于伯醇但慢于叔醇。","D":"正确，叔丁醇生成稳定叔碳正离子，与浓盐酸反应最快。","E":"苯酚的 C-O 键因共轭而强，不与浓盐酸发生取代。"},"id":"org10_q03","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":3},{"type":"A","stem":"2-丁醇在浓硫酸中加热脱水，主要产物是","options":{"A":"1-丁烯","B":"乙醚","C":"丁烷","D":"2-丁烯","E":"丁醛"},"answer":["D"],"rationale":"醇脱水遵循扎依采夫规则，优先生成双键碳上取代基较多、更稳定的烯烃，故主要产物为 2-丁烯。","expl":{"A":"1-丁烯取代较少、较不稳定，是次要产物。","B":"分子间脱水成醚需较低温度，加热脱水以分子内消除为主。","C":"脱水反应不引入氢，不生成丁烷。","D":"正确，2-丁烯更稳定，是主要脱水产物。","E":"脱水生成烯烃，不生成醛，醛需氧化才能得到。"},"id":"org10_q04","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":4},{"type":"A","stem":"异丙醇在酸性重铬酸钾溶液中氧化，主要产物是","options":{"A":"丙醛","B":"丙酸","C":"丙酮","D":"丙烯","E":"丙烷"},"answer":["C"],"rationale":"异丙醇是仲醇，氧化时羟基所连碳只脱去一个氢，生成酮，故主要产物为丙酮，酮一般不易继续氧化。","expl":{"A":"丙醛是伯醇氧化产物，异丙醇为仲醇，氧化得酮。","B":"仲醇氧化成酮后一般不再继续氧化为羧酸。","C":"正确，异丙醇被氧化为丙酮，是仲醇的典型反应。","D":"氧化条件下不会脱水生成丙烯，需浓硫酸加热。","E":"丙烷是还原产物，与氧化反应无关。"},"id":"org10_q05","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":5},{"type":"A","stem":"苯酚与溴水反应，观察到的现象是","options":{"A":"生成白色沉淀","B":"溶液变为无色透明","C":"生成溴苯","D":"生成苯甲酸","E":"无明显现象"},"answer":["A"],"rationale":"羟基强烈活化苯环，使苯酚与溴水迅速发生亲电取代，生成 2,4,6-三溴苯酚白色沉淀。","expl":{"A":"正确，苯酚与溴水生成 2,4,6-三溴苯酚白色沉淀，现象明显。","B":"苯酚与溴水发生取代反应，不会得到无色透明溶液。","C":"溴苯需苯与液溴在铁催化下反应，与苯酚无关。","D":"该反应是溴代而不是氧化成羧酸。","E":"反应迅速且现象明显，不会无明显变化。"},"id":"org10_q06","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":6},{"type":"A","stem":"苯酚与三氯化铁溶液作用，呈现的颜色是","options":{"A":"蓝色","B":"绿色","C":"黄色","D":"紫红色","E":"不显色"},"answer":["D"],"rationale":"酚羟基与铁离子形成有色配合物，苯酚显紫红色，这是酚类的常用鉴别反应之一。","expl":{"A":"蓝色不是苯酚与三氯化铁所显的颜色。","B":"绿色通常不出现于该显色反应中。","C":"黄色并不是酚羟基与铁离子形成配合物的特征颜色，该显色反应一般呈紫红色。","D":"正确，苯酚与三氯化铁生成紫红色配合物，可用于鉴别酚羟基。","E":"苯酚含酚羟基，能与铁离子显色，不会不显色。"},"id":"org10_q07","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":7},{"type":"A","stem":"乙醇钠与溴乙烷反应，生成的主要产物是","options":{"A":"乙醇","B":"乙烯","C":"乙醛","D":"乙酸乙酯","E":"乙醚"},"answer":["E"],"rationale":"乙醇钠作为亲核试剂进攻溴乙烷的α-碳，溴离子离去，两个乙基通过氧相连，生成乙醚，即威廉姆逊合成法。","expl":{"A":"乙醇是反应物醇钠的对应醇，不是该取代反应产物。","B":"生成乙烯需强碱高温消除，此处以取代成醚为主。","C":"反应不涉及氧化，不会生成乙醛。","D":"乙酸乙酯需酯化反应，本题无羧酸参与。","E":"正确，醇钠与卤代烷发生威廉姆逊合成，生成乙醚。"},"id":"org10_q08","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":8},{"type":"A","stem":"乙醚与一分子浓氢碘酸共热，生成的产物是","options":{"A":"两分子碘乙烷","B":"一分子乙醇和一分子碘乙烷","C":"乙烯和乙醇","D":"不反应","E":"乙酸乙酯"},"answer":["B"],"rationale":"醚在强酸中先质子化，碘离子进攻较小烷基生成一分子碘代烷，同时生成一分子醇；过量氢碘酸则生成两分子碘代烷。","expl":{"A":"生成两分子碘乙烷需过量氢碘酸，一分子酸只能断裂一侧。","B":"正确，一分子氢碘酸断裂一个 C-O 键，生成乙醇和碘乙烷。","C":"醚断裂不生成烯烃，除非在强热消去条件下。","D":"醚可被浓氢碘酸断裂，并非不反应。","E":"醚的断裂反应体系中并没有羧酸参与，因此不会生成酯类化合物。"},"id":"org10_q09","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":9},{"type":"A","stem":"环氧乙烷在酸催化下与甲醇反应，主要产物是","options":{"A":"乙二醇","B":"二甲醚","C":"乙醇","D":"甲酸","E":"乙二醇单甲醚"},"answer":["E"],"rationale":"酸性条件下甲醇进攻质子化的环氧乙烷，开环后在一个碳上加甲氧基、另一个碳上保留羟基，得乙二醇单甲醚。","expl":{"A":"乙二醇需用水开环才能生成，本题亲核试剂是甲醇。","B":"二甲醚由甲醇分子间脱水生成，与环氧开环无关。","C":"开环产物一端为甲氧基，不是乙基，故不是乙醇。","D":"开环产物含甲氧基和羟基，属醚醇类化合物，分子中并没有羧基，不生成羧酸。","E":"正确，甲醇开环后得到含甲氧基和羟基的乙二醇单甲醚。"},"id":"org10_q10","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":10},{"type":"A","stem":"乙醇的沸点比相对分子质量相近的二甲醚高，主要原因是","options":{"A":"乙醇分子间能形成氢键","B":"乙醇分子间不能形成氢键","C":"乙醇的极性比二甲醚小","D":"二甲醚分子间能形成氢键","E":"乙醇的相对分子质量更大"},"answer":["A"],"rationale":"乙醇含羟基，分子间可形成氢键，需要额外能量才能气化，故沸点显著高于不能形成氢键的二甲醚。","expl":{"A":"正确，羟基氢键使乙醇分子间缔合，沸点明显升高。","B":"乙醇恰恰能形成分子间氢键，该项说法与事实相反。","C":"乙醇极性与二甲醚相近，不是沸点差异的主因。","D":"二甲醚无羟基，分子间不能形成氢键。","E":"两者相对分子质量相同，不能解释沸点差异。"},"id":"org10_q11","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":11},{"type":"A","stem":"苯酚能与氢氧化钠溶液反应，却不与碳酸氢钠溶液反应，这说明","options":{"A":"苯酚是强酸","B":"苯酚酸性强于碳酸","C":"苯酚没有酸性","D":"苯酚与乙酸的酸性相同","E":"苯酚酸性弱于碳酸"},"answer":["E"],"rationale":"苯酚能溶于氢氧化钠说明有酸性，但不能与碳酸氢钠放出二氧化碳，说明其酸性弱于碳酸，故不能置换碳酸。","expl":{"A":"苯酚 pKa 约 10，属弱酸，不是强酸。","B":"若酸性强于碳酸则会与碳酸氢钠反应放出二氧化碳，事实相反。","C":"苯酚能与氢氧化钠成盐，说明确有酸性。","D":"乙酸 pKa 约 4.76，酸性远强于苯酚。","E":"正确，由不置换碳酸可判断苯酚酸性弱于碳酸。"},"id":"org10_q12","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":12},{"type":"X","stem":"下列化合物能与三氯化铁溶液显色的有","options":{"A":"苯酚","B":"乙醇","C":"对甲基苯酚","D":"邻苯二酚","E":"苯甲醚"},"answer":["A","C","D"],"rationale":"含酚羟基的化合物能与铁离子形成有色配合物，苯酚、对甲基苯酚、邻苯二酚均显色，而乙醇和苯甲醚不能。","expl":{"A":"正确，苯酚含酚羟基，与三氯化铁显紫红色。","B":"乙醇是脂肪醇，羟基不能与铁离子形成该有色配合物。","C":"正确，对甲基苯酚含酚羟基，同样能与铁离子显色。","D":"正确，邻苯二酚含两个酚羟基，显色更深。","E":"苯甲醚中羟基已被醚化，无酚羟基，不显色。"},"id":"org10_q13","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":13},{"type":"X","stem":"关于醇的氧化反应，下列说法正确的有","options":{"A":"伯醇氧化先生成醛，可进一步氧化为羧酸","B":"仲醇氧化生成酮","C":"叔醇一般不被氧化","D":"可用酸性重铬酸钾或高锰酸钾作氧化剂","E":"伯醇氧化一定停留在醛这一步"},"answer":["A","B","C","D"],"rationale":"伯醇氧化成醛并可继续氧化成酸，仲醇氧化成酮，叔醇无α-氢故一般不被氧化，故 E 错误。","expl":{"A":"正确，伯醇先氧化为醛，强烈氧化条件下继续生成羧酸。","B":"正确，仲醇羟基所连碳只有一个氢，氧化产物为酮。","C":"正确，叔醇没有α-氢，一般条件下不被氧化。","D":"正确，酸性重铬酸钾和高锰酸钾都是常用氧化剂。","E":"错误，伯醇在强氧化条件下会继续氧化成羧酸，不会一定停在醛。"},"id":"org10_q14","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":14},{"type":"A","stem":"用高碘酸氧化邻二醇类化合物时，能被氧化的结构要求是","options":{"A":"两个羟基位于相邻碳上且处于顺式，能形成环状高碘酸酯","B":"两个羟基位于相邻碳上且处于反式","C":"两个羟基连在同一个碳原子上","D":"两个羟基分别位于相隔一个碳的两个碳原子上","E":"分子中只要有一个羟基即可"},"answer":["A"],"rationale":"高碘酸氧化需先与底物生成五元环状高碘酸酯，因此两个羟基必须位于相邻碳上且空间上彼此靠近（顺式）；反式邻二醇难以成环，1,3-二醇和只含一个羟基的醇均不被氧化，故只有顺式邻二醇的碳碳键被氧化断裂。","expl":{"A":"正确，顺式邻二醇生成环状高碘酸酯后 C—C 键断裂，得到两分子醛或酮。","B":"反式邻二醇的两个羟基相距较远，难以形成五元环状中间体，一般不被氧化。","C":"同碳二醇（偕二醇）极不稳定，高碘酸氧化针对的是相邻碳上的两个羟基。","D":"1,3-二醇不能形成五元环状高碘酸酯，故不与高碘酸反应。","E":"只有一个羟基的醇不能被高碘酸氧化，需两个相邻羟基才能断裂碳碳键。"},"id":"org10_q15","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":15},{"type":"A","stem":"用威廉姆逊合成法制备甲基叔丁基醚，最合适的原料组合是","options":{"A":"甲醇钠与叔丁基溴","B":"叔丁醇钠与溴甲烷","C":"叔丁醇与甲醇在浓硫酸中加热","D":"叔丁基溴与甲醇直接加热","E":"叔丁醇钠与叔丁基溴"},"answer":["B"],"rationale":"威廉姆逊合成是醇钠与卤代烷之间的 SN2 反应。叔丁基溴是叔卤代烷，遇强碱性醇钠主要发生 E2 消除生成异丁烯，故应选用位阻大、不能发生消除的叔丁醇钠与位阻小、只能发生取代的溴甲烷反应，才能高产率得到甲基叔丁基醚。","expl":{"A":"甲醇钠是强碱，会使叔丁基溴主要发生消除生成异丁烯，醚的产率很低。","B":"正确，叔丁醇钠提供叔丁氧基，溴甲烷只发生 SN2 取代，顺利生成甲基叔丁基醚。","C":"叔醇在浓硫酸中加热主要脱水成烯烃，分子间脱水成醚的产率很低。","D":"叔丁基溴与甲醇直接加热缺少缚酸剂，主要发生消除，不是合理方法。","E":"两个叔丁基位阻太大，SN2 难以进行，主要产物仍是异丁烯。"},"id":"org10_q16","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":16},{"type":"A","stem":"3,3-二甲基-2-丁醇在酸催化下脱水，主要产物是","options":{"A":"3,3-二甲基-1-丁烯","B":"2,3-二甲基-1-丁烯","C":"2,3-二甲基-2-丁烯","D":"2,2-二甲基丁烷","E":"2,3-二甲基-2-丁醇"},"answer":["C"],"rationale":"酸催化脱水先质子化羟基并失水，生成 C2 的仲碳正离子；由于相邻 C3 是季碳，发生 1,2-甲基迁移形成更稳定的叔碳正离子，再失去β-氢，得到取代程度最高、热力学最稳定的 2,3-二甲基-2-丁烯。","expl":{"A":"端位双键取代基最少、最不稳定，不是主要产物。","B":"该烯烃双键在端位，取代程度低，稳定性明显不如四取代烯烃。","C":"正确，经 1,2-甲基迁移生成叔碳正离子后脱氢，得四取代的稳定烯烃。","D":"脱水生成烯烃，只有加氢才可能得到烷烃。","E":"这是原料醇，属于未反应的底物而非脱水产物。"},"id":"org10_q17","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":17},{"type":"A","stem":"环氧丙烷在碱性条件下与甲醇反应，亲核试剂主要进攻的碳原子是","options":{"A":"取代较多的仲碳，因为该碳正电性较强","B":"取代较少的端基碳，因为该处空间位阻小","C":"两个碳原子机会均等，产物无选择性","D":"环氧环外的甲基碳原子","E":"碱催化下环氧环不开环"},"answer":["B"],"rationale":"碱性条件下开环是典型的 SN2 过程，亲核试剂从位阻小的一侧进攻环氧氧所连的端基碳；而在酸性条件下环氧氧被质子化，过渡态带较多正电荷，才转向取代较多、能稳定正电荷的碳，因此两种条件下的区域选择性恰好相反。","expl":{"A":"这是酸催化开环的取向，碱性条件下碳正离子特征不明显，位阻起决定作用。","B":"正确，SN2 进攻位阻最小的端基碳，甲氧基连在端基碳上。","C":"碱性开环有明确的区域选择性，并非各占一半。","D":"甲基碳不在环氧环上，进攻它不能开环。","E":"醇钠、醇钾等碱可使环氧环开环，反应可顺利进行。"},"id":"org10_q18","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":18}]},{"title":"第十一章 醛、酮、醌","questions":[{"type":"A","stem":"下列羰基化合物中，亲核加成活性最强的是","options":{"A":"苯甲醛","B":"苯乙酮","C":"丙酮","D":"乙醛","E":"甲醛"},"answer":["E"],"rationale":"羰基碳正电性越强、空间位阻越小则亲核加成越快，甲醛无烷基给电子也无位阻，故活性最强。","expl":{"A":"苯甲醛的苯环与羰基共轭，降低了羰基碳的正电性，活性较低。","B":"苯乙酮既有共轭又有甲基位阻，活性更低。","C":"丙酮有两个给电子的甲基，羰基碳正电性降低，活性弱于醛。","D":"乙醛活性高于酮，但有一个甲基给电子，仍弱于甲醛。","E":"正确，甲醛无给电子基且位阻最小，亲核加成活性最强。"},"id":"org11_q01","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":1},{"type":"A","stem":"丙酮与 HCN 加成后，再将产物水解，生成的是","options":{"A":"2-羟基丙酸","B":"丙酸","C":"丙酮酸","D":"乙酸","E":"2-羟基-2-甲基丙酸"},"answer":["E"],"rationale":"丙酮与 HCN 加成生成氰醇，氰基水解为羧基，羰基碳上保留羟基和一个甲基，故得 2-羟基-2-甲基丙酸。","expl":{"A":"2-羟基丙酸由乙醛的氰醇水解得到，丙酮多一个甲基。","B":"丙酸不含羟基，而氰醇水解后羰基碳上必然保留羟基。","C":"丙酮酸是α-酮酸，本题产物为α-羟基酸。","D":"碳数不符，丙酮含三个碳，产物应为四碳酸。","E":"正确，氰醇水解后在原羰基碳上同时有羟基和羧基，得 2-羟基-2-甲基丙酸。"},"id":"org11_q02","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":2},{"type":"A","stem":"乙醛与甲基碘化镁反应后水解，主要产物是","options":{"A":"乙醇","B":"异丙醇","C":"正丙醇","D":"2-丁醇","E":"丙酮"},"answer":["B"],"rationale":"格氏试剂对乙醛的羰基加成，甲基连到羰基碳上，水解后该碳变为连有羟基的仲醇碳，生成异丙醇。","expl":{"A":"乙醇需还原乙醛才能得到，格氏加成引入了新的碳。","B":"正确，甲基加到羰基碳上，水解后生成异丙醇。","C":"正丙醇为伯醇，格氏加成于醛得到的是仲醇。","D":"2-丁醇需格氏试剂与甲乙酮等反应才能得到。","E":"格氏试剂对醛加成后水解得到的是醇，不会生成酮，故该选项错误。"},"id":"org11_q03","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":3},{"type":"A","stem":"乙醛在稀碱溶液中发生的主要反应是","options":{"A":"坎尼扎罗反应","B":"卤仿反应","C":"酯化反应","D":"羟醛缩合反应","E":"重排反应"},"answer":["D"],"rationale":"乙醛含α-氢，在稀碱中生成烯醇负离子并进攻另一分子醛的羰基，发生羟醛缩合生成β-羟基醛。","expl":{"A":"坎尼扎罗反应是无α-氢醛在浓碱中的歧化，乙醛有α-氢故不适用。","B":"卤仿反应需要卤素和碱，仅有稀碱不能发生。","C":"酯化反应需要羧酸与醇共同参与，乙醛既不是羧酸也不是醇，不能发生酯化。","D":"正确，乙醛含α-氢，在稀碱中发生羟醛缩合。","E":"稀碱条件下乙醛只发生羟醛缩合，不会发生骨架重排反应，故该项错误。"},"id":"org11_q04","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":4},{"type":"A","stem":"下列化合物不能发生碘仿反应的是","options":{"A":"乙醛","B":"丙酮","C":"乙醇","D":"苯乙酮","E":"3-戊酮"},"answer":["E"],"rationale":"碘仿反应要求分子中含有 CH3CO- 结构或可氧化成该结构的醇，3-戊酮两端均为乙基，不含甲基酮结构。","expl":{"A":"乙醛含 CH3CO- 结构，可发生碘仿反应。","B":"丙酮是典型的甲基酮，能生成碘仿。","C":"乙醇可被次碘酸钠氧化为乙醛，故也呈阳性。","D":"苯乙酮含 CH3CO- 结构，能发生碘仿反应。","E":"正确，3-戊酮无 CH3CO- 结构，不能发生碘仿反应。"},"id":"org11_q05","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":5},{"type":"A","stem":"无α-氢的醛在浓碱溶液中发生的反应是","options":{"A":"羟醛缩合反应","B":"康尼查罗反应","C":"卤仿反应","D":"氧化反应","E":"酯化反应"},"answer":["B"],"rationale":"无α-氢的醛在浓碱中不能发生羟醛缩合，只能发生自身氧化还原的歧化反应，即康尼查罗反应。","expl":{"A":"羟醛缩合必须有α-氢参与，无α-氢的醛不能进行。","B":"正确，两分子醛一分子被氧化成酸、一分子被还原成醇，即歧化反应。","C":"卤仿反应需卤素参与并含甲基酮结构，此处条件不符。","D":"该反应中同时发生氧化与还原，不只是氧化。","E":"酯化需羧酸和醇，与醛在浓碱中的行为无关。"},"id":"org11_q06","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":6},{"type":"A","stem":"下列化合物能发生银镜反应的是","options":{"A":"丙酮","B":"苯乙酮","C":"苯甲醛","D":"叔丁醇","E":"乙酸"},"answer":["C"],"rationale":"托伦试剂可氧化醛基而自身析出银镜，苯甲醛含醛基，故能发生银镜反应；酮、醇、羧酸均不能。","expl":{"A":"丙酮是酮，不能被托伦试剂氧化，无银镜。","B":"苯乙酮为酮，不能还原托伦试剂。","C":"正确，苯甲醛含醛基，可被氧化并析出银镜。","D":"叔丁醇属于醇类，不能被托伦试剂氧化，因此不会产生银镜。","E":"乙酸是羧酸，不能还原托伦试剂产生银镜。"},"id":"org11_q07","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":7},{"type":"A","stem":"下列化合物中，不能被斐林试剂氧化的是","options":{"A":"苯甲醛","B":"甲醛","C":"乙醛","D":"甲酸","E":"葡萄糖"},"answer":["A"],"rationale":"斐林试剂氧化能力较弱，芳香醛不能还原斐林试剂，故常用斐林试剂区别脂肪醛与芳香醛。","expl":{"A":"正确，苯甲醛是芳香醛，不能被斐林试剂氧化，也不产生砖红色沉淀。","B":"甲醛是脂肪醛，能被斐林试剂氧化。","C":"乙醛能被斐林试剂氧化生成砖红色氧化亚铜沉淀。","D":"甲酸虽为羧酸但含醛基结构，能还原斐林试剂。","E":"葡萄糖是还原糖，能与斐林试剂反应。"},"id":"org11_q08","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":8},{"type":"A","stem":"丙酮与锌汞齐、浓盐酸共热，生成的产物是","options":{"A":"丙烯","B":"异丙醇","C":"正丙醇","D":"丙烷","E":"不反应"},"answer":["D"],"rationale":"这是克莱门森还原，将羰基完全还原为亚甲基，故丙酮的 C=O 变为 CH2，产物为丙烷。","expl":{"A":"还原后不保留双键，不会生成丙烯。","B":"异丙醇是催化加氢或硼氢化钠还原的产物，不是克莱门森还原产物。","C":"正丙醇同样保留了含氧官能团，与彻底还原不符。","D":"正确，克莱门森还原把羰基变成亚甲基，丙酮还原为丙烷。","E":"该条件下反应可以顺利进行，并非不反应。"},"id":"org11_q09","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":9},{"type":"A","stem":"黄鸣龙还原法（沃尔夫-凯惜纳-黄鸣龙反应）所用的试剂是","options":{"A":"锌汞齐和浓盐酸","B":"水合肼和强碱","C":"稀碱溶液常温","D":"浓硝酸","E":"光照和氯气"},"answer":["B"],"rationale":"黄鸣龙改进法用水合肼在强碱（如二甘醇中氢氧化钾）条件下将羰基还原为亚甲基，适用于对酸敏感的物质。","expl":{"A":"锌汞齐和浓盐酸是克莱门森还原的条件，与黄鸣龙法不同。","B":"正确，水合肼在强碱中加热把羰基还原成亚甲基，即黄鸣龙还原。","C":"稀碱常温不能把羰基还原为亚甲基。","D":"浓硝酸是强氧化剂，方向与还原完全相反。","E":"光照和氯气用于自由基取代，与此还原反应无关。"},"id":"org11_q10","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":10},{"type":"A","stem":"关于对苯醌的性质，下列说法正确的是","options":{"A":"具有芳香性","B":"不能被还原","C":"是饱和环酮","D":"是无色化合物","E":"是有色化合物，可被还原为氢醌"},"answer":["E"],"rationale":"对苯醌含有共轭的α,β-不饱和二酮结构，呈黄色，可接受两个氢还原为无色的对苯二酚（氢醌）。","expl":{"A":"对苯醌不满足 4n+2 规则，环上只有 4 个 π 电子，无芳香性。","B":"对苯醌容易被还原为氢醌，是典型的还原反应。","C":"对苯醌含两个碳碳双键，不是饱和环酮。","D":"对苯醌呈黄色，不是无色化合物。","E":"正确，对苯醌有颜色，可还原成氢醌，二者构成可逆氧化还原体系。"},"id":"org11_q11","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":11},{"type":"A","stem":"区别乙醛和丙酮可用的试剂是","options":{"A":"托伦试剂","B":"2,4-二硝基苯肼","C":"溴水","D":"氢氧化钠溶液","E":"乙醇"},"answer":["A"],"rationale":"乙醛含醛基可还原托伦试剂产生银镜，丙酮为酮无此反应，故用托伦试剂即可区别二者。","expl":{"A":"正确，乙醛产生银镜，丙酮不反应，可以区别。","B":"两者都能与 2,4-二硝基苯肼生成黄色沉淀，不能区分。","C":"两者都能与溴水发生一定作用，现象不够特征。","D":"稀氢氧化钠中乙醛发生羟醛缩合，现象不明显，不宜作鉴别。","E":"乙醇与二者均不反应，无鉴别作用。"},"id":"org11_q12","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":12},{"type":"X","stem":"下列化合物能发生碘仿反应的有","options":{"A":"乙醛","B":"丙酮","C":"乙醇","D":"苯乙酮","E":"丙醛"},"answer":["A","B","C","D"],"rationale":"含 CH3CO- 结构的醛酮及可被氧化成该结构的醇均能发生碘仿反应，丙醛为 CH3CH2CO- 结构故不能。","expl":{"A":"正确，乙醛含 CH3CO- 结构，生成黄色碘仿沉淀。","B":"正确，丙酮是典型的甲基酮，碘仿反应阳性。","C":"正确，乙醇可被次碘酸钠氧化为乙醛，故也呈阳性。","D":"正确，苯乙酮含 CH3CO- 结构，能生成碘仿。","E":"错误，丙醛的α-碳上只有一个氢，不形成 CH3CO- 结构。"},"id":"org11_q13","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":13},{"type":"X","stem":"关于羟醛缩合反应，下列说法正确的有","options":{"A":"反应物必须含有α-氢","B":"产物为β-羟基醛或β-羟基酮","C":"加热失水后可生成α,β-不饱和羰基化合物","D":"常用稀碱作催化剂","E":"苯甲醛可以自身发生羟醛缩合"},"answer":["A","B","C","D"],"rationale":"羟醛缩合需要α-氢形成烯醇负离子，产物为β-羟基羰基化合物，可脱水生成共轭烯醛，故 E 错误。","expl":{"A":"正确，无α-氢则不能形成烯醇负离子，无法发生缩合。","B":"正确，缩合产物是β-羟基醛或β-羟基酮。","C":"正确，加热易脱水生成α,β-不饱和醛酮。","D":"正确，稀碱是羟醛缩合的常用催化剂。","E":"错误，苯甲醛无α-氢，不能自身缩合，只能与含α-氢的醛酮交叉缩合。"},"id":"org11_q14","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":14},{"type":"A","stem":"丙酮与甲基碘化镁反应后再水解，生成的主要产物是","options":{"A":"异丙醇","B":"正丙醇","C":"2-甲基-2-丙醇","D":"2-丁醇","E":"丙烷"},"answer":["C"],"rationale":"格氏试剂对羰基加成：甲基碘化镁的碳负性甲基进攻丙酮羰基碳，生成醇镁盐 (CH3)3C—OMgI，水解后得 2-甲基-2-丙醇（叔丁醇）。甲醛加成得伯醇，其他醛加成得仲醇，酮加成得叔醇。","expl":{"A":"异丙醇是丙酮被还原（如催化加氢、NaBH4）的产物，不是格氏加成产物。","B":"正丙醇需由丙醛与格氏试剂加成得到，丙酮加成后羰基碳上会有三个甲基。","C":"正确，羰基碳上再连一个甲基，生成含三个甲基的叔醇。","D":"2-丁醇是甲乙酮加氢或乙醛与乙基格氏试剂加成的产物。","E":"格氏试剂与酮加成不会把羰基彻底还原成亚甲基。"},"id":"org11_q15","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":15},{"type":"A","stem":"苯甲醛与过量甲醛在浓碱溶液中反应，主要产物是","options":{"A":"苯甲酸和甲醇","B":"苯甲酸钠和甲醇","C":"甲酸和苯甲醇","D":"苯甲醇和甲酸钠","E":"两者不发生反应"},"answer":["D"],"rationale":"两种无α-氢的醛在浓碱中可发生交叉康尼查罗反应：甲醛还原性最强、位阻最小，优先被氧化为甲酸并成盐；苯甲醛则被还原为苯甲醇。因此主产物是苯甲醇和甲酸钠。","expl":{"A":"甲醛才是被氧化的一方，苯甲醛被还原，故不会生成苯甲酸。","B":"氧化还原方向恰好相反，苯甲醛应变为醇。","C":"甲酸在碱性介质中以甲酸钠形式存在，且苯甲醛应被还原成醇。","D":"正确，甲醛作还原剂被氧化成甲酸钠，苯甲醛被还原成苯甲醇。","E":"无α-氢的醛在浓碱中能发生康尼查罗反应，反应可顺利进行。"},"id":"org11_q16","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":16},{"type":"A","stem":"丙酮在酸催化下与溴反应，主要产物是","options":{"A":"三溴丙酮","B":"溴仿和乙酸钠","C":"一溴丙酮（CH3COCH2Br）","D":"2,2-二溴丙烷","E":"2-溴-2-丙醇"},"answer":["C"],"rationale":"酮的α-卤代经烯醇中间体进行。酸催化时生成的一卤代物使羰基氧质子化程度降低、烯醇含量下降，反应基本停留在一卤代；碱催化时卤代酮的α-氢更活泼，可继续卤代直至生成卤仿。","expl":{"A":"三溴丙酮是碱催化过量卤素时的产物，随后还会发生卤仿反应。","B":"溴仿与乙酸钠是甲基酮在碱性溴液中卤仿反应的产物。","C":"正确，酸催化下烯醇化受到抑制，主要得到一溴代丙酮。","D":"该产物来自丙烯与溴的加成，与酮的α-卤代无关。","E":"α-卤代发生在α-碳上，不是羰基碳上再加次溴酸。"},"id":"org11_q17","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":17},{"type":"X","stem":"关于醛、酮的还原反应，下列说法正确的有","options":{"A":"硼氢化钠可把醛酮还原为相应的醇，通常不还原酯基和羧基","B":"氢化铝锂不能还原酰胺","C":"锌汞齐-浓盐酸（克莱门森还原）适用于对碱敏感、对酸稳定的底物","D":"水合肼-强碱法（沃尔夫-凯惜纳-黄鸣龙法）适用于对碱敏感的底物","E":"催化加氢可把苯甲醛还原为苯甲醇"},"answer":["A","C","E"],"rationale":"NaBH4 是温和的负氢试剂，只还原醛酮而保留酯基、羧基；LiAlH4 还原性强，能把酰胺还原成胺；克莱门森还原在强酸中进行，沃尔夫-凯惜纳法在强碱中进行，须按底物对酸、碱的敏感性选择；芳香醛经催化加氢可还原为相应醇。","expl":{"A":"正确，NaBH4 选择性高，常用于含酯基的醛酮的选择性还原。","B":"错误，LiAlH4 能把酰胺还原为相应的胺，是制备胺的常用方法。","C":"正确，该法在浓盐酸中进行，底物不能含缩醛、环氧化合物等对酸敏感的基团。","D":"错误，该法使用强碱，底物不能含对碱敏感的基团。","E":"正确，Ni、Pd 等催化加氢可把苯甲醛还原成苯甲醇。"},"id":"org11_q18","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":18}]},{"title":"第十二章 羧酸及羧酸衍生物","questions":[{"type":"A","stem":"下列羧酸中酸性最强的是","options":{"A":"甲酸","B":"乙酸","C":"丙酸","D":"三氯乙酸","E":"苯甲酸"},"answer":["D"],"rationale":"三个氯原子通过诱导效应强烈吸电子，稳定羧酸根负离子，使三氯乙酸酸性远强于乙酸等一元羧酸。","expl":{"A":"甲酸酸性强于乙酸，但仍弱于三氯乙酸。","B":"乙酸无吸电子取代基，酸性明显弱于三氯乙酸。","C":"丙酸给电子的乙基使酸性略弱于乙酸。","D":"正确，三个氯的强吸电子诱导效应使三氯乙酸酸性最强。","E":"苯甲酸的酸性弱于甲酸，更弱于三氯乙酸。"},"id":"org12_q01","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":1},{"type":"A","stem":"在羧酸的α-碳上引入吸电子基团，其酸性将","options":{"A":"减弱","B":"不变","C":"完全消失","D":"无规律变化","E":"增强"},"answer":["E"],"rationale":"α-碳上的吸电子基通过诱导效应分散羧酸根负电荷，使共轭碱更稳定，故酸性增强。","expl":{"A":"吸电子基使羧酸根更稳定，酸性应增强而非减弱。","B":"取代基通过诱导效应影响电离平衡，不会毫无变化。","C":"引入吸电子基不会使羧酸失去酸性。","D":"诱导效应随距离减弱，规律明确，并非无规律。","E":"正确，吸电子基稳定羧酸根负离子，酸性增强。"},"id":"org12_q02","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":2},{"type":"A","stem":"下列羧酸衍生物中，酰化能力最强的是","options":{"A":"乙酰氯","B":"乙酸酐","C":"乙酸乙酯","D":"乙酰胺","E":"苯甲酸乙酯"},"answer":["A"],"rationale":"酰卤中卤素的吸电子诱导效应强且离去能力好，故反应活性最高，顺序为酰卤大于酸酐大于酯大于酰胺。","expl":{"A":"正确，乙酰氯活性最高，遇水甚至剧烈水解。","B":"乙酸酐活性高于酯，但低于酰卤。","C":"乙酸乙酯的烷氧基给电子共轭，活性低于酸酐和酰卤。","D":"乙酰胺中氮的共轭最强，活性最低。","E":"苯甲酸乙酯属酯类，活性低于酰卤。"},"id":"org12_q03","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":3},{"type":"A","stem":"酯在碱性条件下的水解反应又称为","options":{"A":"酯化反应","B":"酸化反应","C":"皂化反应","D":"水合反应","E":"氨解反应"},"answer":["C"],"rationale":"酯在碱中水解生成羧酸盐和醇，因油脂的碱性水解用于制皂，故酯的碱性水解称为皂化反应。","expl":{"A":"酯化是羧酸与醇生成酯的反应，方向相反。","B":"酸化不是酯水解的专门名称，与本题不符。","C":"正确，酯的碱性水解生成羧酸盐和醇，称为皂化。","D":"水合是加水到不饱和键上，与酯水解不同。","E":"氨解是酯与氨反应生成酰胺，不是水解。"},"id":"org12_q04","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":4},{"type":"A","stem":"羧酸与醇发生酯化反应时，通常的脱水方式是","options":{"A":"羧酸脱氢，醇脱羟基","B":"两者都脱羟基","C":"羧酸脱羟基，醇脱氢","D":"两者都脱氢","E":"无法确定"},"answer":["C"],"rationale":"同位素示踪证明酯化时羧酸提供羟基、醇提供氢，脱去一分子水生成酯，即酸脱羟基醇脱氢。","expl":{"A":"该方式与示踪实验结果相反，实际是酸脱羟基。","B":"若都脱羟基则无法形成 C-O-C 键，与事实不符。","C":"正确，羧酸失去羟基、醇失去氢，共同脱水成酯。","D":"若都脱氢则不能生成水，与反应事实矛盾。","E":"同位素示踪已明确证明脱水方式，可以确定。"},"id":"org12_q05","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":5},{"type":"A","stem":"乙酸乙酯在乙醇钠作用下发生缩合，生成的主要产物是","options":{"A":"丙二酸二乙酯","B":"丙酮","C":"乙醇","D":"乙酰乙酸乙酯","E":"乙酸"},"answer":["D"],"rationale":"乙酸乙酯的α-氢被乙醇钠夺去形成烯醇负离子，进攻另一分子酯的羰基，脱去乙醇，生成乙酰乙酸乙酯。","expl":{"A":"丙二酸二乙酯由丙二酸与乙醇酯化制得，不是乙酸乙酯缩合产物。","B":"丙酮是乙酰乙酸乙酯脱羧的产物，不是缩合直接产物。","C":"乙醇是缩合反应的副产物而被蒸出，不是主要产物。","D":"正确，两分子乙酸乙酯缩合脱去一分子乙醇，生成乙酰乙酸乙酯。","E":"缩合产物是β-酮酸酯，不是乙酸。"},"id":"org12_q06","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":6},{"type":"A","stem":"乙酰胺与五氧化二磷共热，生成的主要产物是","options":{"A":"乙胺","B":"乙酸","C":"乙醇","D":"乙醛","E":"乙腈"},"answer":["E"],"rationale":"酰胺在强脱水剂五氧化二磷作用下脱去一分子水，生成腈，故乙酰胺脱水生成乙腈。","expl":{"A":"乙胺需还原酰胺才能得到，脱水剂不能起还原作用。","B":"乙酰胺水解才生成乙酸，脱水方向相反。","C":"生成醇需还原，与脱水条件不符。","D":"脱水不改变氧化态，不会生成醛。","E":"正确，酰胺脱水生成腈，乙酰胺脱一分子水得乙腈。"},"id":"org12_q07","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":7},{"type":"A","stem":"下列化合物能与碳酸氢钠溶液反应放出二氧化碳的是","options":{"A":"苯酚","B":"乙酸","C":"乙醇","D":"乙醛","E":"苯甲醚"},"answer":["B"],"rationale":"羧酸酸性强于碳酸，能与碳酸氢钠反应放出二氧化碳，苯酚酸性弱于碳酸则不能，这是二者的重要区别。","expl":{"A":"苯酚酸性弱于碳酸，不能与碳酸氢钠反应放出二氧化碳。","B":"正确，乙酸酸性强于碳酸，与碳酸氢钠反应放出二氧化碳。","C":"乙醇酸性极弱，与碳酸氢钠不反应。","D":"乙醛无酸性氢，不与碳酸氢钠反应。","E":"苯甲醚无酸性，不能与碳酸氢钠反应。"},"id":"org12_q08","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":8},{"type":"A","stem":"乙酸被氢化铝锂还原，生成的产物是","options":{"A":"乙醛","B":"乙烷","C":"乙醇","D":"乙酸乙酯","E":"丙酮"},"answer":["C"],"rationale":"氢化铝锂是强还原剂，能把羧酸还原为相应的伯醇，故乙酸被还原为乙醇，而硼氢化钠不能还原羧酸。","expl":{"A":"氢化铝锂还原羧酸不会停留在醛，而是继续还原成醇。","B":"乙烷需彻底脱氧还原，氢化铝锂只还原到醇。","C":"正确，羧酸被氢化铝锂还原成伯醇，乙酸生成乙醇。","D":"酯化需酸催化脱水，还原条件下不生成酯。","E":"羧酸还原不生成酮，丙酮需由其他途径制备。"},"id":"org12_q09","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":9},{"type":"A","stem":"丙二酸受热脱羧，生成的产物是","options":{"A":"甲酸","B":"乙醇","C":"丙酸","D":"丙酮","E":"乙酸"},"answer":["E"],"rationale":"β-二酸受热易脱去一个羧基，丙二酸（含三个碳）脱羧后减少一个碳，生成乙酸。","expl":{"A":"甲酸只有一个碳，与丙二酸脱羧产物不符。","B":"脱羧过程只是失去二氧化碳，并不涉及还原，因此不可能生成乙醇。","C":"丙酸与丙二酸碳数相同，脱羧应减少一个碳。","D":"丙酮是乙酰乙酸脱羧的产物，不是丙二酸的产物。","E":"正确，丙二酸脱羧失去二氧化碳，生成乙酸。"},"id":"org12_q10","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":10},{"type":"A","stem":"乙酸与二氯亚砜（SOCl2）反应，生成的主要产物是","options":{"A":"乙酸酐","B":"乙酰氯","C":"乙酰胺","D":"氯乙烷","E":"乙酸乙酯"},"answer":["B"],"rationale":"二氯亚砜把羧酸的羟基转化为氯，生成酰氯，副产物为气体，故乙酸与二氯亚砜反应生成乙酰氯。","expl":{"A":"乙酸酐需用脱水剂（如五氧化二磷）处理羧酸才能得到。","B":"正确，二氯亚砜将羧酸转化为酰氯，产物为乙酰氯。","C":"乙酰胺需羧酸衍生物与氨反应才能生成。","D":"氯乙烷需还原脱羧，二氯亚砜只取代羟基。","E":"乙酸乙酯需与乙醇酯化，与二氯亚砜无关。"},"id":"org12_q11","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":11},{"type":"A","stem":"与胺相比，酰胺的碱性","options":{"A":"明显更强","B":"与胺完全相同","C":"明显更弱","D":"完全没有碱性","E":"无法比较"},"answer":["C"],"rationale":"酰胺氮上的孤对电子与羰基形成 p-π 共轭，电子云密度降低，故碱性远弱于相应胺，几乎不显碱性。","expl":{"A":"共轭使氮上电子云密度降低，碱性减弱而非增强。","B":"酰胺与胺的碱性差异显著，不可能完全相同。","C":"正确，孤对电子参与共轭，酰胺碱性明显弱于胺。","D":"酰胺仍可在强酸中质子化，只是碱性很弱，不能说完没有。","E":"两者碱性强弱有明确规律，可以比较。"},"id":"org12_q12","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":12},{"type":"X","stem":"下列化合物中酸性比乙酸强的有","options":{"A":"甲酸","B":"三氯乙酸","C":"苯甲酸","D":"苯酚","E":"丙二酸"},"answer":["A","B","C","E"],"rationale":"羧酸的酸性随吸电子基团增强：甲酸（pKa 3.77）、三氯乙酸（0.65）、丙二酸（2.83）和苯甲酸（4.20）的酸性都强于乙酸（4.76），而苯酚（约 10）是弱酸，酸性远弱于乙酸，故 C 也应选入。","expl":{"A":"正确，甲酸 pKa 约 3.77，是饱和一元羧酸中酸性最强的。","B":"正确，三个氯的强吸电子诱导效应使三氯乙酸 pKa 降至约 0.65。","C":"正确，苯甲酸的 pKa 约 4.20，因苯环的吸电子诱导效应使其酸性略强于乙酸（4.76）。","D":"错误，苯酚 pKa 约 10，是弱酸性酚，远弱于乙酸。","E":"正确，丙二酸两个羧基相互吸电子，pKa 约 2.83，强于乙酸。"},"id":"org12_q13","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":13},{"type":"X","stem":"关于羧酸衍生物，下列说法正确的有","options":{"A":"都能发生水解反应","B":"都能与氨反应生成酰胺","C":"都能被氢化铝锂还原","D":"反应活性顺序为酰卤大于酸酐大于酯大于酰胺","E":"酰胺比酯更容易水解"},"answer":["A","C","D"],"rationale":"羧酸衍生物都能水解，也都能被氢化铝锂还原，反应活性顺序为酰卤>酸酐>酯>酰胺；但氨解只适用于酰卤、酸酐和酯，酰胺本身就是氨解的产物，不再与氨反应。酰胺最稳定，比酯更难水解。","expl":{"A":"正确，酰卤、酸酐、酯、酰胺都能水解，只是难易差别很大。","B":"错误，酰卤、酸酐和酯可氨解生成酰胺，但酰胺本身已是产物，不与氨反应。","C":"正确，氢化铝锂能把酰卤、酸酐、酯还原成醇，把酰胺还原成胺。","D":"正确，离去基团越稳定、共轭程度越低，活性越高，故酰卤最高、酰胺最低。","E":"错误，酰胺最稳定，水解比酯更困难，需强酸或强碱长时间加热。"},"id":"org12_q14","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":14},{"type":"A","stem":"乙酸乙酯在稀酸催化下进行水解，其断键方式是","options":{"A":"断裂烷氧键，生成乙酰基正离子","B":"断裂酰氧键，水进攻羰基碳","C":"断裂碳碳键，生成乙酸和乙烷","D":"断裂乙基的碳氢键，发生氧化","E":"不断键，只发生酯的异构化"},"answer":["B"],"rationale":"酯的酸催化水解按 AAC2 历程进行：羰基氧质子化后水进攻羰基碳形成四面体中间体，再消除醇、断酰氧键（酰基与氧之间的键）生成羧酸。18O 标记实验证明酸水解断的是酰氧键，碱性水解（皂化）同样断酰氧键。","expl":{"A":"烷氧键断裂只在羧酸叔烷基酯等能生成稳定碳正离子时发生，属 AAL1 历程。","B":"正确，水进攻羰基碳后消去醇，断裂的是酰基与氧之间的键。","C":"水解不破坏碳骨架，只断裂酯的 C—O 键。","D":"水解是加成-消除过程，不涉及乙基被氧化。","E":"酯在酸中确实水解成羧酸和醇，并非异构化。"},"id":"org12_q15","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":15},{"type":"A","stem":"乙酸乙酯与过量甲醇在少量浓硫酸催化下加热，主要产物是","options":{"A":"乙酸甲酯和乙醇","B":"甲醇和乙酸","C":"甲酸乙酯和甲醇","D":"二甲醚和乙酸","E":"两者不发生反应"},"answer":["A"],"rationale":"酯与醇在酸催化下发生酯交换（醇解），按 AAC2 历程生成新的酯和新的醇；使用过量的甲醇可使平衡右移，得到乙酸甲酯并释出乙醇，这是工业上由低级酯制备其他酯的常用方法。","expl":{"A":"正确，甲醇的甲氧基取代乙氧基，生成乙酸甲酯和乙醇。","B":"这是完全水解的产物，需大量水存在时才为主产物。","C":"酯交换只更换烷氧基，酰基部分保持不变。","D":"甲醇在酸中分子间脱水需高温，竞争不过酯交换反应。","E":"酯交换在酸或碱催化下均可进行。"},"id":"org12_q16","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":16},{"type":"A","stem":"己二酸与氢氧化钡共热并蒸出产物，生成的主要化合物是","options":{"A":"丁二酸酐","B":"戊二酸酐","C":"环己酮","D":"环戊酮","E":"己酸"},"answer":["D"],"rationale":"二元羧酸受热规律为：乙二酸、丙二酸脱羧生成一元酸；丁二酸、戊二酸分子内脱水成五元或六元环酐；己二酸、庚二酸在氢氧化钡存在下加热失羧并成环，分别生成环戊酮和环己酮。","expl":{"A":"丁二酸受热才生成丁二酸酐，己二酸碳链更长，走失羧成环的路。","B":"戊二酸受热生成戊二酸酐，不是己二酸的产物。","C":"环己酮由庚二酸（比己二酸多一个碳）失羧成环得到。","D":"正确，己二酸失羧并成环，得到五元环酮。","E":"己二酸在此条件下成环，不发生简单脱羧生成己酸。"},"id":"org12_q17","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":17},{"type":"A","stem":"乙酰氯与无水乙酸钠共热，生成的主要产物是","options":{"A":"乙酸乙酯","B":"乙酰胺","C":"乙酸","D":"乙酸酐","E":"乙烯酮"},"answer":["D"],"rationale":"酰卤与羧酸盐反应时，羧酸根作为亲核试剂进攻酰基碳，消除氯离子后生成酸酐：CH3COCl + CH3COONa → (CH3CO)2O + NaCl，这是实验室制备对称酸酐或混合酸酐的常用方法。","expl":{"A":"乙酸乙酯需酰卤与乙醇反应（醇解），而不是与羧酸盐反应。","B":"乙酰胺是酰卤与氨或胺发生氨解的产物。","C":"乙酸只是该反应中水解产生的副产物，主产物是酸酐。","D":"正确，羧酸根取代氯离子，生成乙酸酐。","E":"乙烯酮需乙酸高温脱水或酰卤在碱中消除 HCl 制得，非本题条件。"},"id":"org12_q18","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":18},{"type":"X","stem":"关于羧酸与醇的酯化反应，下列说法正确的有","options":{"A":"用 18O 标记的甲醇与乙酸酯化，18O 保留在生成的酯中","B":"反应可逆，常通过移除生成的水或使用过量醇提高产率","C":"羧酸α-碳上取代基空间位阻增大，酯化速率下降","D":"叔醇在酸催化酯化条件下易脱水成烯，酯的产率降低","E":"酯化平衡常数很小，即使加入过量醇也不能提高酯的产率"},"answer":["A","B","C","D"],"rationale":"酯化是酸催化的可逆反应，按 AAC2 历程羧酸断酰氧键、醇断 O—H 键，故醇的氧随烷基进入酯中；位阻增大会妨碍四面体中间体形成，叔醇在酸性条件下更易消除成烯。因此除水或加大醇的比例都可使平衡右移提高产率。","expl":{"A":"正确，醇的氧随烷基进入酯中，18O 标记留在烷氧基上。","B":"正确，酯化是可逆平衡，除水或过量醇都使平衡右移。","C":"正确，位阻增大不利于四面体中间体形成，速率与产率均下降。","D":"正确，叔醇在酸性条件下更易消除成烯，酯化产率明显偏低。","E":"错误，增大醇的比例可使平衡右移，从而提高酯的产率。"},"id":"org12_q19","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":19}]},{"title":"第十三章 取代羧酸","questions":[{"type":"A","stem":"α-羟基酸受热发生分子间脱水，生成的主要产物是","options":{"A":"酮","B":"内酯","C":"不饱和酸","D":"醛","E":"交酯"},"answer":["E"],"rationale":"α-羟基酸分子间羟基与羧基相互酯化，形成六元环状的交酯，故受热主要生成交酯。","expl":{"A":"α-羟基酸受热不生成酮，酮需氧化或脱羧等条件。","B":"内酯由γ-或δ-羟基酸分子内脱水形成，α-羟基酸分子内成环张力大。","C":"脱水成酯而非脱水成烯，故不生成不饱和酸。","D":"受热脱水不改变官能团类型，不生成醛。","E":"正确，两分子α-羟基酸相互酯化生成稳定的六元环交酯。"},"id":"org13_q01","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":1},{"type":"A","stem":"γ-羟基丁酸受热后生成的主要产物是","options":{"A":"交酯","B":"γ-丁内酯","C":"丁烯酸","D":"丁二酸","E":"不反应"},"answer":["B"],"rationale":"γ-羟基酸分子内羟基与羧基距离合适，受热发生分子内酯化，形成稳定的五元环内酯。","expl":{"A":"交酯是α-羟基酸分子间脱水产物，γ-羟基酸以分子内成环为主。","B":"正确，γ-羟基丁酸分子内脱水生成五元环的γ-丁内酯。","C":"受热成酯而非脱水成烯，故不生成丁烯酸。","D":"丁二酸需氧化端位羟基才能得到，与受热脱水无关。","E":"γ-羟基酸受热易成内酯，并非不反应。"},"id":"org13_q02","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":2},{"type":"A","stem":"乙酰乙酸受热到 150 摄氏度以上，生成的产物是","options":{"A":"乙酸","B":"乙醇","C":"丙酮和二氧化碳","D":"丙酸","E":"乙醛"},"answer":["C"],"rationale":"β-酮酸受热易脱羧，乙酰乙酸失去二氧化碳后生成丙酮，这是β-酮酸的重要特性。","expl":{"A":"β-酮酸脱羧时失去的是羧基而不再生成羧酸，故产物为丙酮而不是乙酸。","B":"脱羧不涉及还原，不会生成乙醇。","C":"正确，β-酮酸受热脱羧，乙酰乙酸生成丙酮和二氧化碳。","D":"丙酸与乙酰乙酸碳数相同，脱羧应减少一个碳。","E":"脱羧后保留羰基生成酮而不是醛，醛需经还原等其他条件才能得到。"},"id":"org13_q03","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":3},{"type":"A","stem":"乙酰乙酸乙酯的烯醇式结构是","options":{"A":"CH3COCH2COOC2H5","B":"CH3CH2COCOOC2H5","C":"CH3COCH=C(OH)OC2H5","D":"CH3C(OH)=CHCOOC2H5","E":"环状半缩醛结构"},"answer":["D"],"rationale":"亚甲基上的氢转移到羰基氧上，形成碳碳双键和烯醇羟基，故烯醇式为 CH3C(OH)=CHCOOC2H5。","expl":{"A":"这是酮式结构，亚甲基未被烯醇化。","B":"该结构碳骨架已改变，不是乙酰乙酸乙酯的互变异构体。","C":"羟基连在乙氧基碳上不符合烯醇化的规律。","D":"正确，羰基氧接受α-氢形成羟基，同时在α,β位形成双键。","E":"乙酰乙酸乙酯不发生成环，烯醇式为开链结构。"},"id":"org13_q04","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":4},{"type":"A","stem":"乙酰乙酸乙酯与三氯化铁溶液作用，呈现的颜色是","options":{"A":"蓝色","B":"绿色","C":"黄色","D":"不显色","E":"紫红色"},"answer":["E"],"rationale":"乙酰乙酸乙酯存在烯醇式，烯醇羟基能与铁离子形成有色配合物，故显紫红色。","expl":{"A":"蓝色不是烯醇式与铁离子配合物的特征颜色。","B":"绿色不是烯醇式与铁离子形成的配合物的颜色，该显色反应应呈紫红色。","C":"黄色不是其烯醇铁配合物的颜色。","D":"乙酰乙酸乙酯含烯醇式，能与铁离子显色，不会不显色。","E":"正确，烯醇式与三氯化铁生成紫红色配合物，是鉴别依据。"},"id":"org13_q05","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":5},{"type":"A","stem":"乙酰乙酸乙酯在稀碱中水解后酸化并加热，生成的主要产物是","options":{"A":"乙酸","B":"乙醇","C":"丙酮","D":"丙酸","E":"乙酰乙酸"},"answer":["C"],"rationale":"稀碱水解后酸化得到乙酰乙酸，β-酮酸受热脱羧生成丙酮，此即酮式分解，用于合成取代丙酮。","expl":{"A":"酮式分解的产物是酮，不会生成乙酸。","B":"乙醇是酯水解时释放的醇，不是最终主要有机产物。","C":"正确，酸化后生成β-酮酸，受热脱羧得丙酮，即酮式分解。","D":"丙酸需还原或彻底分解才能得到，与酮式分解不符。","E":"乙酰乙酸是中间体，加热后立即脱羧，不能作为最终产物。"},"id":"org13_q06","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":6},{"type":"A","stem":"丙二酸二乙酯的钠盐与溴乙烷反应，再经碱性水解、酸化并加热，最终产物是","options":{"A":"丙酸","B":"丁酸","C":"戊酸","D":"乙酸","E":"2-甲基丙酸"},"answer":["B"],"rationale":"溴乙烷在丙二酸二乙酯的α-碳上引入乙基，水解酸化得乙基丙二酸，加热脱羧失去一个羧基，生成丁酸。","expl":{"A":"丙酸是未引入乙基时的产物，与题意不符。","B":"正确，引入一个乙基后脱羧，得到比乙酸多两个碳的丁酸。","C":"戊酸需引入丙基才能得到，溴乙烷只引入乙基。","D":"乙酸是丙二酸二乙酯直接水解脱羧的产物。","E":"2-甲基丙酸需用异丙基卤代烃才能得到，与溴乙烷不符。"},"id":"org13_q07","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":7},{"type":"A","stem":"乙酰乙酸乙酯的钠盐与卤代烃反应后，再经酮式分解，生成的产物是","options":{"A":"一取代丙酮","B":"一取代乙酸","C":"醇","D":"醛","E":"酯"},"answer":["A"],"rationale":"卤代烃在α-碳上引入烃基，酮式分解脱羧后保留羰基，生成含该取代基的丙酮衍生物，即一取代丙酮。","expl":{"A":"正确，酮式分解保留羰基，产物为取代丙酮。","B":"一取代乙酸需经酸式分解才能得到，与酮式分解不同。","C":"酮式分解不生成醇，产物仍是酮。","D":"酮式分解保留羰基，最终产物是酮而不是醛，二者官能团并不相同。","E":"水解后已不是酯，酮式分解得到酮。"},"id":"org13_q08","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":8},{"type":"A","stem":"α-氨基酸与亚硝酸反应，生成的产物是","options":{"A":"伯胺","B":"醛","C":"酮","D":"不饱和酸","E":"α-羟基酸并放出氮气"},"answer":["E"],"rationale":"α-氨基酸的氨基被亚硝酸取代为羟基，同时放出一分子氮气，该反应可定量测定氨基，即范斯莱克法。","expl":{"A":"反应是氨基被羟基取代，不会生成伯胺。","B":"生成的是α-羟基酸，不是醛，醛需经氧化脱氨。","C":"α-氨基酸与亚硝酸是氧化脱氨并取代为羟基，不会生成酮类化合物。","D":"氨基被羟基取代并不会形成新的碳碳双键，因此不会生成不饱和酸。","E":"正确，氨基被羟基取代并定量放出氮气，生成α-羟基酸。"},"id":"org13_q09","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":9},{"type":"A","stem":"丙酮酸受热或经酶催化脱羧，生成的产物是","options":{"A":"乙醇","B":"乙醛","C":"乙酸","D":"丙酮","E":"甲醛"},"answer":["B"],"rationale":"丙酮酸是α-酮酸，脱羧后羰基保留在与羧基相邻的碳上，生成乙醛，这是糖代谢中的重要反应。","expl":{"A":"脱羧不涉及还原，不会生成乙醇。","B":"正确，丙酮酸脱去二氧化碳后生成乙醛。","C":"乙酸需氧化才能得到，单纯脱羧生成醛。","D":"丙酮酸脱羧不生成丙酮，丙酮需专门还原。","E":"甲醛只有一个碳，与丙酮酸的碳数不符。"},"id":"org13_q10","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":10},{"type":"X","stem":"关于乙酰乙酸乙酯，下列说法正确的有","options":{"A":"存在酮式与烯醇式的互变异构","B":"其烯醇式能与三氯化铁溶液显色","C":"其烯醇式能使溴水褪色","D":"能与金属钠反应放出氢气","E":"烯醇式的含量高于酮式"},"answer":["A","B","C","D"],"rationale":"乙酰乙酸乙酯以酮式为主，烯醇式含量很少但能显色、使溴水褪色，活泼氢可与钠反应，故 E 错误。","expl":{"A":"正确，酮式与烯醇式通过质子转移相互转变，处于动态平衡。","B":"正确，烯醇羟基与铁离子形成紫红色配合物。","C":"正确，烯醇式的碳碳双键可与溴发生加成而褪色。","D":"正确，活泼亚甲基氢和烯醇氢可与金属钠反应放出氢气。","E":"错误，常温下酮式约占绝大多数，烯醇式含量很少。"},"id":"org13_q11","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":11},{"type":"X","stem":"利用丙二酸二乙酯合成法可以制备","options":{"A":"一元羧酸","B":"二元羧酸","C":"取代乙酸","D":"酮","E":"醇"},"answer":["A","B","C"],"rationale":"丙二酸二乙酯的亚甲基可引入一个或两个烃基，脱羧后分别得到取代乙酸或二元羧酸，但不能用来合成酮和醇。","expl":{"A":"正确，引入一个烃基后脱羧可得一元羧酸。","B":"正确，与二卤代烷反应成环后脱羧可得二元羧酸。","C":"正确，引入一个取代基后脱羧即得取代乙酸。","D":"错误，合成酮需使用乙酰乙酸乙酯法，丙二酸酯法脱羧后为羧酸。","E":"错误，该法产物为羧酸，不能直接得到醇。"},"id":"org13_q12","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":12},{"type":"A","stem":"乳酸（α-羟基丙酸）与稀硫酸共热发生分解，生成的主要产物是","options":{"A":"乙醛和甲酸","B":"乙醇和甲酸","C":"乙酸和甲醛","D":"丙酮和甲酸","E":"丙烯酸和水"},"answer":["A"],"rationale":"α-羟基酸与稀硫酸共热时，α-碳上的羟基被氧化、碳链在α-碳与羧基之间断裂，羧基部分以甲酸形式释出，其余部分生成相应的醛或酮。乳酸因此分解为乙醛和甲酸，该反应常用于α-羟基酸的结构推断。","expl":{"A":"正确，α-羟基酸分解得醛（或酮）与甲酸，乳酸给出乙醛和甲酸。","B":"分解产物是醛而不是醇，过程中伴随氧化还原。","C":"羧基部分以甲酸形式保留，不会生成甲醛。","D":"生成酮需α-碳上没有氢（如α-羟基异丁酸），乳酸的α-碳有氢，故得乙醛。","E":"分子内脱水成不饱和酸是β-羟基酸受热时的行为。"},"id":"org13_q13","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":13},{"type":"A","stem":"β-羟基丁酸受热发生分子内脱水，生成的主要产物是","options":{"A":"交酯","B":"γ-丁内酯","C":"2-丁烯酸","D":"丁二酸","E":"丁醛"},"answer":["C"],"rationale":"羟基酸受热脱水的方式取决于羟基位置：α-羟基酸分子间脱水成交酯；β-羟基酸分子内脱去β-羟基与α-氢生成α,β-不饱和酸；γ-、δ-羟基酸分子内酯化生成五元或六元内酯。β-羟基丁酸因此脱水生成 2-丁烯酸。","expl":{"A":"交酯是α-羟基酸分子间脱水的产物。","B":"γ-丁内酯由γ-羟基丁酸分子内酯化生成。","C":"正确，β-羟基与α-氢脱去一分子水，形成α,β-不饱和酸。","D":"丁二酸是二元羧酸，与羟基酸脱水无关。","E":"脱水生成不饱和酸，而不是断裂碳链生成醛。"},"id":"org13_q14","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":14},{"type":"A","stem":"水杨酸（邻羟基苯甲酸）与碱石灰共热，生成的主要产物是","options":{"A":"苯","B":"苯甲酸","C":"邻甲酚","D":"苯酚","E":"环己醇"},"answer":["D"],"rationale":"酚酸中羧基与酚羟基处于邻位或对位时受热易脱羧。水杨酸与碱石灰共热失去二氧化碳生成苯酚，这是由水杨酸制备苯酚的经典反应，也说明酚酸比一般芳香羧酸更容易脱羧。","expl":{"A":"脱羧后保留了酚羟基，产物是苯酚而不是苯。","B":"反应是失去整个羧基（脱羧），不是氧化或还原。","C":"脱羧只去掉 CO2，不会在环上引入甲基。","D":"正确，邻羟基苯甲酸脱羧生成苯酚。","E":"苯环保持不变，无需加氢还原成环己醇。"},"id":"org13_q15","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":15},{"type":"A","stem":"丙二酸二乙酯的钠盐与溴代环己烷反应，再经碱性水解、酸化并加热，最终产物是","options":{"A":"环己烷","B":"环己醇","C":"环己甲酸","D":"苯乙酸","E":"环己基乙酸"},"answer":["E"],"rationale":"丙二酸二乙酯合成法先在亚甲基上引入烃基，再水解成取代丙二酸，加热脱羧失去一个羧基而得到取代乙酸。引入环己基后，最终产物为环己基乙酸（C6H11CH2COOH）。","expl":{"A":"烃基被引入到丙二酸的亚甲基上，不会生成环己烷。","B":"溴代环己烷在此作烷基化试剂，不发生水解生成醇。","C":"环己甲酸的羧基直接连在环上，需由格氏试剂与 CO2 制备。","D":"原料中没有苯环，环己基也不会芳构化。","E":"正确，环己基连在乙酸的α-碳上，得到环己基乙酸。"},"id":"org13_q16","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":16}]},{"title":"第十四章 含氮有机化合物","questions":[{"type":"A","stem":"(CH3)3N 的正确名称是","options":{"A":"三甲胺","B":"叔丁胺","C":"甲胺","D":"二甲胺","E":"甲乙胺"},"answer":["A"],"rationale":"氮原子上连有三个甲基，按取代基数目命名为三甲胺，注意叔胺与叔丁胺是两个不同概念。","expl":{"A":"正确，氮上连三个甲基，称为三甲胺，属叔胺。","B":"叔丁胺是 (CH3)3C-NH2，氮上只有一个叔丁基。","C":"甲胺是 CH3NH2，氮上只连一个甲基。","D":"二甲胺是 (CH3)2NH，氮上只连两个甲基。","E":"甲乙胺的氮上应同时连甲基和乙基，本题只有甲基。"},"id":"org14_q01","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":1},{"type":"A","stem":"在水溶液中，下列胺的碱性最强的是","options":{"A":"甲胺","B":"二甲胺","C":"三甲胺","D":"苯胺","E":"氨"},"answer":["B"],"rationale":"在水溶液中碱性强弱受电子效应与溶剂化共同影响，二甲胺的碱性最强，顺序为二甲胺大于甲胺大于三甲胺大于氨大于苯胺。","expl":{"A":"甲胺碱性弱于二甲胺，因后者有两个甲基的给电子作用。","B":"正确，综合电子效应与溶剂化作用，二甲胺在水溶液中碱性最强。","C":"三甲胺只有一个可溶剂化的氢，溶剂化差，碱性弱于二甲胺。","D":"苯胺氮上孤对与苯环共轭，碱性远弱于脂肪胺。","E":"氨无烷基给电子，碱性弱于脂肪胺。"},"id":"org14_q02","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":2},{"type":"A","stem":"苯胺的碱性明显弱于氨，其主要原因是","options":{"A":"苯环的空间位阻大","B":"苯胺在水中的溶解度小","C":"苯胺相对分子质量大","D":"苯环的吸电子诱导效应是唯一原因","E":"氮上孤对电子与苯环共轭，使氮上电子云密度降低"},"answer":["E"],"rationale":"苯胺氮上的孤对电子与苯环大 π 键形成 p-π 共轭，电子云向环上分散，与质子结合能力下降，故碱性弱。","expl":{"A":"空间位阻不是苯胺碱性减弱的主要原因。","B":"溶解度影响浓度，不决定碱性强弱。","C":"相对分子质量与碱性没有直接关系。","D":"诱导效应存在，但共轭效应才是主要因素，不能说是唯一原因。","E":"正确，孤对电子参与共轭而离域，是碱性减弱的主要原因。"},"id":"org14_q03","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":3},{"type":"A","stem":"苯胺与乙酸酐反应，生成的主要产物是","options":{"A":"乙酰苯胺","B":"苯甲酰胺","C":"苯乙酸","D":"苯乙酮","E":"N-甲基苯胺"},"answer":["A"],"rationale":"苯胺的氨基与乙酸酐发生酰化反应，氮上引入乙酰基，生成乙酰苯胺，该反应常用于保护氨基。","expl":{"A":"正确，氨基被乙酰化生成乙酰苯胺，是常用的保护氨基方法。","B":"苯甲酰胺需苯甲酸衍生物与氨反应生成，碳架不同。","C":"苯乙酸是羧酸，不是胺的酰化产物。","D":"苯乙酮是酮，需苯与乙酰氯在催化剂下反应才能生成。","E":"酰化的是氮上的氢而不是生成N-甲基，故不是N-甲基苯胺。"},"id":"org14_q04","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":4},{"type":"A","stem":"伯胺与苯磺酰氯反应生成的产物，其性质是","options":{"A":"不溶于碱溶液","B":"不反应","C":"溶于碱溶液，可据此鉴别伯胺","D":"生成偶氮化合物","E":"生成重氮盐"},"answer":["C"],"rationale":"伯胺与苯磺酰氯生成的磺酰胺氮上仍有氢，具弱酸性可溶于碱；仲胺产物不溶，叔胺不反应，故可用于鉴别。","expl":{"A":"不溶于碱是仲胺生成物的特征，不是伯胺产物。","B":"伯胺与苯磺酰氯能顺利反应生成磺酰胺。","C":"正确，伯胺生成的磺酰胺可溶于碱，是兴斯堡鉴别的依据。","D":"该反应生成磺酰胺，不生成偶氮化合物。","E":"生成重氮盐需用亚硝酸，与苯磺酰氯无关。"},"id":"org14_q05","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":5},{"type":"A","stem":"苯胺在低温下与亚硝酸作用，生成的主要产物是","options":{"A":"重氮盐","B":"苯酚","C":"硝基苯","D":"苯肼","E":"偶氮苯"},"answer":["A"],"rationale":"芳香伯胺在 0 至 5 摄氏度与亚硝酸作用生成重氮盐，重氮盐是重要的合成中间体，可用于多种取代反应。","expl":{"A":"正确，低温下芳香伯胺与亚硝酸生成重氮盐。","B":"苯酚需将重氮盐水解才能得到，不是此步产物。","C":"硝基苯由苯直接硝化制得，与亚硝酸无关。","D":"苯肼需经重氮盐还原才能得到，不是直接产物。","E":"偶氮苯需重氮盐与芳烃偶合等条件，此步不生成。"},"id":"org14_q06","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":6},{"type":"A","stem":"重氮盐与酚发生偶合反应，通常所需的介质是","options":{"A":"强酸性","B":"强碱性","C":"中性","D":"弱碱性","E":"无任何要求"},"answer":["D"],"rationale":"弱碱性介质中酚转变为酚氧负离子，活泼性大大增强，有利于重氮离子进攻，故酚的偶合在弱碱性条件下进行。","expl":{"A":"强酸中酚不解离，且重氮离子易转化为其他物种，不利于偶合。","B":"强碱会使重氮盐转变为重氮酸盐而失去偶合能力。","C":"中性介质偶合速率较低，不是最佳条件。","D":"正确，弱碱性中生成活泼的酚氧负离子，偶合顺利。","E":"偶合反应对介质酸碱性很敏感，并非无要求。"},"id":"org14_q07","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":7},{"type":"A","stem":"苯重氮盐在氰化亚铜存在下与氰化钾反应，生成的主要产物是","options":{"A":"氯苯","B":"苯酚","C":"苯胺","D":"硝基苯","E":"苯甲腈"},"answer":["E"],"rationale":"这是桑德迈尔反应，重氮基被氰基取代，生成苯甲腈，是引入氰基、增长碳链的常用方法。","expl":{"A":"氯苯需重氮盐与氯化亚铜反应才能得到。","B":"苯酚需将重氮盐水解，与氰化物无关。","C":"苯胺是重氮盐的还原产物，不是取代产物。","D":"硝基苯不能由重氮盐与氰化物反应生成。","E":"正确，重氮基被氰基取代生成苯甲腈，即桑德迈尔反应。"},"id":"org14_q08","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":8},{"type":"A","stem":"季铵碱受热发生霍夫曼消除，生成的烯烃是","options":{"A":"双键碳上取代基最多的烯烃","B":"双键碳上取代基最少的烯烃","C":"不生成烯烃","D":"环状化合物","E":"无法预测"},"answer":["B"],"rationale":"霍夫曼消除中碱进攻位阻较小的β-氢，主要生成双键碳上取代基最少的烯烃，与扎依采夫规则相反。","expl":{"A":"取代最多的烯烃是扎依采夫产物，霍夫曼消除正相反。","B":"正确，霍夫曼消除优先夺取空间位阻小的β-氢，生成取代最少的烯烃。","C":"季铵碱加热可顺利发生消除生成烯烃。","D":"消除产物是不饱和开链烃，不是环状化合物。","E":"该反应有明确取向规律，可以预测主产物。"},"id":"org14_q09","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":9},{"type":"A","stem":"鉴别伯胺、仲胺和叔胺最常用的反应是","options":{"A":"兴斯堡反应","B":"托伦反应","C":"溴水反应","D":"三氯化铁显色反应","E":"碘仿反应"},"answer":["A"],"rationale":"三类胺与苯磺酰氯反应表现不同：伯胺产物溶于碱，仲胺产物不溶，叔胺不反应，故可用于鉴别。","expl":{"A":"正确，兴斯堡反应依据磺酰胺的溶解性和反应现象区分三类胺。","B":"托伦反应用于鉴别醛，与胺的分类无关。","C":"溴水用于检验酚和不饱和烃，不能区分胺的类型。","D":"三氯化铁显色用于检验酚羟基或烯醇，不适用于胺。","E":"碘仿反应用于甲基酮等结构，不能鉴别胺。"},"id":"org14_q10","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":10},{"type":"X","stem":"关于胺的碱性，下列说法正确的有","options":{"A":"脂肪胺的碱性一般强于氨","B":"苯胺的碱性弱于氨","C":"苯胺对位引入硝基后碱性增强","D":"二苯胺的碱性强于苯胺","E":"三甲胺在水中的碱性弱于二甲胺"},"answer":["A","B","E"],"rationale":"烷基给电子使脂肪胺碱性大于氨，苯环共轭使苯胺碱性小于氨，硝基吸电子减弱碱性，二苯胺碱性更弱。","expl":{"A":"正确，烷基的给电子效应使氮上电子云密度升高，碱性增强。","B":"正确，氮上孤对与苯环共轭，苯胺碱性明显弱于氨。","C":"错误，硝基吸电子使氮上电子云密度进一步降低，碱性减弱。","D":"错误，两个苯环共轭使二苯胺碱性比苯胺更弱。","E":"正确，三甲胺溶剂化差，在水中碱性弱于二甲胺。"},"id":"org14_q11","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":11},{"type":"X","stem":"关于芳香重氮盐的性质，下列说法正确的有","options":{"A":"可被次磷酸还原为苯","B":"加热水解可生成苯酚","C":"能与萘酚发生偶合反应生成偶氮染料","D":"干燥后可长期稳定保存","E":"与氯化亚铜反应可生成氯苯"},"answer":["A","B","C","E"],"rationale":"重氮盐可被还原脱氨、水解成酚、与酚或萘酚偶合、经桑德迈尔反应引入卤素，但干燥时易爆炸，故 D 错误。","expl":{"A":"正确，次磷酸可把重氮基还原为氢，即去氨基反应。","B":"正确，重氮盐水溶液加热水解生成酚。","C":"正确，与萘酚偶合生成有色的偶氮化合物，用于染料合成。","D":"错误，干燥的重氮盐极不稳定，受热或撞击易分解甚至爆炸。","E":"正确，与氯化亚铜反应使重氮基被氯取代，生成氯苯。"},"id":"org14_q12","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":12},{"type":"A","stem":"乙酰胺与溴的氢氧化钠溶液共热，生成的主要产物是","options":{"A":"乙胺","B":"乙酸","C":"甲胺","D":"乙醇","E":"乙腈"},"answer":["C"],"rationale":"霍夫曼降解中，酰胺在碱性溴液中先生成 N-溴代酰胺，再经重排脱去羰基，所得胺比原酰胺少一个碳原子。乙酰胺含两个碳，故降解后生成甲胺（一个碳）。","expl":{"A":"乙胺保留了原有两个碳，霍夫曼降解会脱去羰基碳，使碳数减少。","B":"碱性条件下酰胺水解才生成乙酸钠，本题是溴-碱的降解条件。","C":"正确，脱去羰基后生成比原料少一个碳的伯胺。","D":"降解产物是胺，不是醇。","E":"乙腈是酰胺脱水（如与 P2O5 共热）的产物。"},"id":"org14_q13","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":13},{"type":"A","stem":"芳香伯胺与氯仿、氢氧化钾醇溶液共热，产生难闻气味，该反应生成的化合物类型是","options":{"A":"腈","B":"偶氮化合物","C":"重氮盐","D":"异腈","E":"酰胺"},"answer":["D"],"rationale":"芳香伯胺在碱性醇液中与氯仿反应生成异腈（胩），具有强烈的恶臭，是鉴别芳香伯胺的经典试验（异腈试验）；脂肪伯胺也可发生此反应，仲胺、叔胺则不能。","expl":{"A":"腈由酰胺脱水或卤代烃与氰化钠反应得到，不是本反应产物。","B":"偶氮化合物由重氮盐与酚或芳胺偶合生成。","C":"重氮盐由芳香伯胺在低温与亚硝酸作用生成。","D":"正确，产物为异腈，具有特殊恶臭，可作鉴别依据。","E":"酰胺是羧酸衍生物，不是胺与氯仿反应的产物。"},"id":"org14_q14","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":14},{"type":"A","stem":"用邻苯二甲酰亚胺钾与溴代烷反应，再经水解（或肼解），可以制备","options":{"A":"仲胺","B":"叔胺","C":"季铵盐","D":"酰胺","E":"纯净的伯胺"},"answer":["E"],"rationale":"邻苯二甲酰亚胺钾中氮原子的亲核性被两个羰基活化，与卤代烷发生 SN2 生成 N-烷基衍生物，再水解或肼解放出伯胺。该法避免了伯胺继续被烷基化，因此能得到纯净的伯胺（Gabriel 合成法）。","expl":{"A":"仲胺需伯胺再与卤代烷反应，Gabriel 法的设计正是为了避免这一步。","B":"叔胺需多次烷基化，Gabriel 法只引入一个烷基。","C":"季铵盐由叔胺与卤代烷再反应生成，不是该法的产物。","D":"酰胺是羧酸衍生物，而本题制备的是胺。","E":"正确，Gabriel 合成是制备纯伯胺的经典方法。"},"id":"org14_q15","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":15},{"type":"X","stem":"关于硝基苯的还原，下列说法正确的有","options":{"A":"在酸性介质中用铁粉-盐酸还原，最终主要得到苯胺","B":"在中性或弱酸性介质中用锌粉-氯化铵还原，可得到苯羟胺","C":"在强碱性介质中用锌粉还原，可得到偶氮苯或氢化偶氮苯","D":"催化加氢可使苯环一并被还原，得到环己胺","E":"无论介质如何，硝基苯还原的最终产物都是苯胺"},"answer":["A","B","C","D"],"rationale":"硝基苯的还原深度由介质和还原剂的强弱控制：酸性条件下可一直还原到氨基（苯胺）；中性或弱酸性条件下停留在苯羟胺；强碱性锌粉条件下生成的中间体相互偶联，得偶氮苯或氢化偶氮苯；催化加氢时芳环也可被饱和成环己胺。","expl":{"A":"正确，酸性介质中还原可进行到底，生成苯胺。","B":"正确，弱还原条件下硝基被还原为羟氨基而不再继续。","C":"正确，碱性锌粉条件下中间体偶联成偶氮化合物。","D":"正确，镍或铂催化加氢可使芳环饱和，得到环己胺。","E":"错误，还原产物与介质及还原剂强弱密切相关。"},"id":"org14_q16","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":16}]},{"title":"第十五章 氨基酸、多肽、蛋白质","questions":[{"type":"A","stem":"氨基酸处于等电点时，其在水中的溶解度","options":{"A":"最小","B":"最大","C":"与 pH 无关","D":"等于零","E":"随温度无限增大"},"answer":["A"],"rationale":"等电点时氨基酸以两性离子形式存在，净电荷为零，分子间静电排斥最小，最易聚集析出，故溶解度最小。","expl":{"A":"正确，等电点时净电荷为零，溶解度降至最低，可用于分离纯化。","B":"溶解度最大出现在远离等电点的强酸或强碱条件下。","C":"溶解度随 pH 变化明显，不可能与 pH 无关。","D":"溶解度只是最小，并非完全不溶。","E":"温度升高溶解度变化有限，不会无限增大。"},"id":"org15_q01","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":1},{"type":"A","stem":"α-氨基酸与茚三酮反应，生成的产物颜色是","options":{"A":"红色","B":"黄色","C":"无色","D":"蓝紫色","E":"白色沉淀"},"answer":["D"],"rationale":"α-氨基酸与茚三酮共热发生氧化脱氨并生成蓝紫色化合物，该反应灵敏度高，常用于氨基酸的纸色谱显色。","expl":{"A":"红色不是茚三酮与α-氨基酸反应的特征颜色。","B":"黄色通常不是该反应的产物颜色。","C":"反应生成明显的蓝紫色产物，不是无色。","D":"正确，生成蓝紫色化合物，是氨基酸的常用鉴别反应。","E":"该反应生成有色溶液，不是白色沉淀。"},"id":"org15_q02","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":2},{"type":"X","stem":"关于α-氨基酸，下列说法正确的有","options":{"A":"具有两性，既能与酸又能与碱成盐","B":"在等电点时主要以两性离子形式存在","C":"与亚硝酸反应放出氮气","D":"可发生缩合反应形成肽键","E":"茚三酮反应只对芳香族氨基酸显色"},"answer":["A","B","C","D"],"rationale":"α-氨基酸含氨基和羧基，具两性，等电点以两性离子存在，与亚硝酸放氮并可成肽，茚三酮对多数α-氨基酸均显色。","expl":{"A":"正确，氨基显碱性、羧基显酸性，故氨基酸具有两性。","B":"正确，等电点时羧基去质子、氨基得质子，形成两性离子。","C":"正确，氨基被亚硝酸取代为羟基并定量放出氮气。","D":"正确，一个氨基酸的羧基与另一个的氨基缩合成肽键。","E":"错误，茚三酮对大多数α-氨基酸都显蓝紫色，并非只对芳香族。"},"id":"org15_q03","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":3},{"type":"X","stem":"关于蛋白质的变性，下列说法正确的有","options":{"A":"变性后失去原有的生物活性","B":"变性主要是空间构象被破坏","C":"变性后溶解度降低，容易沉淀","D":"高温、强酸强碱和重金属盐都可引起变性","E":"变性时肽键断裂，一级结构被破坏"},"answer":["A","B","C","D"],"rationale":"变性是二级、三级等空间构象被破坏而一级结构不变的过程，故肽键不断裂，E 错误，其余各项正确。","expl":{"A":"正确，空间构象破坏导致活性中心丧失，生物活性下降或消失。","B":"正确，变性主要破坏氢键、疏水作用等维持的空间构象。","C":"正确，构象改变使疏水基团外露，溶解度降低而沉淀。","D":"正确，高温、强酸碱、重金属盐、有机溶剂均可致变性。","E":"错误，变性不破坏肽键，一级结构保持不变。"},"id":"org15_q04","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":4},{"type":"A","stem":"谷氨酸的等电点约为 3.2，将其溶于 pH 7 的缓冲液中，此时谷氨酸主要以何种形式存在","options":{"A":"带正电荷的阳离子","B":"净电荷为零的两性离子","C":"带负电荷的阴离子","D":"不带电荷的中性分子","E":"分解为氨和有机酸"},"answer":["C"],"rationale":"溶液的 pH 高于等电点时，羧基去质子化程度增大，氨基酸以带负电荷的阴离子为主；pH 低于等电点时则以阳离子为主；只有 pH 等于等电点时才以净电荷为零的两性离子为主。pH 7 远高于谷氨酸的等电点 3.2，故带负电。","expl":{"A":"阳离子是 pH 低于等电点时的主要存在形式。","B":"净电荷为零的两性离子只在 pH 等于等电点时占绝对优势。","C":"正确，pH 大于 pI 时羧基电离占优，分子带负电。","D":"氨基酸在水溶液中以离子形式存在，不以中性分子为主。","E":"氨基酸在水溶液中稳定，不会分解。"},"id":"org15_q05","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":5},{"type":"A","stem":"下列α-氨基酸中，等电点最高的是","options":{"A":"甘氨酸","B":"谷氨酸","C":"天冬氨酸","D":"赖氨酸","E":"丝氨酸"},"answer":["D"],"rationale":"等电点由侧链基团的酸碱性决定：含两个羧基的酸性氨基酸等电点低（谷氨酸约 3.22、天冬氨酸约 2.77）；侧链带氨基的赖氨酸是碱性氨基酸，等电点约 9.74，为常见氨基酸中最高；甘氨酸、丝氨酸等中性氨基酸居中。","expl":{"A":"甘氨酸侧链为氢，等电点约 5.97，属中性范围。","B":"谷氨酸是酸性氨基酸，等电点约 3.22，偏低。","C":"天冬氨酸也是酸性氨基酸，等电点约 2.77。","D":"正确，赖氨酸侧链含氨基，是碱性氨基酸，等电点最高。","E":"丝氨酸侧链含羟基，等电点约 5.68，接近中性。"},"id":"org15_q06","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":6},{"type":"A","stem":"多肽链中肽键（—CO—NH—）的结构特点是","options":{"A":"可以自由旋转的单键","B":"具有部分双键性质，构成肽键的六个原子近似共平面","C":"典型的离子键","D":"由氢键维持的环状结构","E":"酯键的一种"},"answer":["B"],"rationale":"肽键中氮的孤对电子与羰基形成 p-π 共轭，使 C—N 键具有约 40% 的双键性质而不能自由旋转；Cα—CO—NH—Cα 六个原子近似共平面，这一平面性是蛋白质二级结构（α-螺旋、β-折叠）形成的基础。","expl":{"A":"共轭使 C—N 键旋转受阻，可自由旋转的是 Cα—CO 与 N—Cα 单键。","B":"正确，部分双键性质与平面性是肽键最重要的结构特征。","C":"肽键是共价键，不是离子键。","D":"氢键维持的是二级结构，肽键本身是共价酰胺键。","E":"肽键属酰胺键，与酯键不同。"},"id":"org15_q07","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":7},{"type":"A","stem":"组成蛋白质的天然α-氨基酸，其构型特点是","options":{"A":"除甘氨酸外均为 L 型","B":"全部为 D 型","C":"全部为 L 型","D":"多以 D、L 外消旋体形式存在","E":"甘氨酸为 L 型"},"answer":["A"],"rationale":"天然蛋白质中的α-氨基酸除甘氨酸外都含手性碳，其构型均为 L 型（与 L-甘油醛相联系）；甘氨酸α-碳上连两个氢，无手性，谈不上 D、L 构型，故不能说“全部为 L 型”。","expl":{"A":"正确，天然α-氨基酸（甘氨酸除外）都属 L 型。","B":"D 型氨基酸主要存在于细菌细胞壁肽聚糖等少数结构中。","C":"“全部为 L 型”不严密，甘氨酸无手性碳，不能称 L 型。","D":"天然氨基酸并非外消旋体，生物合成的氨基酸具有光学纯度。","E":"甘氨酸无手性碳，不存在 L 型之说。"},"id":"org15_q08","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":8},{"type":"A","stem":"脯氨酸与茚三酮试剂共热，生成的颜色是","options":{"A":"蓝紫色","B":"红色","C":"绿色","D":"无色","E":"黄色"},"answer":["E"],"rationale":"大多数α-氨基酸与茚三酮共热生成蓝紫色化合物；脯氨酸（及羟脯氨酸）属亚氨基酸，氧化脱羧后生成黄色产物，可据此与其他氨基酸区分。多肽和蛋白质也有茚三酮呈色反应。","expl":{"A":"蓝紫色是甘氨酸、丙氨酸等多数α-氨基酸的显色。","B":"红色并非茚三酮反应的典型颜色。","C":"绿色不是该反应的显色结果。","D":"脯氨酸能与茚三酮反应，只是产物颜色不同，并非无色。","E":"正确，脯氨酸为亚氨基酸，与茚三酮显黄色。"},"id":"org15_q09","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":9},{"type":"A","stem":"测定多肽链 N 端氨基酸常用的试剂 2,4-二硝基氟苯，又称为","options":{"A":"桑格（Sanger）试剂","B":"茚三酮","C":"溴甲酚绿","D":"亚硝酸","E":"甲醛"},"answer":["A"],"rationale":"2,4-二硝基氟苯（Sanger 试剂）与多肽 N 端游离氨基反应，生成黄色的 N-2,4-二硝基苯基衍生物；水解后经层析鉴定该衍生物即可确定 N 端氨基酸，是经典的多肽测序方法之一。","expl":{"A":"正确，2,4-二硝基氟苯即 Sanger 试剂，用于标记 N 端氨基酸。","B":"茚三酮用于氨基酸的显色与定量，不能标记 N 端。","C":"溴甲酚绿是酸碱指示剂，与 N 端测定无关。","D":"亚硝酸与伯氨基反应放出氮气，用于测定氨基氮（范斯莱克法）。","E":"甲醛用于氨基酸的甲醛滴定，使氨基酸性增强便于滴定。"},"id":"org15_q10","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":10},{"type":"A","stem":"向蛋白质溶液中加入饱和硫酸铵溶液使蛋白质沉淀，这一过程的实质是","options":{"A":"蛋白质变性，肽键断裂","B":"盐析，蛋白质空间构象未被破坏，稀释后可重新溶解","C":"重金属盐引起的不可逆沉淀","D":"蛋白质水解为氨基酸","E":"蛋白质被氧化"},"answer":["B"],"rationale":"高浓度中性盐（如硫酸铵）夺取蛋白质表面的水化层并中和其电荷，使蛋白质颗粒聚集沉淀，即盐析。盐析只改变溶解状态、不破坏空间构象，属可逆过程，除盐后蛋白质可恢复溶解度和活性，故常用于蛋白质的分离纯化。","expl":{"A":"盐析不破坏肽键和空间构象，与变性有本质区别。","B":"正确，盐析可逆，是分离纯化蛋白质的常用手段。","C":"醋酸铅、氯化汞等重金属盐才与蛋白质结合发生不可逆沉淀。","D":"水解需酸、碱或酶参与，单纯加盐不引起肽键水解。","E":"盐析过程中不发生氧化还原反应。"},"id":"org15_q11","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":11},{"type":"A","stem":"蛋白质的碱性稀硫酸铜溶液显紫红色，该显色反应称为","options":{"A":"茚三酮反应","B":"米伦反应","C":"双缩脲反应","D":"黄色反应","E":"坂口反应"},"answer":["C"],"rationale":"蛋白质（含两个以上肽键）在碱性溶液中与稀硫酸铜作用生成紫红色配合物，即双缩脲反应，可用于蛋白质的定性检验和含量测定，肽键数目越多显色越深。","expl":{"A":"茚三酮反应是氨基酸的显色反应，呈蓝紫色。","B":"米伦反应是含酚羟基（酪氨酸）蛋白质的显色反应。","C":"正确，双缩脲反应检验肽键，呈紫红色。","D":"黄色反应是含苯环氨基酸（如酪氨酸、苯丙氨酸）与浓硝酸的显色。","E":"坂口反应用于检验精氨酸的胍基。"},"id":"org15_q12","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":12}]},{"title":"第十六章 杂环化合物","questions":[{"type":"A","stem":"下列含氮化合物中碱性最强的是","options":{"A":"吡咯","B":"吡啶","C":"苯胺","D":"氨","E":"哌啶"},"answer":["E"],"rationale":"哌啶是饱和六元含氮杂环，氮上孤对电子不参与共轭且受烷基给电子作用，碱性接近脂肪胺，故最强。","expl":{"A":"吡咯的孤对电子参与环上共轭，几乎不显碱性，是最弱者。","B":"吡啶氮上孤对在 sp2 轨道中不参与共轭，碱性弱于脂肪胺。","C":"苯胺孤对与苯环共轭，碱性弱于吡啶和脂肪胺。","D":"氨的碱性弱于哌啶这类脂肪族仲胺。","E":"正确，哌啶为饱和杂环，氮上孤对易给出，碱性最强。"},"id":"org16_q01","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":1},{"type":"A","stem":"吡咯分子中氮原子的孤对电子","options":{"A":"决定其具有强碱性","B":"不参与环上共轭","C":"参与环上共轭，使环具有芳香性","D":"使氮原子带正电荷","E":"对环的稳定性没有影响"},"answer":["C"],"rationale":"吡咯氮上孤对电子处于 p 轨道，与四个碳的 p 轨道形成 6 电子的闭合共轭体系，故吡咯具有芳香性。","expl":{"A":"孤对参与芳香体系后难以给出，吡咯碱性极弱。","B":"孤对恰恰参与共轭，否则吡咯不可能具有芳香性。","C":"正确，孤对参与共轭形成 6 个 π 电子的芳香体系。","D":"孤对参与共轭不使氮带正电，吡咯整体为中性分子。","E":"孤对共轭正是吡咯具有芳香性和稳定性的原因。"},"id":"org16_q02","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":2},{"type":"A","stem":"下列化合物中最容易发生亲电取代反应的是","options":{"A":"苯","B":"吡啶","C":"吡咯","D":"硝基苯","E":"氯苯"},"answer":["C"],"rationale":"吡咯环上五个原子共提供 6 个 π 电子，电子云密度高于苯，故比苯更易发生亲电取代，且主要发生在 2 位。","expl":{"A":"苯的电子云密度低于吡咯，活性不及吡咯。","B":"吡啶氮电负性大，环上电子云密度低，亲电取代困难。","C":"正确，吡咯环富电子，是最易发生亲电取代的化合物。","D":"硝基苯严重缺电子，亲电取代非常困难。","E":"氯苯因氯的吸电子作用而钝化，活性低于苯。"},"id":"org16_q03","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":3},{"type":"A","stem":"吡啶发生亲电取代反应时，取代基主要进入","options":{"A":"2 位","B":"3 位","C":"4 位","D":"氮原子上","E":"不发生取代"},"answer":["B"],"rationale":"吡啶亲电取代的中间体在 3 位取代时正电荷不落在电负性大的氮上，能量更低，故主要进入 3 位。","expl":{"A":"2 位取代的中间体正电荷可落在氮原子上，能量较高，产物较少。","B":"正确，3 位取代的中间体最稳定，是主要产物位置。","C":"4 位取代同样使正电荷分布不利，比例低于 3 位。","D":"亲电试剂进攻的是环上碳原子，不取代氮原子。","E":"吡啶在强烈条件下仍可发生亲电取代，只是较难。"},"id":"org16_q04","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":4},{"type":"A","stem":"吡啶与氨基钠在加热条件下反应，生成的主要产物是","options":{"A":"3-氨基吡啶","B":"4-氨基吡啶","C":"吡咯","D":"2-氨基吡啶","E":"不反应"},"answer":["D"],"rationale":"这是齐齐巴宾反应，氨基钠作为亲核试剂进攻吡啶的 2 位，氢化钠离去后生成 2-氨基吡啶，属亲核取代。","expl":{"A":"3 位是亲电取代的有利位置，亲核取代主要在 2 位。","B":"4 位亲核取代比例低于 2 位，不是主要产物。","C":"反应不改变环的大小和类型，不会生成吡咯。","D":"正确，氨基钠进攻 2 位，生成 2-氨基吡啶。","E":"吡啶可发生亲核取代，该反应能顺利进行。"},"id":"org16_q05","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":5},{"type":"A","stem":"呋喃在强酸性条件下容易发生","options":{"A":"还原为醇","B":"亲电取代","C":"氧化为酸","D":"开环聚合","E":"不发生反应"},"answer":["D"],"rationale":"呋喃环上氧的孤对参与共轭，遇强酸易质子化而破坏芳香性，导致开环并进一步聚合，故呋喃不耐强酸。","expl":{"A":"还原需催化加氢条件，与强酸无关。","B":"亲电取代在温和条件下进行，强酸条件下以开环为主。","C":"强酸不是氧化剂，主要引起开环而非氧化成酸。","D":"正确，强酸使呋喃质子化失去芳香性，进而开环聚合。","E":"呋喃对强酸敏感，会发生明显反应。"},"id":"org16_q06","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":6},{"type":"A","stem":"组氨酸分子中所含的杂环是","options":{"A":"吡啶环","B":"噻吩环","C":"咪唑环","D":"呋喃环","E":"嘧啶环"},"answer":["C"],"rationale":"组氨酸的侧链含咪唑环，咪唑环中两个氮的碱性不同，在酶的催化中常起酸碱催化作用。","expl":{"A":"组氨酸侧链不是六元含氮的吡啶环。","B":"噻吩环含硫，组氨酸分子中不含硫。","C":"正确，组氨酸侧链含五元咪唑环，是重要的药效基团。","D":"呋喃环含氧，组氨酸分子中不含呋喃环。","E":"嘧啶是六元二氮杂环，组氨酸侧链为五元咪唑环。"},"id":"org16_q07","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":7},{"type":"A","stem":"嘌呤环是由下列哪两个环稠合而成的","options":{"A":"嘧啶环和咪唑环","B":"吡啶环和吡咯环","C":"苯环和嘧啶环","D":"呋喃环和吡咯环","E":"两个嘧啶环"},"answer":["A"],"rationale":"嘌呤由一个六元嘧啶环与一个五元咪唑环稠合而成，是核酸中腺嘌呤和鸟嘌呤的母体结构。","expl":{"A":"正确，嘌呤由嘧啶环与咪唑环稠合构成稠杂环。","B":"吡啶与吡咯稠合不是嘌呤的骨架。","C":"嘌呤不含苯环，其六元环为嘧啶环。","D":"呋喃与吡咯稠合的结构与嘌呤不符。","E":"嘌呤由一个六元环和一个五元环稠合，不是两个六元环。"},"id":"org16_q08","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":8},{"type":"X","stem":"关于吡啶，下列说法正确的有","options":{"A":"具有芳香性","B":"氮原子为 sp2 杂化，孤对电子处于 sp2 轨道且不参与环上共轭","C":"碱性强于吡咯","D":"亲电取代反应比苯困难","E":"氮原子上的孤对电子参与环上共轭"},"answer":["A","B","C","D"],"rationale":"吡啶为芳香杂环，氮上孤对在 sp2 轨道中不参与共轭故碱性弱而可质子化，环缺电子使亲电取代困难，故 E 错误。","expl":{"A":"正确，吡啶含 6 个 π 电子的闭合共轭体系，具有芳香性。","B":"正确，孤对位于 sp2 轨道，与环平面垂直，不参与 π 体系。","C":"正确，吡咯孤对参与芳香体系而难以给出，吡啶碱性强于吡咯。","D":"正确，氮的吸电子作用使环缺电子，亲电取代比苯难。","E":"错误，若孤对参与共轭则吡啶不可能具有芳香性且碱性会极弱。"},"id":"org16_q09","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":9},{"type":"A","stem":"呋喃、吡咯和噻吩三者中，芳香性最强的是","options":{"A":"呋喃","B":"吡咯","C":"噻吩","D":"三者完全相同","E":"无法比较"},"answer":["C"],"rationale":"杂原子 p 轨道与碳的 2p 轨道大小越接近重叠越好，芳香性越弱；硫用 3p 轨道重叠较差，故噻吩芳香性最强。","expl":{"A":"呋喃中氧的 2p 轨道与碳 2p 大小匹配，电子云集中在氧上，芳香性最弱。","B":"吡咯居中，氮的 2p 与碳 2p 匹配程度高于硫的 3p，芳香性弱于噻吩。","C":"正确，噻吩的硫用 3p 轨道参与共轭，重叠较差，芳香性在五元杂环中最强。","D":"三者的杂原子不同，芳香性存在明显差异，不可能完全相同。","E":"三者芳香性有明确强弱顺序，可以比较。"},"id":"org16_q10","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":10},{"type":"A","stem":"下列杂环化合物发生亲电取代反应的活性由强到弱的顺序，正确的是","options":{"A":"吡咯 > 呋喃 > 噻吩 > 吡啶","B":"吡啶 > 吡咯 > 呋喃 > 噻吩","C":"呋喃 > 吡咯 > 噻吩 > 吡啶","D":"噻吩 > 呋喃 > 吡咯 > 吡啶","E":"吡啶 > 噻吩 > 呋喃 > 吡咯"},"answer":["A"],"rationale":"五元杂环中杂原子的孤对电子参与共轭，环上电子云密度高于苯，故亲电取代比苯容易；共轭程度按 N>O>S 递减，活性为吡咯>呋喃>噻吩。吡啶的氮原子电负性大并使环缺电子，亲电取代比苯困难，是四者中最不活泼的。","expl":{"A":"正确，富电子五元杂环都比苯活泼，其中吡咯最活泼，吡啶最不活泼。","B":"吡啶环缺电子，亲电取代最困难，不可能居首。","C":"呋喃的共轭程度弱于吡咯，活性应次于吡咯。","D":"噻吩中硫的 3p 轨道与碳的 2p 轨道匹配较差，共轭最弱，活性低于呋喃和吡咯。","E":"吡咯是最活泼的，不可能排在末位。"},"id":"org16_q11","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":11},{"type":"A","stem":"吲哚发生亲电取代反应时，取代基主要进入的位置是","options":{"A":"1 位（氮原子）","B":"3 位","C":"2 位","D":"苯环的 5 位","E":"不发生亲电取代"},"answer":["B"],"rationale":"吲哚可看作吡咯与苯的稠环，亲电取代发生在富电子的吡咯环上。进攻 3 位生成的中间体仍保留完整的苯环芳香结构，能量最低，故 3 位取代为主；3 位被占据时才进入 2 位。","expl":{"A":"氮上的氢只在强碱中才被取代，亲电试剂进攻的是碳原子。","B":"正确，3 位取代的中间体能保留苯环芳香结构，最为稳定。","C":"进攻 2 位会破坏苯环的芳香性，不如 3 位有利。","D":"苯环部分电子云密度低于吡咯环，亲电取代优先发生在吡咯环上。","E":"吲哚是富电子杂环，亲电取代很容易进行。"},"id":"org16_q12","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":12},{"type":"A","stem":"下列化合物中，属于嘧啶衍生物的是","options":{"A":"吲哚","B":"咪唑","C":"嘌呤","D":"尿嘧啶","E":"噻吩"},"answer":["D"],"rationale":"尿嘧啶是含两个氮原子的六元杂环（嘧啶）的二酮衍生物，与胸腺嘧啶、胞嘧啶同属嘧啶碱基；嘌呤则由嘧啶环与咪唑环稠合而成，属于双环体系，二者不可混淆。","expl":{"A":"吲哚是苯与吡咯稠合而成的环系。","B":"咪唑是含两个氮原子的五元杂环，不是六元嘧啶。","C":"嘌呤是嘧啶与咪唑稠合的双环体系，比嘧啶多一个环。","D":"正确，尿嘧啶是嘧啶（2,4-二羟基嘧啶）的衍生物。","E":"噻吩是含硫的五元杂环。"},"id":"org16_q13","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":13},{"type":"A","stem":"喹啉发生亲电取代反应时，取代基主要进入的位置是","options":{"A":"吡啶环的 2 位","B":"吡啶环的 3 位","C":"吡啶环的 4 位","D":"氮原子上","E":"苯环的 5 位或 8 位"},"answer":["E"],"rationale":"喹啉由苯环与吡啶环稠合而成，吡啶环因氮的吸电子作用而钝化，亲电取代发生在电子云密度较高的苯环上，主要在 5 位和 8 位；这与吲哚、吡咯等富电子杂环的取向规律相反。","expl":{"A":"吡啶环缺电子，2 位主要发生亲核取代（如齐齐巴宾反应）。","B":"3 位是吡啶本身亲电取代的位置，但在喹啉中吡啶环被钝化。","C":"4 位处于吡啶环，电子云密度低于苯环部分。","D":"氮原子不参与亲电取代，其孤对电子不参与共轭。","E":"正确，苯环部分较富电子，取代主要发生在 5 位和 8 位。"},"id":"org16_q14","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":14},{"type":"X","stem":"关于呋喃、吡咯和噻吩，下列说法正确的有","options":{"A":"三者都是含一个杂原子的五元环，均符合休克尔规则而具有芳香性","B":"杂原子均以 sp2 杂化，其孤对电子参与环上的共轭体系","C":"三者的亲电取代反应都比苯容易进行","D":"三者中噻吩因含硫原子而水溶性最好","E":"呋喃和吡咯遇强酸易发生开环或聚合"},"answer":["A","B","C","E"],"rationale":"呋喃、吡咯、噻吩都是 6π 电子的富电子五元杂环，杂原子 sp2 杂化、孤对电子参与共轭，环上电子云密度高于苯，故亲电取代比苯容易；但孤对电子参与共轭后碱性极弱，且呋喃、吡咯对强酸敏感，质子化后芳香性被破坏，易开环或聚合。","expl":{"A":"正确，三者均为 4n+2（n=1）的 6π 体系，具有芳香性。","B":"正确，氧、氮、硫的孤对电子都参与形成 6π 共轭体系。","C":"正确，环上电子云密度高于苯，亲电取代更易进行。","D":"错误，三者几乎都不溶于水，含硫并不使其水溶性变好。","E":"正确，强酸使呋喃、吡咯质子化并破坏芳香性，导致开环或聚合。"},"id":"org16_q15","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":15}]},{"title":"第十七章 糖类化合物","questions":[{"type":"A","stem":"葡萄糖的开链结构中含有","options":{"A":"五个羟基和一个醛基","B":"四个羟基和一个酮基","C":"六个羟基","D":"不含醛基的多羟基化合物","E":"三个羟基和一个羧基"},"answer":["A"],"rationale":"葡萄糖是己醛糖，开链结构中有 4 个手性碳上的羟基和 1 个伯羟基共 5 个羟基，以及 1 个醛基。","expl":{"A":"正确，己醛糖开链含五个羟基和一个醛基，C1 为醛基。","B":"酮基结构对应的是果糖，不是葡萄糖。","C":"葡萄糖除五个羟基外还有醛基，不是六个羟基。","D":"葡萄糖是醛糖，开链结构中确实含醛基。","E":"葡萄糖没有羧基，羟基数目也多于三个。"},"id":"org17_q01","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":1},{"type":"A","stem":"葡萄糖水溶液产生变旋现象，其原因是","options":{"A":"葡萄糖被氧化","B":"葡萄糖发生分解","C":"形成环状半缩醛，α 与 β 异头物在溶液中互变并达成平衡","D":"葡萄糖发生聚合","E":"没有合理解释"},"answer":["C"],"rationale":"葡萄糖在水溶液中形成六元环状半缩醛，产生 α 和 β 两种异头物，二者通过开链式互变并达到平衡，故旋光度改变。","expl":{"A":"变旋是构型互变，不是氧化反应。","B":"葡萄糖在溶液中稳定，不发生分解。","C":"正确，α 与 β 异头物经开链式互变达平衡，旋光度随之变化。","D":"聚合会使体系变粘稠，与旋光度逐渐恒定无关。","E":"变旋现象有明确的环状半缩醛机理解释。"},"id":"org17_q02","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":2},{"type":"A","stem":"下列糖中不属于还原糖的是","options":{"A":"葡萄糖","B":"果糖","C":"麦芽糖","D":"蔗糖","E":"乳糖"},"answer":["D"],"rationale":"蔗糖的两个异头碳都参与苷键形成，无游离的半缩醛羟基，不能开环变醛基，故为非还原糖。","expl":{"A":"葡萄糖有游离半缩醛羟基，是还原糖。","B":"果糖为酮糖，可异构化为醛糖，属还原糖。","C":"麦芽糖有一个游离半缩醛羟基，是还原糖。","D":"正确，蔗糖两端异头碳均参与成苷，无还原性。","E":"乳糖保留一个游离半缩醛羟基，是还原糖。"},"id":"org17_q03","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":3},{"type":"A","stem":"葡萄糖和果糖分别与过量苯肼反应，生成的产物是","options":{"A":"两种不同的糖脎","B":"不反应","C":"醇类化合物","D":"羧酸类化合物","E":"同一种糖脎"},"answer":["E"],"rationale":"葡萄糖与果糖只在 C1、C2 的羰基位置不同，成脎后该部分结构相同，故生成同一种糖脎，可用于鉴定。","expl":{"A":"二者成脎后 C1 与 C2 结构一致，产物相同而非不同。","B":"醛糖和酮糖都能与苯肼反应生成糖脎。","C":"糖脎是含苯腙结构的衍生物，不是醇。","D":"成脎不是氧化反应，不生成羧酸。","E":"正确，葡萄糖与果糖生成同一种糖脎，说明二者仅 C1、C2 有别。"},"id":"org17_q04","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":4},{"type":"A","stem":"蔗糖分子中连接两个单糖的苷键是","options":{"A":"α-1,2-苷键","B":"β-1,4-苷键","C":"α-1,4-苷键","D":"β-1,2-苷键","E":"α-1,6-苷键"},"answer":["A"],"rationale":"蔗糖由 α-D-葡萄糖的 C1 与 β-D-果糖的 C2 通过氧相连，故为 α-1,2-苷键，两端异头碳均被占用。","expl":{"A":"正确，葡萄糖 C1 与果糖 C2 成苷，属 α-1,2-苷键。","B":"β-1,4-苷键是纤维素中的连接方式，不是蔗糖。","C":"α-1,4-苷键是淀粉和麦芽糖中的连接方式。","D":"蔗糖中参与成苷的是葡萄糖的 C1 而非 C2。","E":"α-1,6-苷键是支链淀粉分支处的连接方式。"},"id":"org17_q05","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":5},{"type":"A","stem":"淀粉与纤维素在结构上的主要区别是","options":{"A":"二者结构完全相同","B":"淀粉为 α-1,4-苷键，纤维素为 β-1,4-苷键","C":"淀粉为 β-1,4-苷键","D":"纤维素为 α-1,4-苷键","E":"二者没有区别"},"answer":["B"],"rationale":"淀粉由 α-D-葡萄糖以 α-1,4-苷键连接，纤维素由 β-D-葡萄糖以 β-1,4-苷键连接，苷键构型不同导致性质差异。","expl":{"A":"二者的苷键构型不同，结构并不相同。","B":"正确，淀粉为 α-1,4-苷键，纤维素为 β-1,4-苷键，这是本质区别。","C":"淀粉的苷键为 α 构型，不是 β 构型。","D":"纤维素的苷键为 β 构型，不是 α 构型。","E":"二者在苷键构型、溶解性和消化性上均有明显区别。"},"id":"org17_q06","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":6},{"type":"A","stem":"决定 D-葡萄糖属于 D 型构型的依据是","options":{"A":"C1 上半缩醛羟基的朝向","B":"C2 上羟基的朝向","C":"C6 上伯醇基的位置","D":"距离羰基最远的手性碳（C5）上羟基的朝向","E":"分子是否能使偏振光右旋"},"answer":["D"],"rationale":"糖的 D、L 构型以距离羰基最远的手性碳为基准：该碳上羟基在 Fischer 投影式右侧者为 D 型，在左侧者为 L 型。葡萄糖的基准碳是 C5，其羟基在右，故为 D-葡萄糖；旋光方向（+/−）与 D、L 构型并无必然联系。","expl":{"A":"C1 的朝向只决定 α 或 β 端基异构，不决定 D、L 构型。","B":"C2 的构型决定它是葡萄糖还是甘露糖（C2 差向异构）。","C":"C6 是伯醇碳，不含手性，不能作为 D、L 判断依据。","D":"正确，基准碳 C5 上羟基在右即为 D 型。","E":"D/L 是构型标记，与实测旋光方向不一定一致。"},"id":"org17_q07","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":7},{"type":"A","stem":"α-D-葡萄糖与β-D-葡萄糖之间的关系是","options":{"A":"对映异构体","B":"端基异构体（非对映体）","C":"构造异构体","D":"顺反异构体","E":"同一化合物"},"answer":["B"],"rationale":"α 与 β 两种环状异构体只在 C1（端基碳）上的羟基构型不同，其余手性碳的构型完全相同，属于端基异构体，是互不为镜像的非对映体；二者在溶液中通过开链醛式相互转化并达到平衡，因此表现出变旋现象。","expl":{"A":"对映体要求所有手性碳构型都相反，二者只有 C1 不同。","B":"正确，仅在端基碳上不同的异构体称为端基异构体（异头物）。","C":"二者的原子连接顺序相同，不是构造异构。","D":"顺反异构通常描述双键或环上的几何关系，不用于端基碳。","E":"两者的熔点、比旋光度都不同，不是同一化合物。"},"id":"org17_q08","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":8},{"type":"A","stem":"葡萄糖与溴水反应，生成的主要产物是","options":{"A":"葡萄糖酸","B":"葡萄糖二酸","C":"葡萄糖醛酸","D":"山梨醇","E":"果糖"},"answer":["A"],"rationale":"溴水是温和氧化剂，只能把葡萄糖 C1 的醛基氧化为羧基，得到葡萄糖酸，不氧化仲羟基；若用浓硝酸则 C1 与 C6 均被氧化生成葡萄糖二酸，催化加氢则还原得到山梨醇。","expl":{"A":"正确，溴水只氧化醛基，产物为葡萄糖酸。","B":"葡萄糖二酸需用浓硝酸把 C1 和 C6 同时氧化。","C":"葡萄糖醛酸是只氧化 C6 伯羟基的产物，需酶或保护其他基团。","D":"山梨醇是葡萄糖催化加氢还原的产物。","E":"果糖是酮糖，不能由葡萄糖氧化得到。"},"id":"org17_q09","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":9},{"type":"A","stem":"果糖在水溶液中主要以环状结构存在，其环状结构是","options":{"A":"六元吡喃环状半缩醛","B":"五元吡咯环状半缩醛","C":"六元环状半缩酮","D":"五元环状半缩醛","E":"五元呋喃环状半缩酮"},"answer":["E"],"rationale":"果糖是己酮糖，C2 羰基与 C5（或 C6）上的羟基成环：与 C5 羟基成环形成五元呋喃环状半缩酮，是果糖在水溶液中的主要形式，也可形成少量六元吡喃环；而葡萄糖是醛糖，主要形成六元吡喃环状半缩醛。","expl":{"A":"六元吡喃环是葡萄糖等醛糖的主要形式。","B":"吡咯是含氮杂环，与糖的环状结构无关。","C":"六元吡喃环只是果糖的次要形式，主要形式是五元环。","D":"果糖是酮糖，成环后生成半缩酮而不是半缩醛。","E":"正确，果糖与 C5 羟基成五元呋喃环状半缩酮。"},"id":"org17_q10","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":10},{"type":"A","stem":"蔗糖在稀酸或蔗糖酶作用下完全水解，生成的产物是","options":{"A":"两分子葡萄糖","B":"两分子果糖","C":"一分子葡萄糖和一分子果糖","D":"葡萄糖和半乳糖","E":"不发生水解"},"answer":["C"],"rationale":"蔗糖由 α-D-葡萄糖的 C1 与 β-D-果糖的 C2 通过 α-1,2-苷键连接，水解后生成等量的葡萄糖和果糖。由于果糖的左旋度大于葡萄糖的右旋度，水解过程中旋光由右旋变为左旋，所得混合物称为转化糖。","expl":{"A":"两分子葡萄糖是麦芽糖水解的产物。","B":"蔗糖是二糖，水解必然得到两种不同的单糖。","C":"正确，苷键水解后得到一分子葡萄糖和一分子果糖。","D":"半乳糖来自乳糖，不是蔗糖的组成单元。","E":"蔗糖是二糖，可被酸或酶水解。"},"id":"org17_q11","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":11},{"type":"X","stem":"关于单糖的变旋现象，下列说法正确的有","options":{"A":"变旋是 α 与 β 端基异构体通过开链醛式（酮式）相互转化引起的","B":"新配制的 D-葡萄糖溶液放置后旋光度逐渐改变，最后趋于恒定","C":"达到平衡时 β-D-葡萄糖的比例高于 α-D-葡萄糖","D":"形成糖苷后，端基碳被固定，不再发生变旋","E":"变旋只发生在酮糖中，醛糖不会变旋"},"answer":["A","B","C","D"],"rationale":"变旋的实质是端基碳构型经开链形式互变：α 与 β 异构体的比例随平衡而改变，溶液旋光度随之漂移直至恒定。葡萄糖平衡混合物中 β 型约占 64%、α 型约占 36%；成苷后端基碳成为缩醛（缩酮），无开链形式，故不再变旋。","expl":{"A":"正确，开链醛式（或酮式）是 α、β 互变的必经中间体。","B":"正确，新配溶液旋光度漂移正是变旋的表现。","C":"正确，平衡时 β 型约占 64%，α 型约占 36%。","D":"正确，糖苷的端基碳已形成缩醛（缩酮），不能再开环。","E":"错误，醛糖和酮糖都能发生变旋。"},"id":"org17_q12","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":12}]},{"title":"第十八章 萜类和甾体化合物","questions":[{"type":"A","stem":"萜类化合物分子中的基本结构单位是","options":{"A":"异戊二烯单位","B":"葡萄糖单位","C":"氨基酸单位","D":"苯环单位","E":"甾核单位"},"answer":["A"],"rationale":"萜类化合物可看作由两个或多个异戊二烯单位首尾相连构成，即遵循异戊二烯规则，故基本单位为异戊二烯。","expl":{"A":"正确，萜类由异戊二烯单位以头尾方式连接而成。","B":"葡萄糖是糖类的结构单位，与萜类无关。","C":"氨基酸是蛋白质的结构单位，不构成萜类骨架。","D":"苯环是芳香族的基本结构，萜类骨架一般不含苯环。","E":"甾核是甾体化合物的骨架，不是萜类的基本单位。"},"id":"org18_q01","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":1},{"type":"A","stem":"甾体化合物的基本骨架是","options":{"A":"苯并芘","B":"蒽","C":"环戊烷多氢菲","D":"萘","E":"吡啶"},"answer":["C"],"rationale":"甾体化合物由三个六元环和一个五元环稠合而成，这一骨架称为环戊烷多氢菲，是甾体化合物的共同结构特征。","expl":{"A":"苯并芘是稠环芳烃，不是甾体骨架。","B":"蒽是三个苯环直线稠合的芳烃，与甾体骨架不符。","C":"正确，三个六元环与一个五元环稠合成环戊烷多氢菲骨架。","D":"萘是两个苯环稠合的芳烃，不是甾体骨架。","E":"吡啶是六元含氮杂环，与甾体骨架无关。"},"id":"org18_q02","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":2},{"type":"A","stem":"天然油脂的主要成分是","options":{"A":"高级脂肪酸的甘油酯","B":"高级脂肪醇","C":"游离脂肪酸","D":"磷脂","E":"甾醇"},"answer":["A"],"rationale":"油脂是甘油与三分子高级脂肪酸形成的三酰甘油，属酯类化合物，故主要成分为高级脂肪酸的甘油酯。","expl":{"A":"正确，油脂即甘油三酯，由甘油与高级脂肪酸酯化而成。","B":"高级脂肪醇是蜡的主要成分，不是油脂。","C":"游离脂肪酸在油脂中含量很少，不是主要成分。","D":"磷脂是含磷的类脂，与油脂是不同类别。","E":"甾醇属甾体化合物，不是油脂的主要成分。"},"id":"org18_q03","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":3},{"type":"A","stem":"下列结构特征中，为强心苷强心活性所必需的是","options":{"A":"C17 位连五元不饱和内酯环，同时 C14 位有 β-羟基","B":"C17 位连乙酰基，同时 C3 位有 β-羟基","C":"A 环芳香化，同时 C3 位为酚羟基","D":"C11 位有 β-羟基，同时 C17 位连—COCH2OH","E":"C5 与 C6 之间成双键，同时 C17 位连异辛基侧链"},"answer":["A"],"rationale":"强心苷苷元属甾体化合物，其 C17 必须连五元不饱和内酯环、C14 必须有 β-羟基，二者为强心活性所必需，缺一则活性显著下降；糖链部分只影响水溶性、吸收与作用强度。","expl":{"A":"正确。C17 不饱和内酯环与 C14β-羟基同为活性必需结构。","B":"C17 连乙酰基是黄体酮等孕激素的特征，并非强心苷。","C":"A 环芳香且 C3 为酚羟基是雌二醇等雌激素的特征。","D":"C11β-羟基与 C17—COCH2OH 是氢化可的松等糖皮质激素的特征。","E":"C5 与 C6 间双键及 C17 异辛基侧链是胆固醇的结构特征。"},"id":"org18_q04","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":4},{"type":"A","stem":"按异戊二烯规则，单萜分子中含有的异戊二烯单位数是","options":{"A":"1 个","B":"2 个","C":"3 个","D":"4 个","E":"6 个"},"answer":["B"],"rationale":"萜类按分子中异戊二烯单位（C5H8）的数目分类：单萜 2 个单位（C10）、倍半萜 3 个（C15）、二萜 4 个（C20）、三萜 6 个（C30）、四萜 8 个（C40）。故单萜含 2 个异戊二烯单位。","expl":{"A":"一个异戊二烯单位只相当于半萜（C5），如异戊烯醇。","B":"正确，单萜含 2 个异戊二烯单位，共 10 个碳。","C":"3 个单位是倍半萜（C15），如法尼醇。","D":"4 个单位是二萜（C20），如维生素 A。","E":"6 个单位是三萜（C30），如齐墩果酸。"},"id":"org18_q05","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":5},{"type":"A","stem":"下列化合物中，属于双环单萜的是","options":{"A":"柠檬烯","B":"薄荷醇","C":"香叶醇","D":"樟脑","E":"法尼醇"},"answer":["D"],"rationale":"单萜按碳骨架分为链状、单环和双环三类：香叶醇为链状单萜，柠檬烯、薄荷醇为单环单萜，樟脑（莰酮）、蒎烯、龙脑为双环单萜；法尼醇含 15 个碳，属倍半萜，不属于单萜。","expl":{"A":"柠檬烯具有对孟烷骨架，是单环单萜。","B":"薄荷醇是单环单萜醇，存在于薄荷油中。","C":"香叶醇是无环（链状）单萜。","D":"正确，樟脑含双环莰烷骨架，属双环单萜酮。","E":"法尼醇含 15 个碳，是倍半萜。"},"id":"org18_q06","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":6},{"type":"A","stem":"甾体化合物的母核由哪些环稠合组成","options":{"A":"四个六元环","B":"三个六元环","C":"三个六元环和一个五元环","D":"两个六元环和一个五元环","E":"两个六元环和两个五元环"},"answer":["C"],"rationale":"甾体母核为环戊烷多氢菲，由 A、B、C 三个环己烷型六元环稠合一个 D 环戊烷型五元环构成，共 17 个碳原子；甾体化合物的命名和编号都以此骨架为准。","expl":{"A":"四个六元环中没有五元 D 环，不是甾体骨架。","B":"缺少五元 D 环，甾体母核是四环体系。","C":"正确，环戊烷多氢菲即三个六元环加一个五元环。","D":"环数不足，甾体母核共有四个稠环。","E":"甾体母核中只有一个五元环，即 D 环。"},"id":"org18_q07","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":7},{"type":"A","stem":"胆固醇被称为 Δ5-甾醇，是因为其结构中","options":{"A":"C5 位连有羟基","B":"C5 与 C6 之间有一个碳碳双键","C":"C5 位连有甲基","D":"C5 位为羰基","E":"C5 位连有异辛基侧链"},"answer":["B"],"rationale":"甾体化合物用 Δ 加位次表示双键位置，胆固醇在 C5—C6 之间有一个碳碳双键，故称 Δ5-甾醇。其 C3 位有β型羟基、C17 位连异辛基侧链，这些都与 Δ5 的含义无关。","expl":{"A":"胆固醇的羟基在 C3 位，不在 C5 位。","B":"正确，Δ5 表示 C5 与 C6 位置的双键。","C":"C5 位没有甲基，角甲基位于 C10 和 C13 位。","D":"C5 位没有羰基，胆固醇是 3-羟基甾醇。","E":"异辛基侧链连在 C17 位，不在 C5 位。"},"id":"org18_q08","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":8},{"type":"A","stem":"甾体化合物常用的显色反应是 Liebermann-Burchard 反应，其试剂是","options":{"A":"茚三酮溶液","B":"三氯化铁溶液","C":"斐林试剂","D":"溴水","E":"醋酐-浓硫酸"},"answer":["E"],"rationale":"Liebermann-Burchard 反应是甾体（含甾核或三萜）的通用显色反应：样品溶于醋酐后滴加浓硫酸，甾体经脱水、氧化等变化生成有色物质，颜色随结构不同呈红、紫、蓝、绿等，可用于甾体化合物的检识。","expl":{"A":"茚三酮用于氨基酸、多肽和蛋白质的显色。","B":"三氯化铁显色用于酚类和烯醇类化合物。","C":"斐林试剂用于检验还原性糖等还原性物质。","D":"溴水用于检验酚类和不饱和化合物。","E":"正确，醋酐-浓硫酸是甾体 LB 反应的典型试剂。"},"id":"org18_q09","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":9},{"type":"A","stem":"测定油脂的碘值，可以反映油脂的","options":{"A":"相对分子质量大小","B":"游离脂肪酸的含量","C":"不饱和程度（双键的多少）","D":"皂化的难易程度","E":"甘油的含量"},"answer":["C"],"rationale":"碘值指 100 g 油脂所能加成碘的克数，加成的碘量取决于分子中碳碳双键的数目，故碘值反映油脂的不饱和程度；游离脂肪酸含量用酸值表示，皂化难易用皂化值表示。","expl":{"A":"相对分子质量需用其他方法测定，碘值不能反映。","B":"游离脂肪酸含量由酸值反映，与碘值无关。","C":"正确，碘值越高说明双键越多、不饱和程度越大。","D":"皂化难易程度用皂化值衡量。","E":"甘油含量需另行测定，碘值只反映双键的多少。"},"id":"org18_q10","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":10},{"type":"A","stem":"下列化合物中，不属于甾体化合物的是","options":{"A":"胆固醇","B":"胆酸","C":"睾酮","D":"维生素 C","E":"氢化可的松"},"answer":["D"],"rationale":"胆固醇、胆酸（胆汁酸）、睾酮（性激素）和氢化可的松（肾上腺皮质激素）都具有环戊烷多氢菲母核，属甾体化合物；维生素 C 是含烯二醇内酯结构的糖酸衍生物，无甾体骨架。","expl":{"A":"胆固醇是动物细胞膜中的典型甾醇，含甾核。","B":"胆酸属胆汁酸，是甾体酸的代表。","C":"睾酮是雄性激素，属甾体激素。","D":"正确，维生素 C 为内酯类化合物，不含甾体骨架。","E":"氢化可的松是肾上腺皮质激素，属甾体。"},"id":"org18_q11","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":11},{"type":"X","stem":"关于甾体化合物，下列说法正确的有","options":{"A":"基本骨架为环戊烷多氢菲，含 17 个碳原子","B":"C3 位常连有羟基，可与糖形成苷","C":"胆汁酸、性激素、肾上腺皮质激素和强心苷均属甾体化合物","D":"其 A、B、C、D 四个环都是六元环","E":"甾体化合物都不含手性碳，因而没有旋光性"},"answer":["A","B","C"],"rationale":"甾体化合物以环戊烷多氢菲（三个六元环加一个五元环，共 17 个碳）为母核，C3 位常有羟基并可成苷，胆汁酸、性激素、皮质激素、强心苷等都属于甾体；甾核上多个手性碳使其具有旋光性，D 环是五元环。","expl":{"A":"正确，环戊烷多氢菲骨架共 17 个碳原子。","B":"正确，C3 羟基是甾醇、强心苷成苷的常见位置。","C":"正确，这几类天然成分都以甾核为骨架。","D":"错误，A、B、C 为六元环，D 环是五元环。","E":"错误，甾体分子含多个手性碳，通常具有旋光性。"},"id":"org18_q12","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":12}]}]};
